window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[13]=[{"i":32832,"n":"נאבל, יוסף מהלברשטט","k":"בעל תבור","bt":"תקצח","b":"תלמיד זקנו ר אהרן קוטנא, ותלמיד ר עזריאל הילדסהימר באיזנשטט. דרשן, רב בקלויז בהלברשטט-תרם. הו\"ל ספר זקנו עם הערות ממנו. פרסם ספרי דרוש.","s":"אוצר הרבנים 8450"},{"i":32833,"n":"נאבל, שלום מברזוב","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח.","s":"אוצר כתבי עת-לוין"},{"i":32834,"n":"נאבת, יהודה מאלגיר","dt":"תקסו - לפני","b":"רב בקצמטינא נזכר ב\"אשכבתא דרבנן\", ונזכר ב\"אהל דוד\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":32835,"n":"נאדאש, שמואל מירגין","f":"דוד","bt":"תקלט","bp":"נאדאש","dt":"תקצז - כ אייר","dp":"יערגין","b":"תלמיד החת\"ס. רב בוערבא-תקע, יערגין-תקעו. בנו ר אברהם שלמה זוננפלד מוערבא. נספד ע\"י החת\"ס. (דחה הצעות רבנות שונות וקיבל את יערגין בגלל קרבתה לחת\"ס - שאף הוא בחר את יערגין למקום מנוחה והיה מטייל עמו שם ביער).","s":"החת\"ס ותלמידיו"},{"i":32836,"n":"נאה, אברהם חיים","k":"בעל שיעורי תורה","r":"רב שכונת הבוכרים","bt":"ה'תרנ","bp":"חברון","dt":"תשיד - כ תמוז","dp":"ירושלים","b":"רב בבוכארה,חזר לירושלים","s":"אוצר הרבנים 1080; מידע אנ\"ש גליון 214; היברובוקס; יומא דהילולא","bk":[["קצות השלחן",""],["שיעורי תורה (ר\"ח נאה)",""],["פסקי הסידור - סידור הרב",""],["קונטרס השלחן",""],["קצות השלחן - הלכה לפי סדר שלחן ערוך הרב",""],["שיעור מקוה",""],["שיעורי ציון - השיעורים הנהוגים בירושלם",""],["שיעורי תורה",""],["שנות חיים - דיני ומנהגי השנה",""],["חנוך לנער",""],["פסקי הסידור",""],["קונטרס החליבה",""],["קונטרס הסידור",""],["קונטרס השיעורים",""],["שיעורי ציון",""],["שנות חיים",""],["קצות השולחן",""]],"e":"תר\"נ-תשי\"ד","rb":"ירושלים","co":{"b":"31.533333,35.095"}},{"i":32837,"n":"נאה, ברוך מאדרינופול","f":"מנחם","bt":"תרם","bp":"אדרינופול","b":"עסקן צבור באדרינופול, עלה לארץ-תרפד והתישב בתל אביב והיה מראשי התאחדות הספרדים שם. תרגם ספרים מעברית ללועזית.","s":"גאון-יהודי המזרח"},{"i":32838,"n":"נאה, מנחם מנדל","f":"משה צבי","bt":"תרכז","bp":"קאליסק","dt":"תרצח","dp":"ירושלים","b":"חתן ר דב בער הלוי אשכנזי מקליסק-הח\"חוזר\" של הצמח צדק. מחכמי חברון, עלה בגיל 18, והיה מראשי חסידי חבד, למד עם ר אליהו מני רבה של חברון. עמד בראש ישיבת \"מגן אבות\". והתמנה לרב האשכנזי של חברון לאחר יציאת ר שלמה אליעזרוב לשליחות. עבר לירושלים, כיהן כדיין באלכסנריה לשם הוגלה בזמן מלחמת העולם הראשונה. השאיר כתבים בהלכה. גיסו - ר שלמה יהודה אליעזרוב (היו נשואים לשתי אחיות).","s":"גליס"},{"i":32839,"n":"נאוואפרוצקי, אהרן מואשלישוק","b":"גביר מחכמי ואשלישוק. חתנו - ר שלמה מרדכי מוסנזון.","s":"אהלי שם"},{"i":32840,"n":"נאווי, אלישע מדמשק וצפת","bt":"חלב","dt":"תמא","dp":"המבורג","b":"מחכמי דמשק, חבר בית דינו של ר שמואל ויטאל, וחתם עמו בשנת תכג על קבלת עדות. עבר לחלב, ושימש שם כרב. לאחר תל\"ה עלה לצפת, יצא בשליחות לתורכיה ואירופה, פגש בבלגרד את ר יוסף אלומשנינו וחתם לו על תשובה. נפטר בשליחותו","s":"גליס; אוצר הרבנים 2778; ארזי הלבנון; רוזניס-תורכיה-ד; בניהו סיני רח"},{"i":32841,"n":"נאווי, יוסף מחלב וצפת","f":"אלישע","b":"רבה של ארם צובא, עלה לצפת ויצא לשליחות בתונס בשנת תסג, נזכר בכתב יד \"מעשה נסים\" שפגש את ר ששון קשתיאל. מובא בפסק ב\"דברי יוסף\" לר יוסף אירגאס, ובספר \"ריח השדה\" לר אברהם דוויק הכהן. בהיותו בחלב פגש את ר יהודה דיואן והסכים על פסק שלו (\"חוט המשולש\").","s":"גליס; אוצר הרבנים 8451; רוזניס-תורכיה-ד; בניהו \"סיני\" ריח"},{"i":32842,"n":"נאווי, יצחק מראשיד","f":"ישועה","b":"רב בראשיד, וזמן קצר גם באלכסנדריה. אחיו - ר שבתי מראשיד.","s":"רוזניס-תורכיה-ה"},{"i":32843,"n":"נאווי, ישועה מחלב","b":"רב בחלב. בנו - ר שבתי מרשיד-מצרים.","s":"רוזניס-תורכיה-ה"},{"i":32844,"n":"נאווי, ישעיה מצפת","b":"מחכמי צפת, בשנת תלח בשליחות במרוקו.","s":"גליס; שא\"י"},{"i":32845,"n":"נאווי, ראובן דוד מבגדד","k":"בעל יחי ראובן","bt":"[תקל]","bp":"בגדד","dt":"תקפא","dp":"בגדד","b":"תלמיד ר משה חיים מבגדד. רב בבגדד-תקע על מקום רבו (עוד בחיי ר משה שמינהו לראב\"ד), אך נפטר עוד בחיי רבו. נינו - ר יהודה פתייה מבגדד.","s":"אוצר הרבנים 17734; ארזי הלבנון"},{"i":32846,"n":"נאווי, שבתי ממצרים","f":"ישועה מחלב","bp":"חלב","dp":"רשיד - או בדרכו לשם","b":"רב בראשיד(=רוזיטה)-מצרים-שנות ה-ת' לצד ר דוד גרשון ועל מקומו אחריו-תצה בערך וראש ישיבה שם. חתם על תשובות עם בעל \"גנת ורדים\", נזכר גם ב\"שערי ישועה\" לר ישועה זיין, נזכר גם ב\"משאת משה\" לר משה ישראל. נאלץ לעזוב את מצרים בגלל מחלוקת מצד גביר תקיף, ונדד במקומות שונים ובהם איטליה, ופגש שם את ר דוד עזריאל פינצי ור רפאל מילדולה. אחיו - ר יצחק מראשיד.","s":"אוצר הרבנים 18075; ארזי הלבנון; רוזניס-תורכיה-ד,ה"},{"i":32847,"n":"נאוורי, חנוך הניך מבודזנוב","f":"אברהם","bt":"תרלד","b":"רב בבאדזאנוב(=בודזנוב)-תרס.","s":"אוצר הרבנים 6651; אהלי שם"},{"i":32848,"n":"נאויסעלער, דוד שלמה הכהן","f":"משה חנוך מטשרני","k":"אדמור ממקרוב בפילדלפ","bt":"תרנב","bp":"ירמוליניץ-פודוליה","dt":"תשכו - ו-ט אייר","dp":"בני ברק","b":"נסמך מאת: ר משה נתן רובינטשין מויניציא בעל \"אלף המגן\", ר אליעזר חריף מזסלב, הרב רוטבלאט מזיטומיר, הרב פרלמוטר מפאשקרוב. חתן ר שלמה חיים דברברימדיקר מקונסטנטין, ובזיוו\"ש חתן ר צבי אריה טברסקי מברדיטשוב. רב בפילשטין, עבר לארה\"ב-תרסט וכיהן כרב ואדמור בפילדלפיה. חבר אגודת הרבנים באמריקה, ותנועת המזרחי.","s":"אוצר הרבנים 5221; אלפסי; אנשי שם-אמריקה"},{"i":32849,"n":"נאויסעלער, משה חנוך הכהן","b":"רב בטשרנוסטרו(=טשערנאוסטרה)-תר\"ע","s":"אוצר הרבנים 15412"},{"i":32850,"n":"נאטהאן, שמשון דאקטאר מהמבורג","f":"אורי שרגא","k":"בעל צדק ומשפט","bt":"תקף","bp":"המבורג","dt":"תרסו - ג חשון","dp":"המבורג","b":"נכד-אבי אמו ר ליב פופרש בעל \"לשם זבח\". תלמיד ר איזיק מעץ, הרב בערנייס, ר מיכאל לנדסברג. נסמך מאת: ר אהרן פולד מפפד\"מ, ר בער אלדר מפפד\"מ, ר צבי בנימין אוירבך מדרמשטט. בעל תואר ד\"ר. מלמד בפפד\"מ, מלמד ודיין בהמבורג, סירב לרבנות שווערין, ממלא מקום ר אשר שטרן עד למינוי ר מרדכי עמרם הירש. חיבר חוברת \"צדק ומשפט\"-המבורג תרמד כנגד קונטרס \"חסד ואמת\" (בענין בית הקברות אהלסדורף), ועוד.","s":"דוקס-אוה למושב-ב"},{"i":32851,"n":"נאי, מנחם מנדל מצוזמיר","f":"נתן","bt":"תרטו","dt":"תשג","b":"רב בדובנקה-פלך לובלין-תרנג, צויזמיר(=צוזמיר)-פלך ראדום-תרנג.","s":"אוצר הרבנים 13499; אהלי שם"},{"i":32852,"n":"נאים - משפחה במרוקו","k":"בעל מעינות חכמה","b":"משפחה בדיבדו-מרוקו.","s":"טולדנו-נר המערב"},{"i":32853,"n":"נאים ן, אברהם מלוב","dt":"תשג","dp":"מחנה ריכוז גאדו-לוב","b":"רב באפולוניה-לוב (מרסה סוסה וקירני)-תרעה עד תשב, נשלח ע\"י האיטלקים למחנה הריכוז גאדו-תשג ונספה בשואה.","s":"מלכי חי\"ל-מרציאנו"},{"i":32854,"n":"נאים ן, אהרן מאלגיר","f":"יעקב - ריב\"ן","bt":"תקך - בערך","dt":"תקפ - בערך","b":"רב באלגיר. הו\"ל מחזור מנהג אלגיר - פיסא תקנד, הגדה \"חקת הפסח\" לאביו הריב\"ן.","s":"מלכי ישורון-חכמי אלגיר"},{"i":32855,"n":"נאים ן, אליהו מטבריה","b":"מחכמי טבריה-תרכ\"ז","s":"ארזי הלבנון"},{"i":32856,"n":"נאים ן, אליהו מתאזא-מרוקו","b":"מראשי קהלת תאזא-מרוקו יסד ביכ\"נ ונקרא על שמו. מכתב מר אליהו הצרפתי אליו ואל חברו ר דוד גיגי שהיה לצדו בהנהגת הקהלה.","s":"מלכי רבנן"},{"i":32857,"n":"נאים ן, יהודה מפאס","b":"מחכמי ורבני פאס, נזכר בפס\"ד-שעח.","s":"ארזי הלבנון; מלכי רבנן"},{"i":32858,"n":"נאים ן, יונתן מאזמיר","b":"רב באזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ה"},{"i":32859,"n":"נאים ן, יוסף ממרוקו","f":"יצחק","k":"בעל מלכי רבנן","bt":"תרמב","bp":"פאס","b":"רב בפאס, חוקר וביבליוגרף. חיבר ספרים שונים.","s":"אוצר הרבנים 8449; גאון-יהודי המזרח"},{"i":32860,"n":"נאים ן, יוסף ממרוקו וירושלים","bp":"טיטואן","dt":"תרנח","dp":"ירושלים","b":"מחכמי טיטואן, עלה לארץ-תרכב והתישב בחיפה, עבר לירושלים-תרכו. מחכמי ישיבת \"חסד אל\" לעדת הבבלים. בניו: ר בן ציון, ר משה חי.","s":"גאון-יהודי המזרח"},{"i":32861,"n":"נאים ן, יעקב חיים מאלגיר-ריב\"ן","f":"שמואל","k":"בעל זרע יעקב","bt":"לפני ה'תצה","bp":"פאס","dt":"תקסד - כה תשרי","dp":"אלגיר או ליוורנו","b":"מקובל מחכמי פאס, תלמידו של ר אפרים מונסונייגו מאלגיר, בשנת תקך עזב את פאס בדרכו לארץ ישראל אולם התעכב באלגיר שנים רבות וכיהן כרב באלמעסכר(=מסכארא)-אלגיר-תקיז, אלגיר(=דזאייר)-תקכד, ראש ישיבה בליוורנו-תקמב - בזמן החיד\"א שהעריכו מאוד והזכירו בספריו. כנראה הגיע לארץ ישראל ומשם נשלח לשליחות באלגיר ושם נפטר, (בקהילת אלגיר היו נוהגים להזכיר בליל יום הכפורים את נשמת שליח ירושלים ר יעקב בן נאים). נספד על ידי ר ישראל נחמן דרוהוביטצר מצפת, ונדפסו תולדותיו בשם \"אמת ליעקב\" - ליוורנו תקסד. הו\"ל והגיה ספרים שונים בליוורנו ובהם ספר הזוהר, \"כתם פז\" לר שמעון לביא. חיבר \"זרע יעקב\" - ליוורנו תקמד, \"ישועות יעקב\" - ליוורנו. (אצל גירונדי תאריך פטירתו - תקנח).","s":"גליס; אוצר הרבנים 9773; איטליה גירונדי-י פח; מלכי ישורון-חכמי אלגיר; מלכי רבנן","bk":[["זרע יעקב [שו\"ת]",""]]},{"i":32862,"n":"נאים ן, יעקב יוסף","f":"יצחק","b":"מחכמי מרוקו-תרב, אולי הוא ר יוסף מטיטואן הנזכר ב\"ויאמר יצחק\" ו\"שופריה דיעקב\".","s":"מלכי רבנן"},{"i":32863,"n":"נאים ן, יעקב מאזמיר","f":"ירמיה","k":"בעל משכנות יעקב","dt":"תעד - כא אדר","dp":"אזמיר","b":"תלמיד וחתן ר אהרן לפפא. רב באזמיר-תלד על מקום ר חיים בנבנישתי (ברצות העדה לתקן את אשר עשו בגרשם מאזמיר את ר אהרן לפפא בזמן ש\"ץ), ותלמידו ר\"א ן עזרא על מקומו אחריו. (לפי רוזניס נפטר - תנב).","s":"אוצר הרבנים 9782; פין-כנסת ישראל; רוזניס-תורכיה-ד,ה"},{"i":32864,"n":"נאים ן, יעקב מאזמיר","dt":"תג - ה כסלו","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":32865,"n":"נאים ן, יצחק","f":"מסעוד","bt":"תרט","dt":"תרעה - א ניסן","dp":"פאס","b":"תלמיד ר אהרן ששון, ור חיים דוד סירירו, ור ישראל מימרן. שו\"ב בפאס (בהסכם עם ר יצחק ן דנאן שהיה בעל החזקה). הגיע לארץ-תרלו וחזק למרוקו (בגלל התנגדות אשתו לעלייה). היה רב בבית כנסת יוצאי דברו בפאס. בנו ר יוסף בעל מלכי רבנן.","s":"ארזי הלבנון"},{"i":32866,"n":"נאים ן, יצחק מדבדו","dt":"תקסד - אחרי","dp":"דבדו-מרוקו","b":"מחכמי דבדו-מרוקו-תקנט. חיבר דרושים על הפרשיות. נהרג ע\"י ערבי בדרכו לדבדו.","s":"מלכי רבנן"},{"i":32867,"n":"נאים ן, יצחק מטריפולי","f":"כלפאללה","bt":"תס","dt":"תקל - בערך","b":"רב וסופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":32868,"n":"נאים ן, יצחק מפאס ותלמסאן","f":"מסעוד בן נסים","bp":"פאס","dt":"תקפג - בערך","b":"מחכמי פאס, חתם עם ר שאול סירירו-תקנו, עבר לתלמסאן-תקנז. (אולי הוא המחבר ספר הדרושים לר\"י בן נאיים). בנו - ר יעקב יוסף.","s":"ארזי הלבנון"},{"i":32869,"n":"נאים ן, ירמיה מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":32870,"n":"נאים ן, כמוס מטריפולי","bt":"תרמג","dt":"תשכא","b":"תלמיד ר משה סרוסי, ור ציון ביתאן. ר\"מ בישיבת דאר אסרוסי בטריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":32871,"n":"נאים ן, משה","b":"מחכמי ירושלים, חתם בשנת שץ על כתב שליחות ר אברהם ביטון ור שמואל רימון.","s":"גליס"},{"i":32872,"n":"נאים ן, משה חי מירושלים","f":"יוסף","bt":"תרמא","bp":"ירושלים","b":"הו\"ל עתון \"החרות\" יחד עם משה עזריאל, בשליחות \"בית חנוך עורים\" באלגיר ומרוקו, עסק במסחר ספרי סת\"ם, פעיל צבור, ממיסדי בנק \"הלואה וחסכון\", ועוד.","s":"גאון-יהודי המזרח"},{"i":32873,"n":"נאים ן, נסים מטריפולי","bt":"תקן","dt":"תרך - בערך","b":"רב בטריפולי, עלה לארץ. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":32874,"n":"נאים ן, עזרא מטריפולי","bt":"תקף","dt":"תרס - בערך","b":"רב בטריפולי. מתורתו ב\"באר לחי\" לר חי מימון-ליוורנו תרמח.","s":"מלכי חי\"ל-מרציאנו; ארזי הלבנון"},{"i":32875,"n":"נאים ן, פרג'י מטריפולי","f":"רחמים","k":"בעל מזמרת הארץ","bt":"תקעה","bp":"טריפולי","dt":"תרנג - ה תמוז","b":"רב דיין ומקובל בטריפולי.","s":"ארזי הלבנון; מלכי חי\"ל-מרציאנו"},{"i":32876,"n":"נאים ן, פרג'י מטריפולי","bt":"תקי","dt":"תקף - בערך","b":"רב בטריפולי, חתם עם דייני הקהלה בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":32877,"n":"נאים ן, רפאל חיים משה מגיברלטר","f":"ישעיה","k":"בעל קול תחינה","bt":"תרה או תרג","bp":"טיטואן או חיפה","dt":"תרף - יא אב","dp":"גיברלטר","b":"חתן ר שמואל ישראל. תלמיד ר דוד ן שמעון - צוף דב\"ש, ר חיים שמואל קונוורתי, ר יצחק ן ואליד מטיטואן. עלה עם הוריו לחיפה ועבר לטבריה והיה מחכמיה (לדעת גאון נולד בחיפה), בשליחות במרוקו-תרלד, והתמנה לרב בגיברלטר למעלה מ-30 שנה על מקום ר שלמה אלעפרי - עד לפטירתו (יש רושמים תאריך פטירתו - תרסג). חיבר \"דרוש ארץ ישראל\" ירושלים תשכא, \"פטר רחם\", \"קול תחינה וקול טחנה\" - אודות המחלוקת בענין \"הסילאנדרי\", ועוד. בנו - ר שמואל נפטר צעיר-תרמד. (לפי גאון תאריך פטירתו - ד שבט תרסג).","s":"גליס; אוצר הרבנים 17869; מלכי רבנן; גאון-יהודי המזרח; ארזי הלבנון; אהלי שם; שא\"י"},{"i":32878,"n":"נאים ן, שלמה מאזמיר","b":"תלמיד ר יצחק רפפורט בעל בתי כהונה, מחכמי אזמיר. קרובו - ר שמואל ן נאים מאזמיר.","s":"רוזניס-תורכיה-ה"},{"i":32879,"n":"נאים ן, שמואל מאזמיר","dt":"תקז - כז אדר","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ה"},{"i":32880,"n":"נאמיוט, דב משה מאנטורפן","f":"יחיאל מיכל","k":"בעל דברי משה","bp":"זעטל-פלך גרודנא","b":"חתן ר זבולון ליב ברי\"ט. אב\"ד אנטורפן.","s":"מתוך קטלוג"},{"i":32881,"n":"נאמן, פיבש מזולקוא","b":"מראשי קהלת זולקוא, חתם-תנא בין חמשה שומרי תקנת הקהלה.","s":"בובר-זולקוא"},{"i":32882,"n":"נאמן, שמואל","f":"מאיר מקרמניץ","b":"רב-שנת תקך. נכדו - ר אלחנן רוזנשטין מברלין. אחיו - ר אריה ליב קלישר, ר יוחנן קרמניצר.","s":"אוצר הרבנים 19283; ברוורמן-אנשי שם"},{"i":32883,"n":"נאנציאנר, יצחק יהודה מבודפשט","bt":"1867","dt":"1922","b":"רב בבודפשט. הו\"ל כתבי אסף הרופא. חיבר ספר על הארגון הציבורי של יהודי אירופה.","s":"הונגריה"},{"i":32884,"n":"נאסטאסקין, יעקב מסורוקה","bt":"תרלא","dt":"תרסב - כסלו","b":"רב בסורוקה-תרסא על מקום ר מרדכי פרנקל.","s":"דור וחכמיו-א\"ש-ו"},{"i":32885,"n":"נאפולי, ירמיה מליפאנטו","f":"משה","b":"רב בליפאנטו-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":32886,"n":"נאפי-אשכנזי, משה מאישקופיה","f":"אברהם","b":"רב באישקופיה-שסז.","s":"רוזניס-תורכיה-ג"},{"i":32887,"n":"נאפקער, צבי מקאליב","dt":"תרסב - כח תמוז","dp":"קאליב","b":"נכד ר יעקב פיש מקאליב.","s":"ברוין-אנשי מופת"},{"i":32888,"n":"נארינסקר, הירש מזיטומיר","b":"רב בנארינסק-פלך זיטומיר. בנו - ר יעקב יוסף אסמן מאיבנקוב.","s":"אוצר הרבנים 5329; אהלי שם"},{"i":32889,"n":"נאש, יצחק איציק הכהן מלוברנץ","f":"ראה: לסקר, יצחק איצק"},{"i":32890,"n":"נאש, מנשה מקלויזנבורג","b":"רב בקלויזנבורג-תקצז.","s":"הונגריה"},{"i":32891,"n":"נאש, משה מלוברנץ","b":"אב\"ד לוברנץ.","s":"מתוך קטלוג"},{"i":32892,"n":"נאש, צבי מטרעביטש","dt":"תקב - כא חשון","b":"רב בטרעביטש,אונגאריש-ברוד","s":"אוצר הרבנים 17379"},{"i":32893,"n":"נאשאר, יונתן מבליץ","b":"אב\"ד בליץ(=ביאליץ). בנו - ר משה מבייאה.","s":"מתוך קטלוג"},{"i":32894,"n":"נאשאר, משה מאונגריש-ברוד","f":"יונתן מביעליץ","dt":"תרמה","b":"חתן ר ישכר בר סימאנדל ממיקולאש. רב באונגריש-ברוד-תרד, בייאה והרב ד\"ר יו\"ט ליפמן אדלר על מקומו אחריו-תרמה. לתולדותיו ב\"מאיסעס נאשאר\" לד\"ר ש' נאסער - ברלין תרלט.","s":"גרינוולד-סלובקיה והונגריה"},{"i":32895,"n":"נאשר, שמעון מבאייה","b":"רב בבאייה, ברלין.","s":"הונגריה"},{"i":32896,"n":"נבארו, אברהם מפאס-מרוקו","b":"מחכמי פאס-מרוקו-בשנות הת'. חתם על הסכמה עם חכמי דבדו.","s":"מלכי רבנן"},{"i":32897,"n":"נבארו, בכור יצחק","k":"בעל פני מבין","dt":"תקצא - כה אב","b":"דיין, חיבר \"פני מבין\". אולי הוא שחתם שמו - ודי למבי\"ן.","s":"ארזי הלבנון; ארזי הלבנון חלק א' עמוד 352, חלק ד' עמוד 1949, תולדות הפוסקים עמוד 314","bk":[["לב מבין – רמב\"ם",""],["מבין דבר",""],["פני מבין – סנהדרין",""]]},{"i":32898,"n":"נבארו, דוד מצפת","dt":"שסז","dp":"צפת?","b":"רב בצפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים, חתום בהסכמת הירושה של בכר נבארו, וכפי הנראה היה מוצאו מנבארו שבספרד. ר דוד מוזכר בשו\"ת מהר\"ם אלשיך וכן ב\"אבקת רוכל\". חתם-שלא על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא.","s":"גליס; ארזי הלבנון; רוזניס-תורכיה-ב; דד\"ו, ירושלים ו, סמברי"},{"i":32899,"n":"נבארו, חיים מצפת","b":"מחכמי צפת,שד\"ר צפת-נפל בשבי מלטה","s":"ארזי הלבנון"},{"i":32900,"n":"נבארו, יצחק מאזמיר","b":"רב באזמיר-תקפז עם ר דוד אמאדו, ר שלמה בכר ור שמואל חכים,","s":"רוזניס-תורכיה-ו"},{"i":32901,"n":"נבארו, יצחק ממצרים","b":"גביר במצרים, שר האוצר-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":32902,"n":"נבארו, יצחק משלוניקי","dt":"רעו - כג אייר","dp":"שלוניקי","b":"מיוצאי גירוש נאבארה. מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":32903,"n":"נבארו, שלמה מירושלים","b":"מחכמי ירושלים-תו, בשליחות בארצות שונות, בהיותו באיטליה-תיד התחתן עם נכרית והמיר את דתו.","s":"רוזניס-תורכיה-ד"},{"i":32904,"n":"נבארו, שלמה ממצרים","b":"רב במצרים, ירושלים. חתן - ר משה ן חביב בעל \"גט פשוט\".","s":"רוזניס-תורכיה-ה"},{"i":32905,"n":"נבארו, שלמה ממצרים","b":"גביר במצרים-שנות ה-תק', התמנה יחד עם חברו אברהם סיראנו כאפוטרופוס בצוואת הגביר משה ן עטר מרשיד.","s":"רוזניס-תורכיה-ה"},{"i":32906,"n":"נבארו, שמואל משלוניקי - א","b":"דיין בשלוניקי-שיט.","s":"זכרון שלוניקי"},{"i":32907,"n":"נבארו, שמואל משלוניקי - ב","b":"גביר בשלוניקי. סייע עם שותפו - יהודה דניאל, בהדפסת \"לחם שלמה\" לר משה בולה-תקנה.","s":"זכרון שלוניקי-105"},{"i":32908,"n":"נבארו, תמר מרודוס וירושלים","b":"עלתה מרודוס לירושלים, ועשתה צוואה-תסג ובו הקדישה את רכושה לכוללות ירושלים, והיה מחלוקת על כך ור משה ישראל מרודוס השיב על כך.","s":"רוזניס-תורכיה-ה"},{"i":32909,"n":"נבון, אליהו עמנואל מאדרינופול","bt":"תקצה","bp":"אדרינופול","dt":"תרנט","dp":"אדרינופול","b":"פעיל צבור ומורה מחכמי אדרינופול, ביקר בארץ עם דודו ר יקיר אסטרוג גירון. מתלמידיו עובדיה מיסריאל שחיבר קינה לזכרו.","s":"גאון-יהודי המזרח"},{"i":32910,"n":"נבון, אליהו פנחס מירושלים","dt":"תרנו - ו אייר","dp":"ירושלים","b":"מראשי ישיבת \"מגן דוד\" וחתום בתעודות רבות, נציג עדת היהודים במועצת הפלך. בנו - יוסף נבון ביי.","s":"גליס; גאון-יהודי המזרח; שא\"י, אוסף אלישר"},{"i":32911,"n":"נבון, אפרים חיים מירושלים","f":"יהודה מורנו נבון","dt":"תרכא - ו כסלו","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תרד חתם על הסכם שלום לעדת הספרדים, בתריד חתם על תקנה בקשר לישיבת חסד לאברהם. ראש ישיבת \"יסוד עולם\" בירושלים. חתם על תמיכה בביה\"ס למל-תרטז.","s":"אוצר הרבנים 3104; גאון-יהודי המזרח; ארזי הלבנון; גליס; מגני א, הספרים העבריים לש. הלוי 23"},{"i":32912,"n":"נבון, אפרים מירושלים","f":"אריה יהודה-קרית מלך","k":"בעל בית מושב","dt":"תקמד - כב סיון","dp":"ירושלים","b":"מחכמי ירושלים, חיבר ספר \"בית מושב\" ונדפס בסוף ספר \"קרית מלך רב\" לאביו ר יהודה קושטא תקיא. הסכים לספר \"עיני אברהם\" לר אברהם ציפיג חברו של אחיו רפאל. בשנת תקל חתם על בקשת עזרה לקהילת ירושלים, בשנת תקנא חתם על תקנת היורדים, היה שליח הקהלה, ובשובו חבר בית דינו של ר יום טוב אלגזי בשנת תקמב. חתם על מכתבי שליחות ר רפאל יוסף בן רובי, ר יום טוב אלגזי, ר יעקב חזן.","s":"גליס; אוצר הרבנים 3051; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; שא\"י, ירושלים לזכר לונץ,","bk":[["בית מושב",""]]},{"i":32913,"n":"נבון, אפרים מירושלים - א","f":"יונה חנון","dt":"תקטו","dp":"ירושלים","b":"מחכמי ירושלים (ישנו חכם באותו השם ובאותו שם האב שתאריך פטירתו תקסו - ועל כך גם אצל גאון).","s":"גליס; גאון-יהודי המזרח; פרומקין-תח\"י; ירושלים א"},{"i":32914,"n":"נבון, אפרים מקושטא וירושלים","f":"אהרן","k":"בעל מחנה אפרים","r":"עם הגהות מבנו ר' יהודה","bt":"תלז","bp":"קושטא","dt":"תצה - כו ניסן","dp":"ירושלים או קושטא","b":"חתן הגביר ר יהודה אירגאז. מחכמי קושטא, עלה לירושלים בשנת תס עם חותנו, בשליחות באדריאנופל-תפ, דיין ואב\"ד בקושטא-תפא, בשליחות בשנת תפח לקושטא ונתמנה שם דיין על ידי ר יהודה רוזנס ולאחר פטירתו כרב במקומו. חיבר \"מחנה אפרים\" קושטא תצח. חתם בשנת תץ על תקנות הקהלה.","s":"גליס; ארזי הלבנון; אוצר הרבנים 3050; פין-כנסת ישראל; פרומקין-תח\"י; גאון-יהודי המזרח; רוזניס-תורכיה-ד,ה; פרוייקט השו\"ת, תבונות גליון 30 סוף החוברת; יומא דהילולא","bk":[["מחנה אפרים –",""],["מחנה אפרים - דזימיטרובסקי (כרך א)",""],["מחנה אפרים [עניינים]","מפרשי רמב\"ם"],["מחנה אפרים [על הרמב\"ם]","מפרשי רמב\"ם"],["מחנה אפרים [על הש\"ס ומפרשיו]","מפרשי רמב\"ם"],["מחנה אפרים [חדושים]","מפרשי רמב\"ם"]],"e":"תל\"ז-תצ\"ה"},{"i":32915,"n":"נבון, בנימין מירושלים","f":"יונה חנון-גט מקושר","k":"בעל פי שניים","dt":"תקמה - כט טבת","dp":"ירושלים","b":"מחכמי ירושלים, מחבר ספר \"פי שנים\" שלוניקי תקסו (יחד עם חברו ר רפאל סורנאגה). פסקים ממנו בספר \"גט מקושר\" לאביו, בספר \"נחפה בכסף\" לאביו ועוד. בשליחות ירושלים לערי תורכיה-תקמג.","s":"גליס; איטליה גירונדי-ב ד; אוצר הרבנים 3737; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ה; המעל\"ש, שא\"י"},{"i":32916,"n":"נבון, חי יהודה מירושלים","f":"אפרים חיים","dt":"תרס - יח אלול","dp":"ירושלים","b":"רב בירושלים.","s":"אוצר הרבנים 6715; גאון-יהודי המזרח"},{"i":32917,"n":"נבון, חיים יהודה מירושלים","f":"יצחק","b":"מחכמי ירושלים, בשליחות באדרינופול-תקסג. חתם בין גדולי חברון-תקצג. מכתב שלו פרסום בניהו בסורא ג.","s":"גליס; מגני טז; ארזי הלבנון"},{"i":32918,"n":"נבון, חיים רפאל מירושלים","f":"יהודה-קרית מלך רב","dt":"תקס - ד-ז שבט","dp":"ירושלים","b":"מחכמי ירושלים, בשליחות-תקמה והיה באיזנשטט. בירושלים למד תורה עם החכם סגי נהור ר יהודה ציפיג. צילום מאגרת שלו לר נתן עמרם בבית הספרים (ס' 7213). חברו של ר אברהם צפיג בעל \"עיני אברהם. בנו - ר יהודה - ראשל\"צ בירושלים.","s":"גליס; אוצר הרבנים 6573,17820; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; שא\"י,"},{"i":32919,"n":"נבון, חנן-חנון (חנוך) מירושלים","f":"רפאל עלי","dt":"תפב","dp":"ירושלים","b":"מחכמי ירושלים, אביו של ר יונה נבון בעל \"נחפה בכסף\", דיין בבית דינו של ר אברהם יצחקי, ספר דרשותיו נמצא בכתב יד אצל החידא. חתום על תשובות ומכתבים שונים. נספד ב\"יקרא דשכבי\" לר דוד משלוניקי.","s":"גליס; אוצר הרבנים 6680; גאון-יהודי המזרח; ארזי הלבנון; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":32920,"n":"נבון, יהודה אריה מירושלים","f":"אפרים","k":"בעל קרית מלך רב","bt":"תסז-ג","bp":"קושטא","dt":"תקכא - כא שבט","dp":"ירושלים","b":"עלה לירושלים, תלמיד אביו בעל \"מחנה אפרים\", ר שלמה אלגזי (השני). היה רבו של ר יום טוב אלגזי. היה ראש ישיבת \"דמשק אליעזר\" וראב\"ד בירושלים בתקופת החיד\"א. חיבר \"קרית מלך רב\" קושטא תקיא. שימש רב בקושטא לאחר פטירת אביו. נספד על ידי ר יוסף נחמולי בספרו \"אשד הנחלים\". בניו - ר יצחק בעל \"דין אמת\", ר אפרים בעל \"בית מושב\" ור רפאל חיים.","s":"גליס; אוצר הרבנים 7026,3362; גאון-יהודי המזרח; ארזי הלבנון; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ה; פרוייקט השו\"ת, המבשר תורני גליון 267 עמוד כד","bk":[["קרית מלך רב",""],["קרית מלך רב","מפרשי רמב\"ם"]]},{"i":32921,"n":"נבון, יהודה מורנו מירושלים","f":"חיים רפאל","k":"בעל דגל מחנה אפרים","bt":"תקכה","dt":"תרה - כג כסלו","dp":"ירושלים","b":"למד בירושלים, מחכמי חברון, נכדו של בעל \"מחנה אפרים\". בשליחות חברון בצפון אפריקה-תקנז, בשנת תקסט חתם על מכתב חכמי ירושלים. בשנת תרא חתם לטובת דפוס בק, חיבר \"דגל מחנה אפרים\". אחרי פטירת רבו ר יונה נבון נתמנה לראשון לציון. היה אפוטרופוס של ר יעקב שאול אלישר. ראש ישיבת \"בית אהרן קצין\" יחד עם ר בנימין נבון.","s":"גליס; אוצר הרבנים 7027; ארזי הלבנון; פרומקין-תח\"י; שא\"י, גאון \"ירושלים\" שנה א.","bk":[["דגל מחנה אפרים",""]]},{"i":32922,"n":"נבון, יהודה מירושלים","f":"אפרים","dt":"תקמח - יט שבט","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":32923,"n":"נבון, יוחנן מקושטא","b":"מתורגמן במשלחת ונציה בקושטא-סוף שנות ה-ת', נאסר ונדון למות.","s":"רוזניס-תורכיה-ד,ה"},{"i":32924,"n":"נבון, יונה משה מירושלים","f":"בנימין","dt":"תרא - כג טבת","dp":"ירושלים","b":"רב בירושלים-תקצז, גיסו של ר שלמה בכור וילנא. בשליחות בצפון אפריקה יחד עם ר יונה סעדיה נבון בשנים תקסב-תקסח. בשנת תקמא חתם על תקנות ובשנת תקצז על מכתב בקשה עבור חורבת ר יהודה החסיד. כיהן בבית דינו של ר משה סוזין, בשנת תקצז היה ראשון לציון. חדושיו נמצאים בספר \"נחפה בכסף\" לזקנו ר יונה.","s":"גליס; אוצר הרבנים 8008; גאון-יהודי המזרח; פרומקין-תח\"י"},{"i":32925,"n":"נבון, יונה סעדיה מירושלים","k":"הרב חרמון","bt":"תקצט","bp":"ירושלים","dt":"תרסט - כ אייר","dp":"ירושלים","b":"נכד ר יונה משה נבון, ויורשו של ר בנימין מרדכי נבון-אביו חורגו של היש\"א ברכה. מכונה חרמו\"ן(=ח\"ר מורנו נבון). מחכמי ירושלים, וממונה על ענינים שונים מטעם עדת הספרדים, ש\"ץ מפורסם.","s":"אוצר הרבנים 8010; גאון-יהודי המזרח"},{"i":32926,"n":"נבון, יונה סעדיה מירושלים","dt":"תר - לפני","b":"מחכמי ירושלים וחברון, בן דודו של ר יונה משה נבון הראשון לציון, ויצא אתו בשליחות בשנים תקסב-תקסג, ובשנת תקעב בשליחות קהילת חברון. סייע בגאולת חצר האשכנזים שעליה הוקם ביהכ\"נ ה\"חורבה\".","s":"גליס; אוצר הרבנים 8011; גאון-יהודי המזרח; פרומקין-תח\"י; סיני כרך כה."},{"i":32927,"n":"נבון, יוסף מירושלים","f":"אליהו","bt":"תריח","bp":"ירושלים","dt":"תרצד - כג ניסן","dp":"פאריס","b":"איש עסקים ועסקן ציבור בירושלים, ממיסדי פתח תקוה, ראשון לציון, שכונות בירושלים ובהם \"בית יוסף\" שנקראה על שמו, ו\"מחנה יהודה\" שנקראה על שם אחיו, עבר לפאריס. חתנו - ר אליעזר ירוחם אלישר.","s":"גאון-יהודי המזרח"},{"i":32928,"n":"נבון, יוסף מירושלים","f":"נסים יונה","bt":"תרם","bp":"ירושלים","b":"עסקן בעדה הספרדית בירושלים, מנהל בית חנוך יתומים ספרדי, מנהל בית התבשיל של הגביר נתן שטרויס, חבר אספת הנבחרים הראשונה, ועוד.","s":"גאון-יהודי המזרח"},{"i":32929,"n":"נבון, יצחק יוסף מירושלים","f":"אריה יהודה-קרית מלך","k":"בעל דין אמת","bt":"תצג","bp":"קושטא","dt":"תקמז - ח כסלו","b":"מחכמי קושטא, עלה לחברון, מחכמי ישיבת \"דמשק אליעזר\" בירושלים-תקיח רב בירושלים, אביו בעל \"קרית מלך רב\". בשליחות חברון בצפון אפריקה ובתורכיה. בניו - ר יהודה ור אפרים הדפיסו את ספרו \"דין אמת\" שלוניקי תקסג.","s":"גליס; אוצר הרבנים 10836; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; פרוייקט השו\"ת","bk":[["דין אמת","מפרשי רמב\"ם"]]},{"i":32930,"n":"נבון, יצחק מאדרינופול","f":"עלי","b":"רב באדרינופול-תקע בערך.","s":"רוזניס-תורכיה-ו"},{"i":32931,"n":"נבון, יצחק מאדרינופול וקושטא","f":"אליהו","k":"בעל ינון - י-ם תרצב","bt":"תריט","bp":"אדרינופול","b":"מכונה גם בן אמתי, ינון. מזכיר הגביר משה בר נתן בקושטא כ-50 שנה, מתומכי הציונות והחינוך העברי בתורכיה. פרסם מאמרים בעתוני קושטא - בעילום שמו (בגלל החשש מהשלטונות), וב\"הצפירה\", \"המגיד\". סייע בהוצאת \"שירי ישראל בארץ הקדם\" לר בנימין בכר יוסף. עלה לירושלים-תרפט ועסק בליקוט מנגינות עממיות, עבר לתל אביב.","s":"גאון-יהודי המזרח"},{"i":32932,"n":"נבון, יצחק מפאס","b":"מגדולי חכמי פאס-ש\"ה","s":"אוצר הרבנים 10837"},{"i":32933,"n":"נבון, מרדכי מירושלים","f":"יונה","b":"רב בירושלים-תקם. חתם בפסק ר בנימין נבון ב\"קדשי דוד\".","s":"אוצר הרבנים 13948; איטליה גירונדי-מ נה"},{"i":32934,"n":"נבון, מרדכי מירושלים","b":"דיין בירושלים-תקפא.","s":"פרומקין-תח\"י"},{"i":32935,"n":"נבון, משה אפרים מירושלים","bt":"תרח","bp":"ירושלים","b":"שופט בעירית ירושלים, חבר ועדה העדה הספרדית ופעיל צבור. נפטר ללא ילדים.","s":"גאון-יהודי המזרח"},{"i":32936,"n":"נבון, סעדיה יונה מירושלים","k":"מורנו סעדיה,הרב הזקן","dt":"תרה - כג כסלו","b":"מגדולי חכמי ירושלים","s":"אוצר הרבנים 16533"},{"i":32937,"n":"נבון, רפאל עלי מירושלים","dt":"תקט - ו אייר","dp":"[ירושלים]","b":"רב בירושלים. בנו ר חנון נבון.","s":"אוצר הרבנים 17910; ארזי הלבנון; פרומקין-תח\"י"},{"i":32938,"n":"נביאזסקי, יעקב","f":"צבי","bt":"1905","bp":"קובנא","dt":"1964","dp":"תל אביב","b":"נינו של ר הירשל נביאזר. אחיו של משה. תלמיד גימנסיה עברית בקובנא. מהנדס. היגר לארגנטינה והיה פעיל ציבור שם. קונסול ארגנטינה בתל אביב-1948.","s":"ליטא"},{"i":32939,"n":"נביאזסקי, משה","f":"צבי","bt":"1897","bp":"קובנא","b":"נינו של ר הירשל נביאזר. למד בבזל והוסמך כד\"ר לכלכלה. פעיל בתנועה הציונית בליטא ומזכיר ההסתדרות הציונית-1926. הקים את מחלקת העליה שכונתה \"המשרד הארצישראלי\" בבזל, ודרכה עלו לארץ אלפי יהודים לאחר עליית היטלר לשלטון. עלה לארץ-1937 והיה תעשיין ועתונאי.","s":"ליטא"},{"i":32940,"n":"נביאזר, בנימין זאב","f":"יחיאל","b":"פרנס קהילת קובנא-במאה ה-18. סוכן הגרף טישרביץ וחוכר נהר נאוויאזה. מראשני בעלי הבתים בקובנא שהתישבו בעיר ישיבת קבע. הקים מחדש-1813 את בית החולים היהודי בעיר - יחד עם ר אליעזר ליברמן. בגיל 60 פרש מעסקיו והתמסר ללימוד תורה.","s":"ליטא"},{"i":32941,"n":"נביאזר, צבי הירש (הירשל)","f":"בנימין זאב","bt":"1793","bp":"קובנא","dt":"1870","dp":"קובנא","b":"שתדלן ועסקן חרדי בקובנא. גביר עשיר ממנהיגי קהילת קובנא, עסק בצדקה וחסד והקים אכסניה גדולה לנצרכים. חתנו ר אליהו מרקל סייע לו. בגיל 60 פרש מעסקיו והקים בימ\"ד לאנשי המוסר - קלויז נבאיז'ר - והביא לשם את ר' ישראל סלנטר, ושם למדו גם ר יצחק בלזר, ר יעקב יוסף, ר שמחה זיסל, הרב ד\"ר דב רבל, ר נפתלי אמשטרדם ועוד. עזר הרבה גם לחיילים יהודים בצבא הצאר.","s":"ליטא"},{"i":32942,"n":"נביו, אשר מספרד","f":"חיים","k":"בעל ספר הפרדס","b":"תלמיד ר יהודה בן הרשב\"א. מחכמי ספרד-ק', רב במנתשון. חיבר \"ספר הפרדס\" (פרדס הוא שמו בגימטריא - אשר בר חיים נביו). נזכר בחיד\"א שהביא מספרו.","s":"ארזי הלבנון; אלופי יעקב א-תתקמד-א; פין-כנסת ישראל"},{"i":32943,"n":"נבנצל, אלתר יחיאל מוישניצה","f":"יוסף","k":"בעל פרי העץ ומנחת","bt":"תריח או תריב","dt":"תרצט או תשג","b":"חסיד צאנז ובובוב. חתן הגביר ר יהודה ליבוש לנדא מגורליץ. רב בוישניצה-תרמז, סטניסלב וראש ישיבה. עסק בהתרת עגונות אחרי מלחמת העולם הראשונה. חבר במועצת גדולי התורה. חיבר \"פרי העץ ומנחת יחיאל\" מונקטש תרס.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 2964; אהלי שם","bk":[["מנחת יחיאל [שו\"ת]",""]]},{"i":32944,"n":"נבנצל, זאב מסטניסלב","f":"משה צבי הירש מסטני'","bt":"תרע","dt":"תשב","b":"ערך ירחון \"אור תורה\" קולומיאה תרץ.","s":"וונדר-גליציה ח\"ג"},{"i":32945,"n":"נבנצל, יוסף יהודה מברודשין","f":"משה צבי הירש מסטניס'","bt":"תרנח","dt":"תשב","b":"רב בברודשין. חתן ר שמשון בלויגרונד.","s":"וונדר-גליציה ח\"ג"},{"i":32946,"n":"נבנצל, מאיר ממילווקא","f":"ברוך מוישניצה","bt":"תקץ","dt":"תרס","b":"אחיינו של הדברי חיים. (אמו היתה אחותו - והוא הורה לה לקבל פתקאות). חתן ר יונה צימט מפשמישל (או בנו ר פנחס מויליצקה). אחיו ר אביגדור הלברשטט מקשנוב.","s":"וונדר-גליציה ח\"ג"},{"i":32947,"n":"נבנצל, משה צבי הירש מסטניסלב","f":"אלתר יחיאל מסטניסלב","bt":"תרלח","dt":"תשב","b":"מחכמי סטניסלב וניהל בנק שם עם בנו. חתן ר יוסף הולנדר מאמסנא. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":32948,"n":"נבנצל, עקיבא יהודה מוישניצא","f":"ישראל יחזקאל מוישניצ","k":"בעל מסכת כתובות בגר'","bt":"תרלז","bp":"וישניצא","dt":"תשיח","dp":"ירושלים","b":"רב ודוקטור מאוניבר' ברן. חיבר \"מסכת כתובות\" (עם פירוש הרמבם מתורגם לעברית ואשכנזית) ברלין תרסו. עלה לארץ תרצג. חתן ר יצחק הלוי הירש.","s":"וונדר-גליציה ח\"ג"},{"i":32949,"n":"נגאח ן, יונה ממרוקו","k":"בעל כתב אל מוסתלחוק","b":"תלמיד ר יהודה חיוג. מדקדק מחכמי מרוקו-ד'תת - אולי בפאס.","s":"מלכי רבנן; פין-כנסת ישראל"},{"i":32950,"n":"נגאר, אברהם","dt":"תקנט","b":"דיין בתונס","s":"ארזי הלבנון"},{"i":32951,"n":"נגאר, דוד","f":"יהודה?","k":"בעל צמח דוד","b":"רב בתוניס-תק\"ס","s":"אוצר הרבנים 4920; פין-כנסת ישראל"},{"i":32952,"n":"נגאר, חסדאי מאלגיר","bt":"קפ","dt":"רן - בערך","b":"דיין בתנס-אלגיר. נזכר בשו\"ת הרשב\"ש. עליו ב\"ספונות-ז\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":32953,"n":"נגאר, יהודה מספרד","bt":"קפ","dt":"רן - בערך","b":"רב במיורקה-ספרד, בג'איה-אלגיר - כנראה זמן קצר. התכתב עם הרשב\"ץ ונזכר בשו\"ת בנו - הרשב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":32954,"n":"נגאר, יוסף מצפת","b":"מחכמי צפת, חתום על כתב שליחות בשנת תמח.","s":"גליס"},{"i":32955,"n":"נגאר, יצחק מאלגיר","f":"סעדיה","bt":"קל","dt":"ר - בערך","b":"דיין במסתגאנם. חתם על שטר-קסו ונזכר בשו\"ת הריב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":32956,"n":"נגאר, מחפוץ מתימן","f":"יעקב מספלה-סוואריה","k":"בעל סמע דחיי","bt":"תרסט","bp":"קפלה-תימן","dt":"תשם - ד תמוז","dp":"ראש העין","b":"נסמך ע\"י ר עואץ נגער ור צאלח בן מנצור נגאר - רבנים בקפלה-תימן. עבר עם משפחתו לראדע. התכתב עם ר יחיא נחום מבי\"ד צנעא. עלה לארץ והתישב בראש העין. חיבר גם \"זבחי רצון\" ועוד.","s":"ארזי הלבנון"},{"i":32957,"n":"נגאר, מימון (נתן) מאלגיר","f":"סעדיה או דוד","k":"בעל קונטרס המנהגות","bp":"מיורקה","b":"מחכמי מיורקא, ברח לאלגיר-קנא ונתמנה לדיין בקצמטינא(=קונסטנטין) על מקום ר יוסף ן מניר - אצל ר יוסף בן דוד, עם ר שלמה דיסמאשטרי. חברו של הרשב\"ץ עוד במיורקה ותשובות רבות אליו בתשב\"ץ, ויתכן שלמדו יחד אצל ר וידאל אפרים במיורקה, ונזכר גם אצל הריב\"ש. תלמידו - ר צמח בן הרשב\"ש. אחיו ר מרדכי ברח לבג'איה (ור מימון הוזמן לשם לעשות שלום בקהילה) ותנס-אלגיר, חזר למיורקה ושוב ברח. ממשפחתם גם האסטרונום משה נג'אר ואסטורק נג'אר. במאמר ב\"מוריה\" מזוהה ר מימון עם ר נתן - בעוד שהחיד\"א מציינם כחכמים שונים.","s":"ארזי הלבנון; אוצר הרבנים 14131; מלכי ישורון-חכמי אלגיר; מוריה 25-ג-ה"},{"i":32958,"n":"נגאר, מרדכי מספרד ואלגיר","f":"סעדיה או דוד","b":"רב במיורקא, הספיד שם את ר צמח דוראן שנפטר באלגיר-קסה. לאחר פרעות קץ נאנס להמיר דתו ובשנת קצה הצליח לברוח והגיע לבג'איה-אלגיר (ואחיו ר מימון הגיע לשם כדי לעשות שלום במחלוקת שפרצה שם), תנס-אלגיר, חזר למיורקה וברח שנית. ומשם התכתב עם הרשב\"ץ והרשב\"ש שכבדוהו מאוד. אחיו של ר מימון הדיין מקצמטינא.","s":"אוצר הרבנים 13949; מלכי ישורון-חכמי אלגיר; מוריה 25-ג-ה"},{"i":32959,"n":"נגאר, מרדכי מתונס","dt":"תרט","b":"תלמיד ר יעקב פיתוסי בעל \"ירך יעקב\". רב בתונס-תקצב. חתם על תשובות בענין המחלוקת בג'רבא בין קהילת הדיג'ת ואלחארא. בתונס נקראה על שמו \"ישיבת ר מרדכי נג'אר\" ובה שכנה ישיבת \"חברת התלמוד\" בראשות ר שלמה דאנה.","s":"ארזי הלבנון"},{"i":32960,"n":"נגאר, משה מאלגיר","bt":"ק","dt":"קע - בערך","b":"רב בברשך-אלגיר. בקי בתורת הכוכבים ותלמידו בחישוב המולד - ר שמואל חלאיו. נזכר בשו\"ת הרשב\"ץ. כנראה ממשפחת רבני מיורקא שהגיעו לאלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":32961,"n":"נגאר, משה מתונס","b":"תלמיד ר צמח צרפתי. נזכר ע\" השליח ר יעקב חיים מצפת ב\"סמא דחיי\" כדיין בתונס-תעח יחד עם ר יצחק לומברוזו ור שמואל הכהן. רב ראשי בתונס-תקא על מקום ר אברהם טייב. בנו ר דוד כיהן כדיין בתונס, ונכדיו ר אברהם ור משה.","s":"ארזי הלבנון"},{"i":32962,"n":"נגאר, נתן מקטצמטינא (מימון)","bt":"קמ - בערך","dt":"רך - בערך","b":"דיין בקצטמטינא-אלגיר בזמן הרשב\"ש ונשא ונתן עמו ועם אביו הרשב\"ץ, בקי גם בתורת הסוד. במאמר במוריה נאמר כי הוא זהה לר מימון נגאר - בניגוד לחיד\"א שרושמם כשונים.","s":"אוצר הרבנים 16341; ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":32963,"n":"נגאר, סעדיה מאלגיר","f":"שמואל בן סעדיה","bt":"רך - בערך","dp":"ש - בערך","b":"דיין בווהראן, תלמסאן. ונזכר ב\"יכין ובועז\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":32964,"n":"נגאר, עואץ מתימן","k":"בעל חימוד הגנים","bp":"קפלה-תימן","dt":"תשל - יז אדר","b":"מחכמי תימן. עלה לארץ והתישב בראש העין.","s":"ארזי הלבנון"},{"i":32965,"n":"נגאר, שלום מירושלים","f":"שלמה","b":"מקובל מחכמי ירושלים. מיסד ישיבת הרש\"ש בירושלים, ומנהל ישיבת זכרון שמעון - לזכרו של ר שמעון צבי הורביץ.","s":"מתוך קטלוג"},{"i":32966,"n":"נגאר, שלמה מאלגיר","bt":"קס","dt":"רמ - בערך","b":"רב ונגיד בבג'איה-אלגיר ומכונה \"הנשיא\" אצל הרשב\"ש. סייע לדייני עירו לאכוף את דיניהם והרשב\"ש כתב עליו לדיין ר עמרם עמאר \"אשר הוא טוב לך מששים גבורים והלואי שהיה לי בכאן הוא ואחר כמוהו\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":32967,"n":"נגאר, שמואל מתונס","k":"בעל תפארת יעקב","b":"מחכמי תונס-תקפ, אחיו של ר יהודה בעל \"לימודי ה'\".","s":"אוצר הרבנים 19282; ארזי הלבנון"},{"i":32968,"n":"נג'ארה, יהודה","k":"בעל חגי יהודה","b":"מגדולי חכמי קושטא-תק\"נ","s":"אוצר הרבנים 7029"},{"i":32969,"n":"נג'ארה, יעקב מעזה","f":"משה בן ישראל","b":"רב בעזה-תך על מקום אביו.","s":"רוזניס-תורכיה-ד"},{"i":32970,"n":"נג'ארה, ישראל","f":"משה מגורי האר\"י","k":"בעל זמירות ישראל","bt":"שב - שי - שטו","bp":"דמשק או צפת","dt":"שעט-פה-שצ","dp":"עזה","b":"מגדולי המשוררים בכל הדורות. מחכמי דמשק, אביו היה ראש הרבנים שם, נדד בערים שונות ועלה לצפת, תלמיד זקנו (אבי אמו) ר ישראל די קוריאל בצפת. ונשא ונתן בהלכה עם גדולי דורו ובהם ר בצלאל אשכנזי, ר יום טוב צהלון ור יעקב בירב. נתמנה לרב בעזה - אחרי שפא, ובנו ר משה (במקום אחר כותב רוזניס - אברהם) על מקומו אחריו. חיבר שירים ופיוטים, ובהם גם \"שארית ישראל\" ועוד.","s":"גליס; אוצר הרבנים 11998; פין-כנסת ישראל; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":32971,"n":"נג'ארה, לוי מספרד","bp":"נגארה (ספרד)","dp":"צפת","b":"זקנו של ר ישראל נג'ארה המשורר. מחכמי נג'ארה-ספרד. אחר הגירוש התישב בקושטא-רנב, עלה לצפת. בנו - ר משה.","s":"גליס; אוצר הרבנים 12468; ארזי הלבנון; גאון-יהודי המזרח"},{"i":32972,"n":"נג'ארה, משה מעזה הנכד","f":"ישראל","bp":"צפת","dp":"עזה","b":"נקרא על שם זקנו. רב בעזה-שץ על מקום אביו, ובנו ר יעקב על מקומו אחריו. אביו חיבר לכבודו את הפיוט \"שוחטי הילדים\".","s":"גליס; אוצר הרבנים 14941; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ג,ד"},{"i":32973,"n":"נג'ארה, משה מצפת ודמשק","f":"לוי או ישראל","k":"בעל במערכת","bt":"רסח (באוצר רסב)","bp":"צפת או טורקיה","dt":"שמא - א תמוז","dp":"דמשק","b":"עלה לצפת (ויש אומרים יליד צפת), וכיהן כרב בצפת. חתן ר ישראל די קוריאל. מתלמידי-גורי האר\"י. בשליחות בתורכיה, והתישב בדמשק וכיהן שם כרב הראשי ור יעקב אבולעפיה על מקומו אחריו. בנו ר ישראל - מגדולי המשוררים. חיבר גם \"לקח טוב\".","s":"גליס; אוצר הרבנים 14942; ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":32974,"n":"נגארי, יהודה מאלגיר","f":"עמרם בן יצחק","bt":"ר","dt":"רע - בערך","b":"דיין בתלמסאן על מקום אביו, ותיקן תקנות. שאלות ממנו לרשב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":32975,"n":"נגארי, משה ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":32976,"n":"נגארי, עמרם מאלגיר","f":"יצחק","bt":"[קע]","dt":"רן - בערך","b":"רב וראב\"ד בתלמסאן, ובנו ר יהודה על מקומו אחריו. נזכר בשו\"ת הרשב\"ש, והתכתב גם עם ר יוסף ששפורטש מהוניין.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":32977,"n":"נגדוש, שמואל","b":"מחכמי ארץ ישראל, בשנת רסט חתם על תקנת המס.","s":"גליס"},{"i":32978,"n":"נגל, אלפרד מפרשבורג","b":"שירת כקצין בצבא האוסטרי בזמן מלחה\"ע ה-I, ממארגני ההגנה היהודית בפרשבורג - בזמן הפרעות בסיום מלחה\"ע ה-I, יחד עמו היו עוד ששה מאחיו.","s":"פרשבורג-וינגרטן"},{"i":32979,"n":"נגל, אשר מוערבא","f":"שמואל חיים מוערבא","dt":"תש..","b":"תלמיד השב\"ס. חתן ר יצחק דייטש מיאלע-באגאדע. מראשי הקהלה בוערבא. נספה בשואה.","s":"החת\"ס ותלמידיו"},{"i":32980,"n":"נגל, יוסף","dt":"תשד","b":"רב בפריעדוידזא","s":"אוצר הרבנים 8453"},{"i":32981,"n":"נגל, יצחק מפריוויטשיע","f":"פנחס מטאפלטשאן","bt":"תרעג","bp":"טאפלאטשאן","dt":"תשה - ד כסלו","dp":"קרעמניצקא","b":"תלמיד הדעת סופר, ור משה חיים לאו מפראשוב ופיעטרקוב. חתן ר שמואל בנימין רייך מוערבא. רב בפריויטשיע (=נאוואק ואסלאני). נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!).","s":"החת\"ס ותלמידיו; אוצר כתבי עת-לוין"},{"i":32982,"n":"נגל, שמואל חיים מוערבא","b":"חתן ר אשר ברזניץ מברעזאווא. אביו של ר אשר נגל מוערבא.","s":"החת\"ס ותלמידיו"},{"i":32983,"n":"נגלברג, שמואל מרוהטין","bt":"תרלט","bp":"רוהטין","b":"תלמיד ביהמ\"ד בברלין-תרסג. רב בטריטש-תרע, פורליץ(=פוהרליץ)-תרעג.","s":"וונדר-גליציה ח\"ו"},{"i":32984,"n":"נגרין, משה מצפת משלוניקי וצפת","k":"רמ\"ן - בעל שפת אמת","dt":"שפ - לפני","b":"עלה מברוסה, מתלמידי האר\"י בצפת. רב ומקובל בשלוניקי, ויתכן שהיה דרשן נודד שסבב במקומות רבים. חיבר ספרים רבים ובהם \"מלאכת עבודת הקדש\", \"לוית חן\"-בכת\"י, פירוש על ספר היראה לרבנו יונה - קראקא שעב, ועוד.","s":"איטליה גירונדי-מ י; אוצר הרבנים 14943; גליס; ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":32985,"n":"נגרין, נסים חיים מקושטא","b":"דיין בקושטא, חתם-תרכט עם ר אברהם גרשון ור חיים יצחק קמחי.","s":"מתוך קטלוג"},{"i":32986,"n":"נגרין, שמעון שלמה מירושלים","b":"מחכמי ירושלים. הו\"ל ספר דודו (-אחי אביו) - ר משה בעל \"ספר היראה\" - דירנפורט תצב.","s":"פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":32987,"n":"נגריש, שמואל מפורטוגל","b":"מחכמי ספרד, ואחר הגירוש הגיע לתורכיה. נזכר ב\"בית יוסף\".","s":"ארזי הלבנון"},{"i":32988,"n":"נדאף, אברהם","f":"אלנדאף, אברהם","k":"בעל ענף חיים","bt":"תרכו","bp":"תימן","dt":"תש","dp":"ישראל","b":"מחכמי תימן, עלה לא\"י-תרנ\"א, מנהיג קהילת התימנים בירושלים, חיבר \"ענף חיים\"","s":"ארזי הלבנון"},{"i":32989,"n":"נדאף, ראובן מתימן","k":"בעל דודאי ראובן","bp":"צנעא","dt":"תשמד","dp":"חולון","b":"מחכמי תימן, עלה לארץ וכיהן כרב בחולון.","s":"ארזי הלבנון"},{"i":32990,"n":"נדבו-נדבה, נסים יצחק הכהן מדמש","b":"רב ודיין בדמשק-תרצו.","s":"ליטא"},{"i":32991,"n":"נדל, גדליה מבני ברק","k":"מתורתו של ר גדליה","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א.","s":"אוצר כתבי עת-לוין"},{"i":32992,"n":"נדל, יצחק משה מפשמישל","b":"מחכמי פשמישל.","s":"וונדר-גליציה ח\"ג"},{"i":32993,"n":"נדל, צבי מטומנוב","f":"יוסף","bt":"תרלא","b":"רב בטמנוב(=טאמאניוו)-פלך חרסון-תרנה.","s":"אוצר הרבנים 17381; אהלי שם"},{"i":32994,"n":"נדלר, מאיר זאב מפעלשא בניא","dt":"תרצז - סיון","dp":"קלויזנבורג","b":"דיין בפעלשא באניא-סוף המאה ה-19.","s":"טרנסילבניה"},{"i":32995,"n":"נדסמק, אברהם שמואל","b":"רב בטרניגרד-תקס\"ז","s":"אוצר הרבנים 1415"},{"i":32996,"n":"נדש, שמואל","bt":"תקלד","dt":"תקצב - כ אייר","b":"דיין בוורבוי,רב ביערגען","s":"אוצר הרבנים 19284"},{"i":32997,"n":"נהון, בנימין מפאס","f":"יצחק מפאס?","dt":"שמ - אחרי","b":"מחכמי פאס-שך, חתם על הסכמה-שמד עם ר שלמה עוזיאל, ר אברהם ן רמוך, ר יצחק אבזרדיאל, ועוד.","s":"ארזי הלבנון; מלכי רבנן"},{"i":32998,"n":"נהון, יוסף מפאס","f":"בנימין?","b":"אולי בנו או אחיו של ר בנימין מפאס. מחכמי פאס, חתם על הסכמה-שמד, ועם חכמי המעמד-שנא, חיבר ספר דרשות - בכת\"י.","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":32999,"n":"נהון, יצחק מאלגיר","f":"יוסף","dt":"תכד","b":"הגיע מטיטואן-מרוקו, וכיהן כרב באלגיר. נזכר ב\"חוט המשולש\" כמקורב לר שלמה צרור.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33000,"n":"נהון, יצחק מטיטואן","dt":"תרמג - אחרי","b":"מו\"ץ בטיטואן-תקפח, חתם-תריז עם ר יצחק ן ואליד.","s":"אוצר הרבנים 10735; מלכי רבנן"},{"i":33001,"n":"נהון, יצחק מטנג'יר","f":"אברהם","bt":"תרלג","bp":"טנג'יר-מרוקו","b":"עלה בילדותו לחיפה, תלמיד ישיבת ר אברהם כהן, מנהל כי\"ח חיפה על מקום יוסף בן שימול. פעיל צבור, מנהל כי\"ח בדמשק, טנטה-מצרים, חזר לחיפה והקים בנין לביה\"ס.","s":"גאון-יהודי המזרח"},{"i":33002,"n":"נהון, יצחק מטנג'יר - ב","dt":"תץ - סיון","b":"מו\"ץ מטנג'יר(=טאנכיר), וטיטואן, עם ר חסדאי אלמושנינו. נזכר ב\"משפט וצבי\" ו\"זכות אבות\". חתם על פס\"ד-תפז עם ר יעקב טאוריל.","s":"מלכי רבנן"},{"i":33003,"n":"נהון, יצחק מספרד - פאס","f":"יוסף","dt":"שיא - אחרי","dp":"פאס?","b":"תלמיד ר משה חלואה. מחכמי ספרד בזמן הגירוש, רב וראש ישיבה בפאס-שיא. חתם שמיני בתשובה לר\"ח גאגין בענין הנפיחה. (כנראה בניו החתומים בספר התקנות בפאס - ר בנימין מפאס-שכח ור יוסף מפאס-שנ).","s":"ארזי הלבנון; מלכי רבנן"},{"i":33004,"n":"נהון, מנחם מטיטואן","b":"רב בטיטואן, חתם עם ר וידאל ישראל ור משה הלוי-תקמח ועם ר שם טוב ן ואליד-תקמח.","s":"ארזי הלבנון; מלכי רבנן"},{"i":33005,"n":"נהון, רפאל אברהם מחברון","b":"מחכמי חברון. חתם על הקמת ישיבת \"מגן אבות\"-תקץ.","s":"ארזי הלבנון"},{"i":33006,"n":"נהון, שמואל מטיטואן","b":"מו\"ץ בטיטואן, חתם-תרמא על פס\"ד.","s":"מלכי רבנן"},{"i":33007,"n":"נהוראי הכהן","dt":"תריו - ז תמוז","b":"נספד ע\"י ר יוסף אלפנדרי.","s":"ארזי הלבנון"},{"i":33008,"n":"נהוראי הרופא מטבריה","b":"מופיע ב\"סבוב רב פתחיה\" משנת ד'תתקמ (1180) כאחד החכמים בטבריה ולו בן בשם יהודה ע\"ש רבי יהודה הנשיא ויש לו ספר היחס עד אליו.","s":"גליס"},{"i":33009,"n":"נהוראי מאלכסנדריה","f":"הלל","b":"דיין באלכסנדריה בזמן הרמבם, ונזכר בתשובות הרמב\"ם.","s":"ארזי הלבנון"},{"i":33010,"n":"נהוראי ממצרים","f":"נסים בן נהוראי","b":"גביר מחכמי מצרים-ד'תת (1040), רב בקהל בבלי אירקומן דיין וראש ישיבה. התכתב עם ר ישועה הכהן בן יוסף אודות פדיון שבויים, וכן עם בן דודו ר ישראל בן נתן בן נהוראי.","s":"ארזי הלבנון"},{"i":33011,"n":"נהוראי, זאב","b":"פרסם מאמרים ב\"אור המאיר\" - וארשא תרצו.","s":"אוצר כתבי עת-לוין"},{"i":33012,"n":"נהוראי, שלמה מירושלים","dt":"תקצד - בערך","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":33013,"n":"נהורי, חיים מאלגיר","b":"רב בווהראן. עלה לצפת-תקצו, ונזכר בספר צפת.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33014,"n":"נהורי, חיים מטריפולי","bt":"תקס","dt":"תרל - בערך","b":"רב ודיין בטריפולי. חתם בפנקס בי\"ד שלוניקי.","s":"מלכי חי\"ל-מרציאנו"},{"i":33015,"n":"נהורי, רחמים מאלגיר","f":"אליהו","k":"בעל רחמיך רבים","bt":"תרסב","dt":"תשמה","b":"תלמיד ר יעקב הכהן מענאבה-אלגיר. רבה האחרון של ענאבה(=בון)-תרצט על מקום ר יעקב שושנה - בשנת תשכב חדלה הקהלה להתקיים, רב בפאריס - ועזר ליהודי אלגיר להיקלט בצרפת - בין היתר השיג הסכמת השלטון שלא לחייב תלמידים יהודים לכתוב בשבת. בנו ר שאול נאהורי רבה של ניס-צרפת. מתורתו ב\"רחמיך רבים\" ירושלים תשנא.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר","bk":[["רחמיך רבים",""]]},{"i":33016,"n":"נהורי, שאול מצרפת","f":"רחמים מאלגיר","b":"רב בניס-צרפת. מאמר עליו ב\"אור המערב\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33017,"n":"נהר, אהרן הכהן משלוניקי","b":"גביר מחכמי שלוניקי-שצ. בנו - ר יוסף. חתם-תקכג בצפת על כתב שליחות ר אשר קוריאט, ועל כתב שליחות ר מרדכי בונאן-תקכד.","s":"עמנואל-שלוניקי; רוזניס-תורכיה-ה"},{"i":33018,"n":"נהר, דניאל הכהן","k":"בעל יד הנהר","b":"מחכמי איזמיר, רב בצפת, חזר לאיזמיר, חיבר \"יד הנהר\" דרושים","s":"ארזי הלבנון"},{"i":33019,"n":"נהר, יוסף הכהן משלוניקי","f":"אהרן","b":"גביר מראשי קהלת שלוניקי, השתתף במשלחת אצל השולטן בקושטא-שצז בראשות ר יהודה קובו - שנהרג עק\"ה בידי השולטן.","s":"זכרון שלוניקי"},{"i":33020,"n":"נהר, יצחק","b":"נשא מכתב מאמשטרדם לארץ ישראל-תכז מאת ר בנימין מוספיה ואנשיו - לש\"ץ.","s":"רוזניס-תורכיה-ד"},{"i":33021,"n":"נהר, יצחק הכהן משלוניקי","dt":"תה - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":33022,"n":"נהר, מנחם מירושלים","b":"מחכמי ירושלים, ב\"חרבות ירושלים מוזכר שסבל מפרעות אבן פארוך בשנת שפה.","s":"גליס"},{"i":33023,"n":"נהר, משה הכהן מאזמיר","f":"דניאל-יד הנהר","k":"בעל כסא דברכתא","dt":"תרנד","dp":"צפת","b":"נכדו של ר חיים פלאג'י חתן ר אברהם פלאג'י. המזכירו בספרו. מחכמי אזמיר וישב בכפר \"קורון אבאד\" שליד אזמיר ומשם פנה בשאלות לזקנו. עלה לארץ והתישב בטבריה, ועבר לצפת-תרי.","s":"ארזי הלבנון"},{"i":33024,"n":"נובוקובסקי, שניאור זלמן מרדכי","f":"דובער","bt":"תריא","b":"רב בראמען-פלך פולטובה-תרמא, אחר כך במושבה של אכרי ישראל בהר שפר-פלך חרסון.","s":"אוצר הרבנים 20174; אהלי שם"},{"i":33025,"n":"נוביירה, משה","b":"מגדולי חכמי איטליה,רב בפירארה-רס\"ה","s":"אוצר הרבנים 14944(1944)"},{"i":33026,"n":"נוביק, ישראל מאושאץ","f":"דובער","bt":"תרמב","b":"רב באושאץ-תרס.","s":"אוצר הרבנים 12000; אהלי שם"},{"i":33027,"n":"נוביש די, יוסף משלוניקי","b":"גיס ותלמיד ר אברהם בן עזוז בורגיל. חתן ר יהודה בנבנישתי. מחכמי שלוניקי. הו\"ל עם ר מאיר די בוטון את \"לחם משנה\" על הרמב\"ם.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":33028,"n":"נוביש די, יצחק משלוניקי","b":"מחכמי שלוניקי, גיסו של ר שמואל בן יצחק חיון.","s":"זכרון שלוניקי"},{"i":33029,"n":"נובל, יוסף מהלברשטט וטאטא","b":"נכד ר אהרן קוטנא מטאטוס. תלמיד ר עזריאל הילדסהימר. חתן ר יחיאל מיכל נפתלי ברוק מקדלבורג. רב הקהילה הניאולוגית בטנאג'י-אטאד, אטא(=טאטוס)-תרלד על מקום זקנו, ומרק הנדלר על מקומו אחריו, רב בקלויז בהלברשטט. סופרו של ה\"יידישע פרעסע\" עתונו של הרב ד\"ר עזריאל הילדסהימר. חיבר גם \"יהודי התלמוד של רולינג\" כנגד חיבורו האנטישמי \"היהודי התלמודי\" של רולינג.","s":"החת\"ס ותלמידיו; הונגריה"},{"i":33030,"n":"נובל, נחמיה צבי","f":"יוסף נובל","k":"בעל פורת יוסף","bt":"תרלא","dt":"תרפב - כד טבת","b":"רב פעלים,רב בקניגסברג-תר\"ס,לייפציג-תרס\"ב,המבורג-תרס\"ז,פפד\"מ-תר\"ע","s":"אוצר הרבנים 15964"},{"i":33031,"n":"נודלמן, ברוך אשר מפיעטרקוב","b":"תלמיד הסבא ר יוסף יוזל מנוברדוק. ראש ישיבת נוברדוק בפיעטרקוב. נספה בשואה.","s":"מתוך קטלוג"},{"i":33032,"n":"נוה שלום - ישיבת בירושלים","b":"ישיבה בירושלים, נוסדה בידי הגביר ר יצחק די מאיו מקושטא, בראשות ר משה בולא.","s":"רוזניס-תורכיה-ה"},{"i":33033,"n":"נווארא ירושלמי, שלמה מירושלים","b":"מגדולי רבני ירושלים-ש\"ס","s":"אוצר הרבנים 18535; ארזי הלבנון"},{"i":33034,"n":"נווארא, יצחק משלוניקי","dt":"תי","dp":"שלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'.","s":"זכרון שלוניקי"},{"i":33035,"n":"נווארא, מנחם מאיטליה","f":"יצחק","k":"בעל פני יצחק","b":"נכד ר חזקיה מרדכי בן שמואל בסאן. רב ורופא בוירונה-תק. תלמיד ר יעקב חי חפץ. חיבר \"קרוא מקרא\" בתוך \"פני יצחק\" לזקנו, \"שומר שבת\", \"אסור קדושה\". התכתב עם ר מסעוד חי רקח בעל מעשה רוקח, ועם בעל \"זרע אמת\" ועוד.","s":"איטליה גירונדי-מ יט; אוצר הרבנים 13270; ארזי הלבנון"},{"i":33036,"n":"נווארא, משה","b":"רב בויניציאה-שס\"ז","s":"אוצר הרבנים 14945"},{"i":33037,"n":"נווארא, שלמה מירושלים","b":"מחכמי ירושלים-שנות ה-ש'-ת'. העתיק את סיפור ר יוסף די לה ריינה.","s":"פרומקין-תח\"י"},{"i":33038,"n":"נווארא, שמואל משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. נפטר במגיפה-תקא.","s":"זכרון שלוניקי-93"},{"i":33039,"n":"נווארא, שמואל משלוניקי","dt":"שפא - ח טבת","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":33040,"n":"נוואריא=נייריא=פרידריכשטט-קהלה","b":"קהלה בקורלנד.","s":"אובצינסקי-קורלנד"},{"i":33041,"n":"נוזיק, יוסף יצחק מדוקלא","b":"ממשתתפי \"אהל תורה\".","s":"וונדר-גליציה ח\"ו"},{"i":33042,"n":"נוחומובסקי","k":"ראה: נחמובסקי","b":"רב בשאוולי. נספה בשואה עם בני עדתו ביער קוז'י.","s":"ליטא"},{"i":33043,"n":"נוטיק, דוד","k":"בעל מקרא מפורש","bt":"1857","bp":"מוסניק-פלך וילנא","dt":"1919","dp":"וילנא","b":"תלמיד ר יעקב פסקין. התקרב להשכלה ולציונות. מראשוני \"בני משה\" בוילנא. ממיסדי ה\"חדר\" הראשון לבנות בשם \"בנות ישראל\" שהפך ל\"יהודיה\". ממחברי \"מקרא מפורש\" על התנ\"ך.","s":"ליטא"},{"i":33044,"n":"נויאן, יואל מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב.","s":"תולדות אנשי השם-לנדסהוט"},{"i":33045,"n":"נויבאואר אברהם","bt":"1831","dt":"ה'תרסז 1907","s":"היברובוקס","bk":[["מלאכת השיר",""],["סדר החכמים וקורות הימים",""]]},{"i":33046,"n":"נויבורג, יעקב מאופנבך","f":"ברוך","k":"בעל נחלת יעקב","dt":"תקעא","b":"נכד בעל \"קיקיון דיונה\". תלמיד ר טבלי שייאר במגנצא, ר אביש בפפד\"מ. ר\"מ בישיבת ר איצק שפייאר באופנבך. חיבר \"נחלת יעקב\" על מסכתות קטנות - ונדפס בש\"ס וילנא.","s":"מוריה 23-ג-ה; פין-כנסת ישראל"},{"i":33047,"n":"נויבורגר, גוטליב","b":"מגדולי חכמי אשכנז,מרביץ תורה בשוואבן-שיד. ישב לדין יחד עם ר יצחק איזיק גינצבורג בענין ר שמעון גינצבורג והגט המעושה של חתנו - ר מאיר העבעל בן שלמה האז מפפד\"מ.","s":"אוצר הרבנים 4362; רבני פרנקפורט"},{"i":33048,"n":"נויגרשל, מתתיהו","k":"בעל באר שבע","dt":"תקלח","b":"נקרא על שם אביו,רב בצילץ,פרוסטיץ,רודניץ","s":"אוצר הרבנים 15790"},{"i":33049,"n":"נויגרשל, שמואל מגורליץ","b":"תשובה אליו - \"אהל יהושע\"-תרסג.","s":"וונדר-גליציה ח\"ו"},{"i":33050,"n":"נויראט, אלכסנדר מפרשבורג","b":"מעסקני האגודה הציונית \"יגדיל תורה\" (ששינתה שמה ל\"אהבת ציון\") בפרשבורג - אחרי תרנז - שעסקה בלימוד גמרא למשתתפיה.","s":"פרשבורג-וינגרטן"},{"i":33051,"n":"נוישטט, יעקב דוד מוישניצה","b":"רב בוישניצה אצל \"אריה דבעי עילאי\", ובקראקא.","s":"וונדר-גליציה ח\"ג"},{"i":33052,"n":"נולא, אליהו די הרופא מאיטליה","f":"יוסף","b":"רופא מחכמי בולוניה. חיבר פירושים לתנ\"ך בדרך פילוסופיה ומחקר. תרגם מספרי אריסטו מלטינית ליוונית, יחד עם ר משה אלאטורנוס והדפיסם - של.","s":"אלופי יעקב א-תקף"},{"i":33053,"n":"נולא, אליהו מאיטליה - המומר","f":"מנחם","k":"יואן פולו אוסטאכיא","b":"רופא באיטליה. המיר דתו ותרגם-שטו ספרי קבלה עבור הנוצרים.","s":"אלופי יעקב א-תקף"},{"i":33054,"n":"נולא, אליהו מרומא","b":"מחכמי איטליה-ש'. תשובה ממנו בענין חליצה אצל ר אליקים ממצירטא.","s":"איטליה גירונדי-א סו"},{"i":33055,"n":"נומברג, יהודה","f":"מאיר פוזנר","k":"ראה: יהודה מראוי","b":"רב בראוויטש-תק\"ס (יש כאן טעות - היה חתנו של ר מאיר ולא בנו)","s":"אוצר הרבנים 7030"},{"i":33056,"n":"נומברג, יחזקאל מלודז","f":"יהודה מראויטש-גרמניה","dt":"תרטו-לח","b":"חתן הגביר ר פנחס הכהן שאטאן מליומירסק, וגיסו של ר חנוך הניך מאלכסנדר. תלמיד ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק. רב בטערצאל, ליטומירסק-תקעט, קונסטנטין, לודז-תקצב.","s":"אוצר הרבנים 9012,9059; עיר לאסק וחכמיה; אלפסי"},{"i":33057,"n":"נונו, נתן מאלגיר","f":"סמעאל","bt":"ש","dt":"שע - בערך","b":"ספרא רבא באלגיר. כתב מחזור מנהג אלגיר בישיבת ר יוסף בן שלמה דוראן-שמא.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33058,"n":"נונו, שלמה מאלגיר","bt":"קן - בערך","dt":"רכ - בערך","b":"דיין בהוניין-אלגיר, אצל ר אברהם הכהן שולאל. נזכר בתשב\"ץ.","s":"ארזי הלבנון"},{"i":33059,"n":"נוניס אלוארינגה, יצחק חיים","b":"רב בליוורנו, חתום על הקדמה ל\"שדה יצחק\" לר יצחק גויטע-תרו. ישב בבית הדין יחד עם ר יהודה קוריאט ור אברהם ברוך פיפירנו.","s":"ארזי הלבנון"},{"i":33060,"n":"נוניס בילמונטי, יצחק מאזמיר","f":"משה","k":"בעל שיטה מקובצת","bt":"תע-תעה","dt":"תקלד?","b":"נכד(-אבי אמו) ר אפרים ארדיטי בעל \"שיח יצחק\" מאזמיר, וקרובו של ר ברוך גאגין שעזר לו בהדפסת ספרו. תלמיד ר חיים אבולעפיה מאזמיר, ור ברזילי יעבץ בעל לשון למודים, ור יצחק הכהן רפפורט בעל בתי כהונה, ור יעקב אלבעלי מאזמיר בעל קהילת יעקב. היה בשליחות אזמיר באיטליה לאחר השריפה באזמיר-תקלב, ונפטר בשליחות בליוורנו - באמצע שהדפיס \"שיטה מקובצת\". תלמידו ר רפאל יצחק מאיו בעל דרכי הים - הדפיס את ספרו של רבו \"דרך השער\" בסוף \"דרכי הים\". ירש את כתביו וספריו של זקנו - ר אפרים, וכן החזיק בכתביו של ר יונה בן אברהם למסכת בבא בתרא ומהם הדפיס \"שיטה מקובצת\" שלוניקי תקנא. (יש מחליפים בינו לבין ר יצחק נוניס ואיס מליוורנו בעל \"בית יצחק\".","s":"ארזי הלבנון; אוצר הרבנים 10838; פין-כנסת ישראל; רוזניס-תורכיה-ה; יומא דהילולא; ראה ערך שער המלך; ישורון כ ע' תתסה - עד","bk":[["שער המלך",""],["שער המלך","מפרשי רמב\"ם"],["דרך השער",""],["שער המלך – רמב\"ם",""]],"e":"ת\"ע~-תקל\"ד"},{"i":33061,"n":"נוניס ואיס, יעקב מליוורנו","f":"יצחק","k":"בעל חדות יעקב","b":"חתן ר יעקב בונדי. רב בליוורנו על מקום אביו. תלמיד ר יצחק בעל \"שער המלך\". חיבר \"חדות יעקב\" שנדפס בסוף \"שיח יצחק\" לאביו, ועוד.","s":"איטליה גירונדי-י י; פין-כנסת ישראל"},{"i":33062,"n":"נוניס ואיס, יצחק יוסף מליוורנו","k":"ינו\"ן - בעל שיח יצחק","bt":"1730","dt":"תקלד","dp":"ליוורנו","b":"רב בליוורנו. גיסו של ר ישמעאל הכהן בעל \"זרע אמת\". חיבר גם \"בית יצחק\".","s":"אוצר הרבנים 10839; איטליה גירונדי-י ט; ארזי הלבנון; פין-כנסת ישראל; אוצר הרבנים","bk":[["שיח יצחק","מפרשי ש\"ס - אחרונים"],["שיח יצחק - חגיגה ויומא",""]]},{"i":33063,"n":"נוניס טוריס, דוד מאמשטרדם","dt":"תפח","b":"מרביץ תורה בבית מדרש הספרים באמשטרדם, הגיה ספרים לדפוס","s":"ארזי הלבנון"},{"i":33064,"n":"נוניס ן, יוסף משלוניקי","dt":"שפח - טו אלול","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":33065,"n":"נוניס ן, יצחק מפורטוגל ושלוניק","b":"מאנוסי פורטוגל, הגיע לשלוניקי - שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":33066,"n":"נוניס קארואלהו, עמנואל מלונדון","bt":"תקלב","bp":"לונדון","dt":"תקעז - ג ניסן","b":"רב בברידגטאון-ברבדוס-תקנט, רב בצ'רלסטאון-דרום קרוליינה-תקסו, פילדפיה-תקעה.","s":"אמריקה; ארזי הלבנון"},{"i":33067,"n":"נוניס, דוד מהאג","b":"רב בהאג-ת\"ס","s":"אוצר הרבנים 4922"},{"i":33068,"n":"נוסבוים, אברהם ממליץ","b":"רב במליץ-תרסו.","s":"וונדר-גליציה ח\"ג"},{"i":33069,"n":"נוסבוים, זאב וולף מדרוהוביטש","f":"דוד מסטרי","k":"בעל כבוד הלבנון","bt":"תרלז","bp":"סטרי","dt":"תשיג","b":"חתן ר יוסף פנצר מדרוהוביטש. רב בדרוהוביטש לצד חותנו ועל מקומו אחריו. חסיד צורטקוב. חיבר גם \"זיו הלבנון\", ועוד. פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח, \"הכוכב\" - מונקטש תרצה, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 5517; אוצר כתבי עת-לוין"},{"i":33070,"n":"נוסבוים, חיים אלחנן מרישא","f":"אברהם אביש מדזיקוב","k":"בעל לקוטי אלחנן","bt":"[תרמג]","bp":"דזיקוב","dp":"תשמג","b":"מחכמי רישא. עלה לארץ והתגורר בבני ברק. חיבר \"לקוטי אלחנן\" בני ברק תשלד.","s":"וונדר-גליציה ח\"ג"},{"i":33071,"n":"נוסבוים, חיים מטורונטו","f":"אפרים","k":"בעל משעבוד לגאולה","b":"מחנך בטורונטו. חיבר \"משעבוד לגאולה\" לונדון תשלג.","s":"וונדר-גליציה ח\"ג"},{"i":33072,"n":"נוסבוים, יהושע מדזיקוב","k":"בעל זכרון יהושע","bt":"תקצג","dt":"תרלב","b":"דיין בדזיקוב. נפטר ללא ילדים. חברו ר שמעון פרידמן בעל \"אמרי שמעון ליקט והדפיס את ספרו \"זכרון יהושע\" פרמישלא תרלב.","s":"וונדר-גליציה ח\"ג"},{"i":33073,"n":"נוסבוים, יחזקאל מקראקא","b":"מחכמי קראקא - ממשתתפי \"אהל מועד\".","s":"וונדר-גליציה ח\"ג"},{"i":33074,"n":"נוסבוים, מפודגורזע","b":"מחכמי פודגורזע-תרסב - תשובה אליו \"מחזה אברהם\".","s":"וונדר-גליציה ח\"ג"},{"i":33075,"n":"נוסבוים, מרדכי הלוי","b":"רב-שנת תר\"ע","s":"אוצר הרבנים 13950"},{"i":33076,"n":"נוסבוים, משה","dp":"ארץ ישראל","b":"סופרו של הדברי חיים. עלה לארץ.","s":"וונדר-גליציה ח\"ג"},{"i":33077,"n":"נוסבוים, משה מרישא (ריישער)","f":"מנחם מנדל מרישא","k":"בעל שערי ירושלים","bt":"תר","bp":"רישא (או ירושלים)","dt":"תרם","b":"עלה לירושלים עם אביו בילדותו (ואולי נולד בירושלים). עבר לפולין ושם חיבר \"שערי ירושלים\" למברג תרכו. התגורר בטרנוב.","s":"וונדר-גליציה ח\"ג; פרומקין-תח\"י"},{"i":33078,"n":"נוסבוים, ניסן ממעליץ","b":"מחכמי ומלמדי מעליץ.","s":"וונדר-גליציה ח\"ג"},{"i":33079,"n":"נוסבוים, צבי הירש מזאריק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":33080,"n":"נוסבוים, שמואל","f":"אפרים מדזיקוב","bt":"תרעה","bp":"פפדמ","dt":"תשלו","b":"ניצל מהשואה. חתן ר יהושע מתתיהו פינקל מהולנד. מחכמי לוגאנו.","s":"וונדר-גליציה ח\"ג"},{"i":33081,"n":"נוסבוים-טיפנברון, אשר ישעיה","f":"נפתלי טיפנברון","bt":"תרעב","bp":"מעליץ","dt":"תשכו","dp":"ניו יורק","b":"חסיד בלז, חתן ר יוסף פרנקל מצאנז והתגורר בצאנז. ניצל מהשואה. בזיוו\"ש חתן ר שמעון מלבר מדובצק ועבר לאנטורפן. עבר לארה\"ב-תשיב ושימש כר\"מ בישיבת בלז.","s":"וונדר-גליציה ח\"ג"},{"i":33082,"n":"נוסינזון, חיים מהורודוק","k":"בעל באר מים חיים","b":"רב בהורדוק,עלה לא\"י-תרפ\"ג","s":"אוצר הרבנים 6082"},{"i":33083,"n":"נוסנבוים, דוד מהונגריה","b":"רב בהונגריה-תרכה, חתם על מכתב ר משה טפלטשין כנגד הרב הריפורמי ד\"ר יהודה לעף מסנדין.","s":"מתוך קטלוג"},{"i":33084,"n":"נוסנבוים, ישראל יהודה","b":"מראשי חסידות צורטקוב, חתם-תרצד על מכתב בקשת עזרה של ראשי החסידות עם ר יוסף דב הורן.","s":"מתוך קטלוג"},{"i":33085,"n":"נוסקרן, שמואל פנחס מבלז","b":"מחכמי בלז-תרסט.","s":"וונדר-גליציה ח\"ג"},{"i":33086,"n":"נופך, יהודה זאב ממינסק","b":"מחכמי מינסק, משכיל, מנהל ביה\"ס למלאכה-תרן בערך.","s":"מינסק-איזנשטט"},{"i":33087,"n":"נוראך, אהרן דובר ממיטאוי","f":"צבי הירש","b":"תלמיד ביהמ\"ד לרבנים בברלין, ובעל תואר ד\"ר. ספרן בספריה הקיסרית בפטרבורג. רב בליבאוי-תרסו.","s":"אובצינסקי-קורלנד"},{"i":33088,"n":"נורדן, חיים מהמבורג","f":"יהודה אריה","bp":"המבורג","dt":"תרלב - ה אד\"א","dp":"המבורג","b":"תלמיד ר נתן נטע עלינגן. מלמד בת\"ת בהמבורג-תקעח, מחכמי הקלויז בהמבורג-תקפ, ר\"מ בקלויז של ר יחיאל ואליך.","s":"אוצר הרבנים 6083; דוקס-אוה למושב"},{"i":33089,"n":"נורוק, אהרן מראסיין","f":"אריה","dt":"תרכז","b":"רב בראסיין. פרסם מאמרים ב\"המצפה\" - נ\"י תרע. גיסו - ר אלעזר בן מאיר מראסיין. בנו - ר צבי הירש ממיטאוי.","s":"אוצר כתבי עת-לוין; מרקוביץ-ראסיין"},{"i":33090,"n":"נורוק, אהרן מראסיין - הנכד","f":"אריה","b":"שו\"ב בראסיין-סוף שנות ה-תר.","s":"מרקוביץ-ראסיין"},{"i":33091,"n":"נורוק, אריה מראסיין","dt":"תרסא - כב כסלו","dp":"ראסיין","b":"שו\"ב בראסיין.","s":"מרקוביץ-ראסיין"},{"i":33092,"n":"נורוק, מרדכי ממיטאוי","f":"צבי הזנהפט","bt":"תרמה","dt":"תשכג - יא חשון","b":"רב במיטאוי וחבר בבית הנבחרים בלטביה, ניצל מהשואה, עלה לארץ וכיהן כחבר כנסת-תשיב, שר הדואר.","s":"אוצר הרבנים 13951"},{"i":33093,"n":"נורוק, צבי הירש מהאזנפוט","f":"אהרן מראסיין","bp":"ראסיין","b":"חתן ר אליעזר ליפמן ליכטנשטין מטוקום, ר יוסף דב סולוביציק מבריסק. רב בהאזנפוט-תרמב על מקום ר אברהם הלר, מיטאוי-תרנט, שאוויל. קיבל רשיון לרב מטעם השלטון.","s":"אובצינסקי-קורלנד; מרקוביץ-ראסיין"},{"i":33094,"n":"נוריאל, יצחק מבבל","f":"שלום","b":"מחכמי בבל. נזכר ב\"דורש בעדי\" לר עבודי יחיא משה.","s":"ארזי הלבנון"},{"i":33095,"n":"נוריאל, שלום מבבל","b":"תלמיד ר משה חיים. מתורתו ב\"נופת צופים\" לר שלמה תווינא. בנו ר יצחק מחכמי בבל.","s":"ארזי הלבנון"},{"i":33096,"n":"נורלינגן, אברהם אהרן מונציה","f":"שמואל","b":"גיסו של מהר\"ם פדובה. מחכמי אשכנז והגיע לאיטליה, רב בונציה בזמן מהרמא\"י. חתם עם רבני ונציה-שו ונזכר בשו\"ת הרמ\"א. תשובה ממנו בענין מהר\"ר מ\"ן - על אותם שבירכוהו שלא כדין...","s":"איטליה גירונדי-א נג; אלופי יעקב א-קצג"},{"i":33097,"n":"נורלינגן, אהרן דוד מקרימונה","b":"רב בקרימונה, מנטובה-שסז. מתורתו ב\"פלגי מים\" - אודות המחלוקת בענין המקוה ברוויגו. תשובה ממנו ב\"נחלת יעקב\" - שמב.","s":"איטליה גירונדי-א עה"},{"i":33098,"n":"נורלינגן, יצחק איזיק מפפד\"מ","k":"בעל קיצור ראשית חכמה","b":"מחכמי פפד\"מ-ש', רב ושליח צבור. חיבר \"קיצור ראשית חכמה\". נזכר בספר נכדו ר יוסף - \"יוסף אומץ\". בנו - ר פנחס זליגמן.","s":"אלופי יעקב א-תקם"},{"i":33099,"n":"נורלינגן, ישעיה שמואל ממנטובה","b":"אחיינו של ר ר מאיר פדובה-קצנלנבוגן. מחכמי מנטובה, חתם-שמד על הסכם בנקאי.","s":"מתוך קטלוג"},{"i":33100,"n":"נורצי, גמליאל","k":"בעל שפתי רננות","b":"מגדולי חכמי איטליה,רב במנטובה-ת\"כ","s":"אוצר הרבנים 4366"},{"i":33101,"n":"נורצי, חיים ממנטובה","f":"יחיאל","b":"רב במנטובה. חתם עם רבני עירו בשו\"ת הרמ\"ז בענין יבום למומר.","s":"איטליה גירונדי-ח יו"},{"i":33102,"n":"נורצי, ידידיה שלמה רפאל ממנטוב","f":"אברהם","k":"בעל מנחת שי","dt":"שפו","b":"תלמיד ר משה פרנקיטה. מגדולי המדקדקים ובעלי המסורה, רב במנטובה-שמו. חיבר ספר על המסורה בשם \"גודר פרץ\" ונדפס בשם \"מנחת שי\".","s":"אוצר הרבנים 6811; פין-כנסת ישראל"},{"i":33103,"n":"נורצי, יצחק חי מאיטליה","k":"בעל עיטור בכורי קציר","b":"תלמיד ר יצחק למפרונטי בעל \"פחד יצחק\" בפיררה. מחכמי איטליה. ספרו יצא לאור ע\"י רבו. פרסם מאמר ב\"ראשית בכורי קציר\" - ונציה-פיררה תעה.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":33104,"n":"נורצי, יצחק מספרד ואיטליה","b":"מגדולי חכמי ספרד בזמן הגירוש(רנ\"ב),בא לפירארה","s":"אוצר הרבנים 10840"},{"i":33105,"n":"נורצי, משה ממנטובה","b":"רב במנטובה. תשובה אליו ב\"דבר שמואל\".","s":"איטליה גירונדי-מ כו"},{"i":33106,"n":"נורצי, רפאל","k":"בעל סאה סולת","b":"מגדולי חכמי איטליה-ש\"י","s":"אוצר הרבנים 17821"},{"i":33107,"n":"נורתלגאן, דוד מקרימונה","b":"רב בקרימונה, מנטובה. תשובה ממנו ב\"פלגי מים\".","s":"איטליה גירונדי-ד ה"},{"i":33108,"n":"נזיר, אברהם הלוי","f":"משה","b":"אחיו של ר יוסף הלוי נזיר.","s":"רוזניס-תורכיה-ד"},{"i":33109,"n":"נזיר, יוסף הלוי מחברון ומצרים","f":"משה הנזיר","k":"בעל מטה יוסף","bt":"ה'תכ (בערך)","bp":"ירושלים","dt":"תעד - ח חשון","dp":"מצרים","b":"נכד ר אברהם ן חנניה מירושלים. חתן ר אהרן אזובי. מחכמי ירושלים, חברו של ר חזקיה די סילוה, עבר לחברון, ונתקבל לרב במצרים. חתנו - ר ישועה שבאבו בעל \"פרחי שושן\". חיבר \"מטה יוסף\" קושטא תפט. נשא ונתן עם ר אברהם הלוי בעל \"גינת ורדים\" ועוד חכמים. בשנת תמט בשליחות חברון באירופה. חתנו - ר ישועה שבאבו ידיע זין.","s":"גליס; אוצר הרבנים 8455; פין-כנסת ישראל; רוזניס-תורכיה-ד,ה","bk":[["מטה יוסף [שו\"ת]",""]]},{"i":33110,"n":"נזיר, משה הלוי מחברון","k":"בעל ידי משה","bp":"קושטא","b":"עלה לירושלים, מחכמי חברון-תך, חתן ר אברהם ן חנניה. בשנת תכח בשליחות בתורכיה ויון, בשליחות-תלט ופגש את ה\"חכם צבי\". חיבר \"ידי משה\" בכתב יד. מתשובותיו בספר \"מטה יוסף\" לבנו ר יוסף-אב\"ד במצרים. חיבר לעצמו \"סדר קדושה\" - הנהגות פרטיות שקיבל על עצמו. בניו - ר יוסף הלוי הנזיר בעל \"מטה יוסף\", ר אברהם.","s":"גליס; שא\"י; אוצר הרבנים 14946; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":33111,"n":"נזלאן, רפאל מלעראייס-מרוקו","b":"מחכמי לעראייס, חתם-תקצה על פס\"ד עם ר יהודה בן זאזון.","s":"מלכי רבנן"},{"i":33112,"n":"נזרא, סימן טוב מספרד","f":"אליה","b":"מחכמי ספרד-קסו. חיבר פירוש על האבן עזרא.","s":"ארזי הלבנון"},{"i":33113,"n":"נזרי, יצחק מארפוד-מרוקו","b":"שו\"ב במרוקו, עלה לארץ והתישב בלוד. נסמך ע\"י הבבא סאלי.","s":"ארזי הלבנון"},{"i":33114,"n":"נח","dt":"תקכט - כב טבת","b":"רב בפשוורסק","s":"אוצר הרבנים 15805"},{"i":33115,"n":"נח אפרים פישל","dt":"תקמג - יג תשרי","b":"רב בקולומיי","s":"אוצר הרבנים 15827"},{"i":33116,"n":"נח ברמ\"ץ סגל מסקוליע","b":"רב בסקוליע-תקכא.","s":"וונדר-גליציה ח\"ג"},{"i":33117,"n":"נח הלוי מקרולה","b":"דיין בקרולה - אמצע המאה ה-19. נזכר ב\"ארץ צבי\" ו\"תאומי צביה\" בפרענומערנטען.","s":"טרנסילבניה"},{"i":33118,"n":"נח חיים הכהן מקראקא","b":"מחכמי קראקא-תרפז","s":"וונדר-גליציה ח\"ג"},{"i":33119,"n":"נח יעקב","b":"רב בפאסוואל-תרמ\"ח","s":"אוצר הרבנים 15833"},{"i":33120,"n":"נח מבריסק","f":"משה מושלס","b":"דיין בבריסק-שנות ה-ת' יחד עם ר\"א בן יקותיאל זלמן אצל ר אברהם בן בנימין(?)","s":"בריסק-עיר תהלה"},{"i":33121,"n":"נח מהמבורג","f":"שאול מפשעדיבורז","dt":"תקכא - י טבת","dp":"אלטונא","b":"מחכמי המבורג.","s":"דוקס-אוה למושב-ב"},{"i":33122,"n":"נח מוילנא","f":"יוסף","b":"רב בוילנא, חתם-תעד על פס\"ד עם ר בנימין וולף וילנא-אשכנזי ור צבי בן דב בער.","s":"פין-קריה נאמנה"},{"i":33123,"n":"נח מוילנא","f":"יוסף","b":"דיין בוילנא, חתם-תץ עם ר יהודה מטיקטין.","s":"פין-קריה נאמנה"},{"i":33124,"n":"נח מטומשוב","b":"מחדושיו ב\"ברכת טוב\", מוזכר ב\"זרע ברך\".","s":"איטליה גירונדי-נ ד"},{"i":33125,"n":"נח מלודמיר","dt":"תקצב - יז כסלו","b":"רב בלודמיר","s":"אוצר הרבנים 15812","bk":[["ביאורים למהר\"ם שיף",""]]},{"i":33126,"n":"נח מלודמיר","b":"תלמיד החוזה מלובלין. חיבר עם ר מרדכי מארדיש מפריצק את הביאור על \"מהרם שיף\".","s":"אלפסי"},{"i":33127,"n":"נח מקאריב","f":"שמואל הצדיק","k":"בעל קב חן","bt":"תקנד","dt":"תרטו - כו תמוז","b":"תלמיד החוזה מלובלין שמינהו לרב בקאריב. בשנת תקעה תלמיד ר שמואל מקאריב, בתקפו נסע לר יצחק משה עזריאל מבלזיץ. אדמור-תרא - והיה נוסע כאדמור לר מנחם מנדל מקוצק.","s":"אוצר הרבנים 15819; אלפסי"},{"i":33128,"n":"נח משה יונה מלבוב","f":"משה","b":"מחכמי לבוב, נזכר בפנקס הקהלה-תיג, חתם-תיד על שטר מכירה.","s":"בובר-לבוב"},{"i":33129,"n":"נח צבי מלבוב","f":"יוחנן","k":"בעל עטרת צבי","b":"חתן ר יצחק בן ר מרדכי-ראש מדינה בטיסמניץ. דרשן בגליל פדאלי, לבוב-תק, ברודי.","s":"אוצר הרבנים 15835; בובר-לבוב"},{"i":33130,"n":"נח רעסער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז.","s":"עיר וילנא ח\"א"},{"i":33131,"n":"נח, יצחק מכורדיסטן","k":"בעל שיח יצחק","dt":"תשכב","dp":"טבריה","b":"רב בכורדיסטן, עלה לארץ וכיהן כרב במושב אלקוש. חיבר \"שיח יצחק\" ונדפס בתוך \"תולדות יצחק\" שנכתב לתולדותיו - תשנד.","s":"ארזי הלבנון"},{"i":33132,"n":"נחאיסי, כמוס מטריפולי","dt":"תשכה - ט אד\"א","b":"דיין בטריפולי, עלה לארץ-תשו.","s":"אוצר הרבנים 12443; ארזי הלבנון"},{"i":33133,"n":"נחום איש גמזו","dt":"טו אב"},{"i":33134,"n":"נחום גבריאל מיאנינה","b":"מחכמי יאנינה-תעד.","s":"רוזניס-תורכיה-ד"},{"i":33135,"n":"נחום הכהן כץ מצעהלים","bp":"צעהלים","dt":"תקע - יא חשון","dp":"פרשבורג","b":"תלמיד החת\"ס. נפטר בבחרותו, ונספד ע\"י החת\"ס.","s":"החת\"ס ותלמידיו"},{"i":33136,"n":"נחום הכהן מהוסיאטין","f":"אלישע גוטמן מפרמישלן","bt":"תרלח","bp":"רוזין","dt":"תרפה","b":"חתן ר יהושע שפירא מרוזין. רב בהוסיאטין, מיקוליניץ, וינה-תרף - שם עמד בראש ישיבת הוסיאטין, בנו ר יהושע על מקומו בראש הישיבה בוינה.","s":"וונדר-גליציה ח\"ג"},{"i":33137,"n":"נחום הכהן משלוניקי","b":"רב בשלוניקי-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":33138,"n":"נחום טיטיווסקיע מבויאן","b":"גבאי הקלויז בבויאן, חתם-תרנו מטעם הקלויז.","s":"מתוך קטלוג"},{"i":33139,"n":"נחום יהודה ליב מטרטקוב","b":"רב בטרטקוב-תקסד.","s":"וונדר-גליציה ח\"ג"},{"i":33140,"n":"נחום ישעיה","f":"צבי","s":"אוצר הרבנים 15921"},{"i":33141,"n":"נחום ליפא חנניה מוורנה-ליטא","dt":"תרע","dp":"ווארנה","b":"רב בווארנה(=וורנה), הקים בה ישיבה ועמד בראשה, כמו כן יסד ת\"ת, וחברת \"ביקור חולים\".","s":"ליטא"},{"i":33142,"n":"נחום מאיר בהרי\"ת (אולי קרליץ?)","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":33143,"n":"נחום מואסילקוב","b":"תלמיד ר אברהם יהושע השל מאפטא, ור ישראל מרוזין.","s":"אלפסי"},{"i":33144,"n":"נחום מזאמוט וטבריה","b":"מחכמי עדת החסידים בטבריה בזמן ר אברהם מקאליסק.","s":"פרומקין-תח\"י"},{"i":33145,"n":"נחום מטרנופול","b":"רב בטרנופול-תרמח.","s":"וונדר-גליציה ח\"ג"},{"i":33146,"n":"נחום מטרנטשין","f":"שלמה מטרנטשין","k":"בעל דמע עיני","b":"תלמיד החת\"ס. מחכמי פעסט-תר. רב באויבן-תריח.","s":"החת\"ס ותלמידיו"},{"i":33147,"n":"נחום מיכל הכהן מפלאנגן","b":"רב בפלאנגן","s":"אוצר הרבנים 15930"},{"i":33148,"n":"נחום מיכל מאוסטרהא","f":"יוסף משה מקומרנא","dt":"תקפו - כט אדר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בן המגיד מקומרנא ואוסטרהא, ונכד ר אליעזר בן צבי הירש מאוסטרהא.","s":"אוסטרהא רמב"},{"i":33149,"n":"נחום מירושלים","f":"שמחה","b":"מחכמי ירושלים, חתם-תקצז על שטר שליחות ר אברהם מאיר בער.","s":"פרומקין-תח\"י"},{"i":33150,"n":"נחום מלאסק","b":"בנו או נכדו של ר שמואל מואדיסלב ופיורדא, גביר בלאסק. חתניו: ר חיים יעקב הורביץ מלאסק, ר דוד מלאסק, ר נחמן מלאסק.","s":"עיר לאסק וחכמיה"},{"i":33151,"n":"נחום מלודמיר","f":"שלמה מלודמיר","k":"אדמור מלודמיר","b":"רב בלודמיר-תרמ. נינו של ר שלמה הלוי מקרלין. חתן ר מנחם מאניש מרגליות מדוביסאר-חתן ר יעקב אריה ליב מקאוועל (נסכיז).","s":"אוצר הרבנים 15875; אלפסי"},{"i":33152,"n":"נחום מלנצהוט","b":"רב בלאנצוט-תק\"י","s":"אוצר הרבנים 15841"},{"i":33153,"n":"נחום מנארול","f":"אהרן בן אשר ישעיה","b":"נכד ר אשר ישעיה מרופשיץ. חתן ר אברהם ריינמן מנארול. רב חסידי הוסיאטין בנארול.","s":"אלפסי"},{"i":33154,"n":"נחום מסלונים","b":"תלמיד ר מרדכי מלכוביץ, ונסע גם אל ר משה מקוברין.","s":"אלפסי"},{"i":33155,"n":"נחום מצוזמיר","b":"חתן ר יצחק איזיק כץ מאוסטרהא. רב בצוזמיר-תץ בערך.","s":"אוסטרהא מד"},{"i":33156,"n":"נחום מקאפוסט","f":"גרשון חריף ממינסק","b":"רב בקאפוסט. בנו - ר דב בער מויטבסק.","s":"מינסק-איזנשטט"},{"i":33157,"n":"נחום מקובנא וויליאמפול","b":"אב\"ד ויליאמפול-תקפח אצל ר חנוך הניך איטלסון וחתם עמו-תקפח ועם ר ישעיה בן יצחק. חתנו - ר אברהם יצחק בן שלמה צבי דיבעש, ונכדו - ר אליהו זלמן שהו\"ל את יסוד יוסף - וילנא תרמא.","s":"ליפמן-קובנא"},{"i":33158,"n":"נחום משאדובה","b":"מרבני שאדובה","s":"אוצר הרבנים 15924"},{"i":33159,"n":"נחום משידלוב","b":"רב בשידלוב-תק\"צ","s":"אוצר הרבנים 15843"},{"i":33160,"n":"נחום שטינקריצער הכהן מוילנא","b":"מחכמי וילנא. הוא או בנו - ר ברוך הכהן מלעבעדאווא - חתן ר ליב מויליקא.","s":"אהלי שם"},{"i":33161,"n":"נחום שמעון מנעמענצין","f":"נתן נטע","k":"בעל פרי עץ הדר","bp":"איוויע-פלך וילנא","dt":"תרם - ו סיון","dp":"וילנא","b":"תלמיד ר יצחק שירווינטער מאנטאקליא. חתן דודו, ובזיוו\"ש חתן ר יעקב קאוונער. מו\"צ באנטאקליא ור שלמה הכהן על מקומו אחריו, נימנצין.","s":"אוצר הרבנים 15937; עיר וילנא ח\"א"},{"i":33162,"n":"נחום שמש מוילנא","f":"חיים","b":"מו\"צ מחכמי וילנא. בניו: ר זאב וולף, ר יהושע, ר יחיאל מיכל, ר שלום מוילנא. על שמו אחד הבתים ברחוב היהודים בוילנא.","s":"עיר וילנא ח\"ב; בית העלמין בוילנא-קלויזנר"},{"i":33163,"n":"נחום, אפרים חיים מעירק וירושלי","f":"דניאל","k":"בעל צביוננו הלאומי","bt":"תרנז","bp":"כירכוך-עירק","b":"עלה לארץ, ועסק בפעילות צבור, פרסם מאמרים בעתונות העברית, הטיף ללאומיות עברית.","s":"גאון-יהודי המזרח"},{"i":33164,"n":"נחום, דוד מתונס","dt":"תשח","dp":"תונס","b":"דיין בתונס, תלמיד ר' שלמה דאנה","s":"ארזי הלבנון"},{"i":33165,"n":"נחום, חיים מקושטא","f":"בכור יוסף נחום","bt":"תרלג או תרלא","bp":"מאגניסה-ליד אזמיר","dt":"תשך","dp":"מצרים","b":"למד תורה בטבריה, למד מדעים באזמיר וקושטא, תלמיד ביהמ\"ד לרבנים בפאריס ונסמך להוראה, נסע לאתיופיה-תרסח והביא הוכחות ליהדותם של ה\"פלשים\"-תרסח ופעל לשלוח מורים מטעם כי\"ח כדי ללמדם, חכם באשי בקושטא-תרסט והיה מחלוקת כנגדו בגלל שהיה מחניכי כי\"ח, רב ראשי במצרים-תרפו, עבר לפאריס.","s":"אוצר הרבנים 6511; גאון-יהודי המזרח; ארזי הלבנון"},{"i":33166,"n":"נחום, יהודה מטריפולי","f":"פנחס","bt":"תקך","dt":"תקץ - בערך","b":"סופר דווקני בטריפולי, חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":33167,"n":"נחום, ישראל יהודה בכור מאזמיר","bt":"תרנד","bp":"מאגניסיה","b":"פעיל צבור באזמיר, עלה לירושלים-תרצה, עבר לתל אביב.","s":"גאון-יהודי המזרח"},{"i":33168,"n":"נחום, נסים מטריפולי","f":"כלפלא","k":"בעל לבנת הספיר","bt":"תרכא-ד","bp":"טריפולי","dt":"תרפז - טו שבט","dp":"ירושלים","b":"מחכמי טריפולי (בתחלתה עסק במסחר עד ששד\"ר מארץ ישראל השפיע עליו לעסוק בתורה), עלה לירושלים-תרנו והצטרף ל\"בית אל\". ממיסדי (עם אחרים) הישיבות \"רחובות הנהר\", \"פורת יוסף\", \"גן הלבנון\", וישיבת \"שער השמים\" - לחכמי אשכנז. ממיסדי חברת \"כתר תורה\" שלימים התפשטה ברחבי המזרח ואף עד לעיר ניו יורק. הו\"ל ספרי קבלה. חיבר \"לבנת הספיר\". חתניו ר שלום סתהון, ור מטלוב עבאדי.","s":"גליס; אוצר הרבנים 16059; גאון-יהודי המזרח; ארזי הלבנון; מלכי חי\"ל-מרציאנו"},{"i":33169,"n":"נחום, פנחס מלוב","bt":"תרל","dt":"תש - בערך","b":"רב בבנגזי, ודיין אצל ר כמוס פלאח.","s":"מלכי חי\"ל-מרציאנו"},{"i":33170,"n":"נחומוביץ, שבתי משדליץ וחיפה","bt":"תרנג","bp":"אישישוק","dt":"תשלא - א אב","dp":"חיפה","b":"תלמיד ישיבת נוברדוק, ברח מרוסיה לפולין, ראש ישיבת נוברדוק בשדליץ, עלה לארץ-תרצג והקים ישיבת נוברדוק בחיפה-תרצה, ר\"מ ומשגיח בישיבת תפארת ישראל בחיפה. מאמרים ממנו ב\"צפונות\" יב ושם גם תולדותיו.","s":"מתוך קטלוג"},{"i":33171,"n":"נחייאסי, כמוס מטריפולי","bt":"תרס","dt":"תשל - בערך","b":"תלמיד ר ציון ביתאן. דיין בטריפולי-תש, עלה לארץ וכיהן כרב במעברת \"ידי המעביר\". נזכר ב\"ספר לנו ולבנינו\" - ת\"א 1986.","s":"מלכי חי\"ל-מרציאנו"},{"i":33172,"n":"נחימובסקי, דב מגולדינגן","dt":"תרצ - כא שבט","b":"רב בגולדינגן","s":"אוצר הרבנים 4566"},{"i":33173,"n":"נחימובסקי, שמעון ניסן מארה\"ב","k":"בעל דברים נחמדים","b":"חיבר \"דברים נחמדים\" ניו יורק תרעג.","s":"אמריקה"},{"i":33174,"n":"נחמד, אהרן מחלב","f":"שלמה","dp":"אורפה","b":"מחכמי חלב-לפני תר, הוזמן לכהן כראב\"ד בבגדד ונפטר בדרכו באורפה-תורכיה.","s":"גאון-יהודי המזרח"},{"i":33175,"n":"נחמד, אליהו מדמשק","b":"מחכמי דמשק, נאסר בזמן עלילת הדם, ואחר עבר לקהיר, יסד ישיבה בחלב.","s":"גאון-יהודי המזרח"},{"i":33176,"n":"נחמד, בנימין מטבריה","f":"יהודה","dt":"תרנד - יא תשרי","dp":"טבריה","b":"מחכמי טבריה, בשליחות במרוקו-תריז עם ר מאיר אבולעפיה, בשנת תרכג בטריפולי בשליחות ושם הסכים על ספר \"מעשי רקח\" לר מסעוד חי רקח שנדפס בליוורנו. בשנת תרכה בשליחות טבריה לארצות ערב.","s":"גליס; ארזי הלבנון; שא\"י, טוב רא\"י, שנה בשנה תשכט."},{"i":33177,"n":"נחמד, דוד מטבריה","bt":"תקכא","bp":"טבריה","dt":"תרז","dp":"טבריה?","b":"מחכמי טבריה, חתם כנגד אספת הריפורמים בברונשוויג ב\"קנאת ציון\", הסכים על \"אמת ליעקב\"-תרג, בשליחות הקהלה.","s":"מתוך קטלוג"},{"i":33178,"n":"נחמד, חיים מחלב","f":"שלמה מחלב","bt":"תרא","dt":"תרעו - א סיון","b":"רב בארם צובא.","s":"אוצר הרבנים 6084; גאון-יהודי המזרח"},{"i":33179,"n":"נחמד, יהודה מטבריה","f":"חיים יוסף","bt":"תקכא","bp":"טבריה","dt":"תרז","dp":"טבריה","b":"רב בחלב, טבריה אצל ר יצחק אבולעפיה, בשליחות במרוקו-תקסא, חתם על כתב שליחות ר שמואל קושטא, ועל אגרות ותעודות שונות. בשנת תקצא בשליחות בסוריה, ועקב מחלתו מינה את ר אברהם ענתבי להמשיך במקומו עם חבריו ר מנשה סתהון ור יצחק שלום. חתם על אגרת רבני טבריה \"קול רעש גדול\" אודות רעידת האדמה-תר.","s":"גליס; אוצר הרבנים 7031; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ה; ירושלים לזכר לונץ, ריבקינד \"ציון\" ה-ו."},{"i":33180,"n":"נחמד, מאיר מאר\"ץ","f":"חיים","k":"בעל כתר ארם צובא","bt":"תרלו","bp":"חלב","dt":"תשג - כד אייר","b":"רב באר\"ץ וממיסדי אגודת ביקור חולים, עלה לארץ-תרצד והתישב בתל אביב. תלמיד ר עזרא חמווי. מתורתו ב\"המאסף\".","s":"ארזי הלבנון; אוצר הרבנים 12907; גאון-יהודי המזרח"},{"i":33181,"n":"נחמד, משה מצפת","b":"מחכמי צפת, בשנת תקכא בשליחות לארצות ערב.","s":"גליס; שא\"י"},{"i":33182,"n":"נחמד, שלמה מחלב","f":"אהרן","bt":"תקנז","dt":"תרכט - כז אלול","dp":"[חלב]","b":"מחכמי חלב-תקנו, דיין אצל ר מרדכי לבטון, ולבסוף ראב\"ד על מקומו אחריו-תריז. חיבר חדושים על הבית יוסף ופסקי דין בכת\"י - ואבדו.","s":"אוצר הרבנים 18536; ארזי הלבנון; גאון-יהודי המזרח"},{"i":33183,"n":"נחמה בכר יעקב משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"בתי אבות\" לר יוסף דוד-תקפה.","s":"זכרון שלוניקי-115"},{"i":33184,"n":"נחמה מלאך, אהרן משלוניקי","b":"גביר בשלוניקי. תרם להקמת בימ\"ד לרבנים - נוסד בתרמז.","s":"זכרון שלוניקי-157"},{"i":33185,"n":"נחמה, חיים אברהם משלוניקי","f":"שבתי משלוניקי","b":"מדפיס ומגיה ספרים בשלוניקי. הדפיס עם אחיו ר חיים כמה ספרים בבית הדפוס של אביו בשלוניקי.","s":"זכרון שלוניקי-108,111; רוזניס-תורכיה-ה,ו"},{"i":33186,"n":"נחמה, חיים משלוניקי","f":"שבתי משלוניקי","dt":"תקפח - יב תשרי","dp":"שלוניקי","b":"דיין בשלוניקי-תקנו, רב בשלוניקי על מקום ר חיים יוסף ן ארדיט-תקפז. הדפיס עם אחיו ר חיים אברהם ספרים בביה\"ד של אביהם. הניח פסקים בכת\"י - ואבדו. נספד מאת ר יעקב רפאל מנשה.","s":"זכרון שלוניקי-108,111; רוזניס-תורכיה-ו"},{"i":33187,"n":"נחמה, יהודה משלוניקי","f":"יעקב","k":"בעל נדחי ישראל ונפוצ","bt":"תקפה-ז","bp":"שלוניקי","dt":"תרנט - טו שבט","dp":"שלוניקי","b":"חתן הגביר ר יהושע מודילאינו. מחכמי שלוניקי, ועסק במסחר, ועסקן צבור. הטיף להשכלה, והתכתב עם חכמי ישראל באירופה ובהם שד\"ל, יעקב שטרן, ר אליעזר אשכנזי מתונס, ישראל כנפלמאכר, ר מרדכי מורטירה ממנטובה, ועוד. למרות פעילותו היה מקורב לרבני העיר ר אשר קובו ור אברהם גטניו. היה עוזרו של ד\"ר משה אלאטיני בשלוניקי, והקים בית ספר מודרני-תרכה בניהולו של שלמה רוזה. תרגם ספר היסטוריה מאנגלית ללאדינו לצורך בית הספר שהקים. יסד את העיתון הראשון בלאדינו בשלוניקי \"איל לונאר\"-תרכה. נשיאה הראשון של כי\"ח בשלוניקי-תרך. החזיק בספריה גדולה וחשובה (ונשרפה בשריפה הגדולה-תרן). חיבר \"נדחי ישראל ונפוצות יהודה\", ותולדות יהודי שלוניקי-וחלקו תורגם לאנגלית - נשרפו גם הם. חיבר גם \"זכרון טוב\", ועוד.","s":"זכרון שלוניקי-127,123,183"},{"i":33188,"n":"נחמה, יואל משלוניקי","dt":"תקלא","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי-80"},{"i":33189,"n":"נחמה, יוסף משלוניקי","f":"דוד","k":"בעל תולדות היהודים ב","bt":"תרם","bp":"שלוניקי","b":"חוקר יהודי המזרח ובעיקר קהלת שלוניקי. פרסם מאמרים בצרפתית וספניולית.","s":"גאון-יהודי המזרח"},{"i":33190,"n":"נחמה, יעקב מירושלים","f":"מרדכי","bt":"תרן","bp":"ירושלים","b":"תלמיד ישיבת \"תפארת ירושלים\", מורה ושו\"ב באלכסנדריה, רב בקורפו-תרצא.","s":"גאון-יהודי המזרח"},{"i":33191,"n":"נחמה, מרדכי רפאל מירושלים","dt":"תרסה - ח שבט","dp":"ירושלים","b":"מחכמי ירושלים.","s":"ארזי הלבנון; גאון-יהודי המזרח"},{"i":33192,"n":"נחמה, משה משלוניקי","f":"שבתי משלוניקי","b":"מחכמי שלוניקי-תקנג. הו\"ל שו\"ת ר אברהם אליגרי, ור יעקב אשכנזי","s":"זכרון שלוניקי-111"},{"i":33193,"n":"נחמה, שבתי משלוניקי","b":"קנה-תקנו את בית הדפוס של בצלאל אשכנזי בשלוניקי, והדפיס עם בניו - חיים, ואברהם?","s":"רוזניס-תורכיה-ה"},{"i":33194,"n":"נחמו, אליהו חי","b":"מחכמי אנקונה-תקמ\"ז","s":"ארזי הלבנון"},{"i":33195,"n":"נחמובסקי, אברהם יצחק משאוועל","bt":"תרמז","bp":"לובץ-ליטא","dt":"תשא - תמוז","b":"מו\"צ ודיין בשאוועלי-ליטא. נספה בשואה עם בני עדתו ביער קוז'י.","s":"אוצר הרבנים 1231,635; ליטא"},{"i":33196,"n":"נחמולי, וידאל שלמה","f":"יוסף","b":"אביו היה רבה של לאריסה (יון), ור וידאל הוציא לאור את ספרי אביו \"אשד הנחלים\" שלוניקי תקמג, ו\"אשדות הפסגה\" שלוניקי תקן. בשליחות ירושלים בתורכיה ורודוס-תקע.","s":"גליס; ארזי הלבנון; בניהו סורה ב וג."},{"i":33197,"n":"נחמולי, יוסף מלאריסה","f":"דוד","k":"בעל אשד הנחלים","dt":"תקנא","b":"חתן ר יצחק ן שאנג'י. תלמיד ר חיים אבולעפיה, ור אלעזר נחמיאש. מחכמי שלוניקי, רב בארטה, לאריסה(=לארסו)-תקמ על מקום ר חיים אבולעפיה. חיבר גם \"אשדות הפסגה\", ועוד.","s":"אוצר הרבנים 8456; זכרון שלוניקי-105; פין-כנסת ישראל; רוזניס-תורכיה-ה"},{"i":33198,"n":"נחמולי, יצחק מירושלים","b":"מחכמי אלכסנדריה-שכט, בזמן ר בצלאל אשכנזי שהסכים עמו על פירוש לסוגייה. עבר לברוסה. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא - עם תלמידיו ר משה הכהן ור משה טיוולי.","s":"גליס"},{"i":33199,"n":"נחמיאש ממראקש","f":"דוד שאול","k":"בעל יוסף חן","b":"חיבר דרושים ופירושים לתורה - תונס תקעה.","s":"ארזי הלבנון"},{"i":33200,"n":"נחמיאש, אברהם מאיטליה","f":"יוסף","b":"חכם ופילוסוף - שנות ה-ר'. העתיק ותרגם את פירוש תומס די אקוינו לאריסטו, עם הקדמה ממנו.","s":"פין-כנסת ישראל"},{"i":33201,"n":"נחמיאש, אברהם מאישקופיה","b":"רב באישקופיה, שאלה ממנו לר יעקב רפאל מנשה ונזכר בספרו \"באר המים\".","s":"רוזניס-תורכיה-ו"},{"i":33202,"n":"נחמיאש, אברהם ממראקש","b":"מו\"ץ במראקש.","s":"מלכי רבנן"},{"i":33203,"n":"נחמיאש, אברהם מספרד וקושטא","f":"נחמיה","dt":"רפח","b":"רב בספרד וגלה לטורקיה. תלמיד הרא\"ם. נזכר בתשובות ר יוסף קארו, ועוד. אחיינו ר אברהם בן אליעזר מביא ממנו שגער באומרים פיוט המזכיר שמות המלאכים.","s":"ארזי הלבנון; אלופי יעקב א-קסח"},{"i":33204,"n":"נחמיאש, אברהם מצפת","f":"יצחק","b":"מחכמי צפת, העתיק ספר אוצרות חיים לר יעקב צמח ור חיים ויטאל.","s":"מתוך קטלוג"},{"i":33205,"n":"נחמיאש, אברהם מקושטא","b":"רב בקושטא-שנות ה-ש'. בן למשפחת המדפיסים הראשונים בקושטא. אחיו - ר דוד - רב בקושטא.","s":"רוזניס-תורכיה-ג"},{"i":33206,"n":"נחמיאש, אברהם מקושטא","dp":"קושטא","b":"מחכמי קושטא-שנות ה-ת', חברו של ר שמואל אדרבי מקושטא.","s":"רוזניס-תורכיה-ד"},{"i":33207,"n":"נחמיאש, אברהם משלוניקי","bt":"שסד-א אלול","dt":"תסד","dp":"שלוניקי","b":"ר\"מ בשלוניקי.","s":"ארזי הלבנון; אלופי יעקב א-קסז"},{"i":33208,"n":"נחמיאש, אברהם משלוניקי","dt":"שיט - ב תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי","s":"עמנואל-שלוניקי"},{"i":33209,"n":"נחמיאש, אברהם משלוניקי","dt":"תד - ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"אוצר הרבנים 632; עמנואל-שלוניקי"},{"i":33210,"n":"נחמיאש, אברהם משלוניקי וקושטא","dt":"שסד - א אלול","dp":"שלוניקי","b":"חתן ר דוד ן נחמיאש משלוניקי. רב בקושטא, שלוניקי. אחיו - ר דוד - רב בקושטא ושלוניקי.","s":"זכרון שלוניקי; גרינוולד-סלובקיה והונגריה; מלכי רבנן; רוזניס-תורכיה-ג"},{"i":33211,"n":"נחמיאש, אברהם ן מפורטוגל","b":"רב ורופא. חיבר ספר רפואות בלטינית - ונציה שנא. חיבר פירוש על איכה - בכת\"י. (נזכר בכנסת הגדולה).","s":"איטליה גירונדי-א צג"},{"i":33212,"n":"נחמיאש, אהרן ממצרים","f":"יצחק","b":"מדפיס במצרים-תק אצל אברהם יתום.","s":"רוזניס-תורכיה-ה"},{"i":33213,"n":"נחמיאש, אהרן משלוניקי","dt":"תמב","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה-תמב.","s":"זכרון שלוניקי-54"},{"i":33214,"n":"נחמיאש, אלברטו משלוניקי","b":"רופא בשלוניקי-תרס.","s":"זכרון שלוניקי-187"},{"i":33215,"n":"נחמיאש, אליעזר מקושטא","f":"הדריאל","b":"מחכמי קושטא-שן, וממונה על הגיטין. נזכר בספרי חכמי דורו ובהם מהראנ\"ח. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא.","s":"אלופי יעקב א-תשמז; רוזניס-תורכיה-ב,ג"},{"i":33216,"n":"נחמיאש, אליעזר משלוניקי","f":"רפאל אליעזר-הון רב","b":"רב בשלוניקי. בנו - ר רפאל אליעזר מירושלים.","s":"רוזניס-תורכיה-ה"},{"i":33217,"n":"נחמיאש, אלעזר מאישקופיה - הנכד","b":"נכד ר אלעזר נחמיאש משלוניקי. מחכמי שלוניקי, רב באישקופיה-תקעט.","s":"זכרון שלוניקי-111"},{"i":33218,"n":"נחמיאש, אלעזר מסופיה","b":"דיין בסופיה-תקסז אצל ר חיים יעקב משה הלוי, יחד עם ר יעקב בן יצחק בנבנישתי.","s":"רוזניס-תורכיה-ו"},{"i":33219,"n":"נחמיאש, אפרים משלוניקי","f":"אברהם","b":"דיין בשלוניקי-שסה.","s":"זכרון שלוניקי"},{"i":33220,"n":"נחמיאש, אפרים משלוניקי - ג","b":"מו\"צ בקהלת עץ חיים בשלוניקי-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":33221,"n":"נחמיאש, אפרים משלוניקי - הזקן","f":"אברהם","dt":"שך - יא תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי נכדו - הדיין בעל אותו השם.","s":"עמנואל-שלוניקי"},{"i":33222,"n":"נחמיאש, בכור יעקב מאיר","bt":"תקפג","dt":"תרמז - יג אד\"ב","dp":"שלוניקי","b":"רב הכולל בשלוניקי, לצדו של ר שמואל ארדיטי. הניח חדושים בכת\"י - ואבדו. המציא בנעוריו את המשקה \"ראקי נחמיאש\" המכונה \"ראקי די לה קאזה דיל חכם נחמאיש\" שהיה מפורסם בטיבו עד חורבן הקהלה בשואה.","s":"אוצר הרבנים 10215; זכרון שלוניקי-148; גאון-יהודי המזרח"},{"i":33223,"n":"נחמיאש, דוד מוידין","f":"יעקב","b":"רב בוידין - שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":33224,"n":"נחמיאש, דוד מירושלים","b":"מחכמי ירושלים-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":33225,"n":"נחמיאש, דוד מירושלים - א","dt":"תרעד - כב כסלו","b":"מגדולי חכמי ירושלים","s":"אוצר הרבנים 4924"},{"i":33226,"n":"נחמיאש, דוד ממראקש","b":"מחכמי מראקש, אביו של ר שאול בעל \"גבעת שאול\".","s":"מלכי רבנן"},{"i":33227,"n":"נחמיאש, דוד מספרד וקושטא - א","f":"יעקב מספרד","dt":"רעא","b":"ממגורשי ספרד בקושטא, הקים עם אחיו-שמואל את הדפוס הראשון בקושטא. בנו - כנראה ר שמואל - על שם אחיו.","s":"רוזניס-תורכיה-א"},{"i":33228,"n":"נחמיאש, דוד משלוניקי - א","dt":"שסב-ד או שם","dp":"שלוניקי","b":"בן למשפחת המדפיסים הראשונים בקושטא. רב בקושטא, שלוניקי, תלמיד מהרשד\"ם, ראש ישיבת מהרשד\"ם על מקום ר שבתי יונה, ובה למד ר אברהם הלוי בעל \"עין משפט\", כתב פסקים רבים שנדפסו בספרי חכמי דורו. השגות על הטור בכתב יד. חתם בשנת שמז על התקנה לשחרר תלמידי חכמים ממס, והסכים על תקנת הנגיד ר יצחק שולאל-שנג. אחיו - ר אברהם - רב בשלוניקי וקושטא.","s":"גליס; אוצר הרבנים 4923; ארזי הלבנון; זכרון שלוניקי; , מצבות שלוניקי; מלכי רבנן; פין-כנסת ישראל; רוזניס-תורכיה-ג"},{"i":33229,"n":"נחמיאש, הדריאל","k":"המאור הגדול","b":"מרביץ תורה בקושטא-ת\"כ","s":"ארזי הלבנון"},{"i":33230,"n":"נחמיאש, חיים משלוניקי","f":"משה","dt":"תג - ד אב","dp":"שלוניקי","b":"נהרג צעיר.","s":"עמנואל-שלוניקי"},{"i":33231,"n":"נחמיאש, חיים שמואל משלוניקי","f":"רפאל אלעזר-הון רב","dt":"תקמב - כא סיון","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים. הגיה \"מלך שלם\"-תקכט, חיבר הקדמה ל\"מכתם לדוד\"-תקלב. מתורתו בספר אביו - \"הון רב\". נפטר צעיר. בנו - ר רפאל.","s":"גליס; אוצר הרבנים 17870 ו-7692; זכרון שלוניקי-85; גאון-יהודי המזרח; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":33232,"n":"נחמיאש, יאשיהו","b":"מחכמי צפת-תנ\"ז","s":"ארזי הלבנון"},{"i":33233,"n":"נחמיאש, יהודה משלוניקי","f":"יעקב","dt":"שעח - תמוז","dp":"שלוניקי","b":"תלמיד ר אברהם מוטאל. מחכמי שלוניקי. (רוזניס מונהו בין החכמים משנות ה-ת').","s":"זכרון שלוניקי; מלכי רבנן; רוזניס-תורכיה-ד"},{"i":33234,"n":"נחמיאש, יהושע משלוניקי","k":"בעל מגדול ישועות","b":"מקובל מחכמי שלוניקי.","s":"אוצר הרבנים 7595; גאון-יהודי המזרח"},{"i":33235,"n":"נחמיאש, יוסף ממראקש","f":"מסעוד","k":"בעל פירוש אבות","b":"מחכמי מרוקו - אולי ממראקש. נזכר אצל ר שמואל ן דנאן שחיבר פירוש אבות.","s":"מלכי רבנן"},{"i":33236,"n":"נחמיאש, יוסף מספרד","f":"יוסף","k":"בעל פירוש לאסתר","b":"תלמיד הרא\"ש. מגדולי חכמי ספרד-שנת ס'. חיבר פירוש לאסתר. בנו - ר דוד מטולדו.","s":"אוצר הרבנים 8457; אלופי יעקב א-תתקסג; גאון-יהודי המזרח; פין-כנסת ישראל"},{"i":33237,"n":"נחמיאש, יוסף מרודוס","b":"דיין ברודוס-תמ אצל ר דוד חיים הלחמי.","s":"רוזניס-תורכיה-ד"},{"i":33238,"n":"נחמיאש, יעקב מדנאת-מרוקו","k":"מול אנמאי","dp":"כפר זאווית סידי רחאל-מרוק","b":"מצאצאי ר מסעוד נחמיאש. מחכמי דמנאת-מרוקו.","s":"מלכי רבנן"},{"i":33239,"n":"נחמיאש, יעקב מניקופול","b":"רב בניקופול-שטז. שאלות ממנו לר יוסף קארו.","s":"רוזניס-תורכיה-ב"},{"i":33240,"n":"נחמיאש, יעקב מפאס","b":"סופר בפאס-שלז.","s":"מלכי רבנן"},{"i":33241,"n":"נחמיאש, יעקב מצפת","b":"מגדולי חכמי צפת-ש\"כ","s":"אוצר הרבנים 9775"},{"i":33242,"n":"נחמיאש, יעקב משלוניקי","dt":"תקנג","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-105"},{"i":33243,"n":"נחמיאש, יעקב משלוניקי","dt":"תרלד","dp":"שלוניקי","b":"דיין לנזקי שכנים. מתלמידיו - ר יהודה קובו, ור שמעון מנשה.","s":"זכרון שלוניקי-141"},{"i":33244,"n":"נחמיאש, יעקב משלוניקי","f":"מאיר","dt":"תרמט","dp":"שלוניקי","b":"דיין יתומים ואלמנות בשלוניקי.","s":"זכרון שלוניקי-152"},{"i":33245,"n":"נחמיאש, יעקב משלוניקי - א","dt":"שכז","dp":"ברוסה","b":"מחכמי שלוניקי, חתם על הסכמות הקהל בשלוניקי, בשליחות ה\"מוסילימליק\"(=שליחות על המס למוסילין - מושל העיר) בברוסה, בשליחות-שכו קהלת שלוניקי בקושטא אצל השולטן ושריו - ונפטר בשליחותו.","s":"זכרון שלוניקי"},{"i":33246,"n":"נחמיאש, יעקב משלוניקי - ב","b":"תלמיד ר מרדכי מטאלון. מחכמי שלוניקי-שפ.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":33247,"n":"נחמיאש, יעקב שלמה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה.","s":"זכרון שלוניקי-214"},{"i":33248,"n":"נחמיאש, יצחק מאנקונא","dt":"שיו - ה אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":33249,"n":"נחמיאש, יצחק מירושלים","f":"יעקב","b":"מחכמי ירושלים, בשנת רסט חתם על התקנה לשחרור תלמידי חכמים ממס, היה סופר הקהלה בירושלים.","s":"גליס; גאון-יהודי המזרח; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":33250,"n":"נחמיאש, יצחק מצפת","b":"מחכמי צפת בשנים תמח - תנח, חתם על כתב שליחות ר יוסף שאלתיאל קנפנטון בשנת תנח, ועל פסק דין ר משה חיון בענין קהלת טבריה-תע בערך.","s":"גליס; ארזי הלבנון; רוזניס-תורכיה-ד,ה"},{"i":33251,"n":"נחמיאש, יצחק מקורדובה-ספרד","b":"דיין בקורדובה, עבר לפאס-מרוקו וכיהן כרב ראשי. בידידות עם התשב\"ץ.","s":"ארזי הלבנון"},{"i":33252,"n":"נחמיאש, יצחק משלוניקי","b":"מחכמי שלוניקי-תקעח. חיבר הוספות ל\"זכור לאברהם\" לר אברהם אלקעי.","s":"זכרון שלוניקי-111"},{"i":33253,"n":"נחמיאש, יצחק משלוניקי","b":"גביר מראשי קהלת שלוניקי, השתתף במשלחת אצל השולטן בקושטא-שצז בראשות ר יהודה קובו - שנהרג עק\"ה בידי השולטן.","s":"זכרון שלוניקי"},{"i":33254,"n":"נחמיאש, יצחק משלוניקי","dt":"תרלה","dp":"שלוניקי","b":"מחכמי שלוניקי. פסק ממנו ב\"ימי דוד\" לר דוד קרסו.","s":"זכרון שלוניקי-141"},{"i":33255,"n":"נחמיאש, ישראל משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":33256,"n":"נחמיאש, לוי מפאס","b":"מחכמי פאס-שנות ה-ר'. מתורתו ב\"מראה עינים\" לר אלעזר בהלול.","s":"מלכי רבנן"},{"i":33257,"n":"נחמיאש, לוי מצידון","dt":"תה - אחרי","dp":"חברון?","b":"רב בצידון, עלה לחברון והיה שם בשנת תה ובשנת תיב, חתם בשנת תכא על כתב שליחות של ר חייא דיין.","s":"גליס; אוצר הרבנים 12469; גאון-יהודי המזרח"},{"i":33258,"n":"נחמיאש, לוי משלוניקי - ב","k":"בעל פירוש לזהר","b":"מחכמי שלוניקי, עלה לירושלים, בשליחות חברון-תרח באיטליה עם ר יצחק פרחי- היה בפדובה בשנת תרט. הסכים על ספר \"מירא דכיא\" לרב גירונדי. חיבר פירוש לזוהר בכתב יד.","s":"גליס; איטליה גירונדי-ל ה; אוצר הרבנים 12470; ארזי הלבנון; פרומקין-תח\"י"},{"i":33259,"n":"נחמיאש, מאיר משלוניקי","f":"יעקב","dt":"תרמא - טו טבת","dp":"שלוניקי","b":"רב בשלוניקי","s":"אוצר הרבנים 12908; גאון-יהודי המזרח; ארזי הלבנון"},{"i":33260,"n":"נחמיאש, מאיר משלוניקי","b":"דיין בשלוניקי-תקץ.","s":"זכרון שלוניקי-111"},{"i":33261,"n":"נחמיאש, מסעוד מדמנאת-מרוקו-א","f":"יעקב","b":"רב בדמנאת-מרוקו. מקובל ומלומד בנסים. בנו - ר יוסף, נכדו ר שאול בעל \"וישמע שאול\".","s":"ארזי הלבנון; מלכי רבנן"},{"i":33262,"n":"נחמיאש, מסעוד מדמנאת-מרוקו-ב","f":"יוסף","b":"מחכמי דמנאת-תקצד.","s":"מלכי רבנן"},{"i":33263,"n":"נחמיאש, מסעוד ממכנאס","b":"מחכמי מכנאס, חתם-תקכח על פס\"ד עם ר שמואל ן ואעיש.","s":"מלכי רבנן"},{"i":33264,"n":"נחמיאש, מרדכי מביירות","b":"דיין בביירות-תלד עם ר יוסף הכהן אשכנזי ור אברהם נחמיה.","s":"רוזניס-תורכיה-ד"},{"i":33265,"n":"נחמיאש, משה מטריפולי","bt":"תק","dt":"תקעד","b":"דיין בטריפולי. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":33266,"n":"נחמיאש, משה מירושלים","b":"רב בירושלים. חתם על קיום שטר משפחת אמזליג-תריד. ראש ישיבת \"כנסת יחזקאל\" יחד עם ר\"י פרג.","s":"אוצר הרבנים 14947; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י"},{"i":33267,"n":"נחמיאש, משה מספרד","f":"אברהם","b":"תלמיד הרא\"ש בטולדו.","s":"ארזי הלבנון"},{"i":33268,"n":"נחמיאש, משה משלוניקי","dt":"תקלח - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"סוכת דוד\" לר דוד שירירו-תקלח.","s":"זכרון שלוניקי-94"},{"i":33269,"n":"נחמיאש, משה משלוניקי","b":"מחכמי שלוניקי. הסכים על פסק של ר אברהם דוד בשלוניקי-תקעב.","s":"זכרון שלוניקי-111"},{"i":33270,"n":"נחמיאש, משה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה.","s":"זכרון שלוניקי-214"},{"i":33271,"n":"נחמיאש, סעדיה משלוניקי","b":"דיין בשלוניקי-שיט."},{"i":33272,"n":"נחמיאש, רפאל אליעזר - הנכד","f":"חיים שמואל או אליעזר","dt":"תקסו - יז חשון","dp":"ירושלים","b":"נכד ר רפאל בעל הון רב. מחכמי ירושלים ומאנשי \"בית אל\".","s":"גליס; אוצר הרבנים 17847; גאון-יהודי המזרח; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":33273,"n":"נחמיאש, רפאל אלעזר חיים משלוני","f":"שמואל","k":"בעל הון רב","bt":"תנח","dt":"תקלח - ג אלול","dp":"ירושלים","b":"גיסו של ר יוסף שמואל מודיליאנו. דיין בשלוניקי עם ר יצחק הלוי ור משה בן יוחנן הירירה. רב הגדול בשלוניקי-תקכג על מקום ר יהושע בדרשי ור משה הירירה, ור רפאל חיים אברהם קובו על מקומו אחריו, עלה לירושלים-תקלו. חיבר הקדמות לכמה ספרים, חיבר 119 דרושים, שו\"ת, ומכתביו נדפס \"הון רב\" שלוניקי תקלז-תקמד, כמה מחבוריו אבדו (בהקדמת ספרו מתאר שנאלץ לעזוב את שלוניקי בגלל התנכלויות של כמה גבירים - ור דוד פיפאנו ב\"שלשלת רבני שלוניקי\" מספר כי הגבירים עקרו כמעט מכל המהדורה של הספר את דבריו אלו נגדם). בימיו \"קנו\" היהודים את העיר מידי שר העיר ל-100 שנה לצורך העירוב. בניו - ר אלעזר, ר חיים שמואל רב בשלוניקי, וחתנו - ר יצחק אברהם מולכו. מתלמידיו - ר יוסף נחמולי מלארסו. הסכים על \"למנצח לדוד\"-תקכה, \"מכתם לדוד\"-תקכט, \"ארחות צדיקים\"-תקל, \"צמח צדיק\"-תקלא, ועוד.","s":"גליס; אוצר הרבנים 17848; גאון-יהודי המזרח; ארזי הלבנון; זכרון שלוניקי-80,83; פרומקין-תח\"י; רוזניס-תורכיה-ה","bk":[["הון רב [ח\"א - עה\"ת, ח\"ב - שו\"ת]",""]]},{"i":33274,"n":"נחמיאש, רפאל חיים שמואל","f":"אליעזר (רפאל)","dt":"תקסב - כא סיון","dp":"ירושלים","b":"מחכמי ירושלים. (שנת פטירתו נרשמה גם - תקמב ותקמח).","s":"פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":33275,"n":"נחמיאש, שאול ממרוקו","f":"דוד","k":"בעל ויאמר שאול","b":"מחכמי מרוקו, חתם על הסכמה לפס\"ד מאת רבני צפרו בראבאט-תרו. חיבר גם \"גבעת שאול\", \"וישמע שאול\", ועוד.","s":"ארזי הלבנון; מלכי רבנן"},{"i":33276,"n":"נחמיאש, שלם מארץ ישראל","dt":"תצה","dp":"מרוקו","b":"סוחר מחכמי ארץ ישראל, היה במרוקו-תצג ונהרג עק\"ה-תצה.","s":"גאון-יהודי המזרח"},{"i":33277,"n":"נחמיאש, שלם מישראל ומרוקו","dt":"תצג - כח כסלו","b":"מחכמי ארץ ישראל עסק במסחר במרוקו, נהרג בפקודת הממשלה, ונזכר אצל היעב\"ץ.","s":"מלכי רבנן"},{"i":33278,"n":"נחמיאש, שלמה ממונשטיר","f":"משה","b":"רב במונשטיר-שץ.","s":"רוזניס-תורכיה-ג"},{"i":33279,"n":"נחמיאש, שלמה ממרוקו","f":"שאול","k":"בעל ויחכם שלמה","dt":"תרסב","dp":"[מראקש]","b":"רב במראקש.","s":"ארזי הלבנון"},{"i":33280,"n":"נחמיאש, שלמה משלוניקי","b":"דיין בשלוניקי-תקץ. חיבר שו\"ת בכת\"י - והיה בידי ר דוד פיפאנו.","s":"זכרון שלוניקי-111"},{"i":33281,"n":"נחמיאש, שם טוב משלוניקי","f":"מאיר","dt":"תרסט","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-191"},{"i":33282,"n":"נחמיאש, שמואל יצחק משלוניקי","dt":"תקיא","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":33283,"n":"נחמיאש, שמואל מאזמיר","b":"רב ביוזיל היסאר - ליד אזמיר - שעז, יחד עם ר משה עובדיה, ר יוסף ור אברהם ניניו.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":33284,"n":"נחמיאש, שמואל מאיפסולה","b":"מחכמי איפסולה-תכז, חתום על ההסכם עם נתן העזתי.","s":"רוזניס-תורכיה-ד"},{"i":33285,"n":"נחמיאש, שמואל מירושלים","dt":"תקי - כו כסלו","dp":"ירושלים","b":"מרבני ירושלים","s":"אוצר הרבנים 19285; גאון-יהודי המזרח; פרומקין-תח\"י"},{"i":33286,"n":"נחמיאש, שמואל ממצרים","b":"דיין ברשיד-שנות ה-ת' אצל ר דוד גרשון.","s":"רוזניס-תורכיה-ד"},{"i":33287,"n":"נחמיאש, שמואל מספרד וקושטא","f":"יעקב מספרד","b":"ממגורשי ספרד בקושטא, הקים עם אחיו-דוד את הדפוס הראשון בקושטא.","s":"רוזניס-תורכיה-א"},{"i":33288,"n":"נחמיאש, שמואל מקושטא","f":"דוד","b":"מדפיס בקושטא על מקום אביו.","s":"רוזניס-תורכיה-א"},{"i":33289,"n":"נחמיאש, שמואל מרודוס","b":"דיין ברודוס-תם, עם ר יוסף אמאטו.","s":"רוזניס-תורכיה-ד"},{"i":33290,"n":"נחמיאש, שמואל משלוניקי","dt":"תקל","dp":"שלוניקי","b":"גביר בשלוניקי. נהרג עק\"ה-תקל.","s":"זכרון שלוניקי-79"},{"i":33291,"n":"נחמיאש-נמיאש, שלמה משלוניקי","dt":"רפ-רצ","dp":"שלוניקי","b":"מחכמי שלוניקי-רפ.","s":"עמנואל-שלוניקי"},{"i":33292,"n":"נחמיה","b":"מגדולי הראשונים בספרד-שנת פ'","s":"אוצר הרבנים 15939"},{"i":33293,"n":"נחמיה","f":"צבי","b":"רב-שנת תר\"כ","s":"אוצר הרבנים 15940"},{"i":33294,"n":"נחמיה בן אברהם בירך מדוברובנא","f":"ראה: גינצבורג, נחמיה"},{"i":33295,"n":"נחמיה בן חכליה","r":"חלק מהספר של עזרא, לא נכתב על ידי נחמיה","dt":"ט טבת ג' אלפים תמב","s":"מבשר ואומר ט טבת תשעד","bk":[["נחמיה",""]]},{"i":33296,"n":"נחמיה הגדול","b":"תלמיד הבעשט. נזכר בכתבי תלמידי בית קוריץ.","s":"אלפסי"},{"i":33297,"n":"נחמיה הכהן מחנטשין","b":"ראש מדינה בחנטשין-סוף שנות ה-ש'. חתנו - ר אברהם כץ בן יעקב קופל מטארלי.","s":"בובר-לבוב"},{"i":33298,"n":"נחמיה הכהן מפולין","k":"נחמיה הנביא","b":"הגיע אל ש\"ץ בדרדנלים, והכריז עליו כמשיח שקר, וכדי להציל את חייו המיר את דתו לאיסלם, והלשין על ש\"ץ בפני התורכים כמורד, אח\"כ שב ליהדות וחזר לפולין.","s":"רוזניס-תורכיה-ד"},{"i":33299,"n":"נחמיה הלוי מפאס","dt":"תרלב","b":"מחכמי פאס.","s":"מלכי רבנן"},{"i":33300,"n":"נחמיה חי מפיררה","f":"משה","b":"גביר מחכמי פיררה, סייע לר משה ישראל מרודוס בהדפסת ספרו \"משאת משה\".","s":"רוזניס-תורכיה-ה"},{"i":33301,"n":"נחמיה חי מפיררה","f":"יעקב","b":"גביר מחכמי פיררה, סייע לר משה ישראל מרודוס בהדפסת ספרו \"משאת משה\".","s":"רוזניס-תורכיה-ה"},{"i":33302,"n":"נחמיה כץ מקראטיה וטבריה","dt":"תקנה - לפני","b":"מראשי החסידים בארץ. חתם עם ר מנחם מנדל מויטבסק ור אברהם מקאליסק על המכתב לר ישעיהו מדינוביץ. נזכר אצל ר יוסף יהודה ליב מבאלטא.","s":"אלפסי"},{"i":33303,"n":"נחמיה מאוסטרהא","f":"ליב","dt":"תקסח - יב שבט","dp":"אוסטרהא","b":"מגיד באוסטרהא יחד עם ר גרשון דקראסניגורא - בזמן ר ייבי, ואחריו היה ר אשר המגיד, מגיד בדובנא.","s":"אוסטרהא קעד"},{"i":33304,"n":"נחמיה מבבל","f":"כהן צדק","dt":"ד'תשכח (968)","b":"ראש הגולה בבבל בזמן שאחרי רב סעדיה גאון. אחיו של ר חפני גאון.","s":"ארזי הלבנון"},{"i":33305,"n":"נחמיה מבריסק","f":"מרדכי","dt":"תרטז - ט תשרי","dp":"בריסק","b":"גביר מחכמי בריסק. בנו - ר דוד ליב מבריסק.","s":"בריסק-עיר תהלה"},{"i":33306,"n":"נחמיה מגלגוא","f":"אברהם מגלוגא","dt":"תקל - ח טבת","b":"מו\"צ בהנובר","s":"אוצר הרבנים 15943"},{"i":33307,"n":"נחמיה מיוזפוף","dt":"תקצח - כח ניסן","b":"רב ביוזפוף גדול. תלמיד החוזה מלובלין, והיהודי הקדוש מפשיסחא. היה מנהיג עדת חסידים.","s":"אוצר הרבנים 15942; אלפסי"},{"i":33308,"n":"נחמיה ממצרים","f":"אברהם","b":"פייטן מחכמי מצרים, בן דורו של ר האי גאון. מפיוטיו נכנסו למחזורי התפלה, גם אביו וגם בנו ר יאשיה היו פייטנים.","s":"ארזי הלבנון"},{"i":33309,"n":"נחמיה מעכו","f":"נתניה","b":"מחכמי עכו, בשנת ד'תתקצד (1234) חתם על הסכמה על תקנת ר אברהם בן הרמבם.","s":"גליס"},{"i":33310,"n":"נחמיה מתנוס","f":"עובדיה","b":"רב בגאבס-תונס. במאה הי-יא.","s":"ארזי הלבנון"},{"i":33311,"n":"נחמן","f":"הרמב\"ן","b":"מגדולי חכמי ספרד-שנת מ',אליו נכתבה אגרת הרמב\"ן. חיבר חדושים לתלמוד ונדפס פירושו למסכת ביצה.","s":"אוצר הרבנים 15969; ארזי הלבנון"},{"i":33312,"n":"נחמן","f":"יעקב יוסף","s":"אלפסי"},{"i":33313,"n":"נחמן הכהן מטולצ'ין ואומאן","f":"פסח","k":"ר נחמן פסח'לעס","bt":"תקעד","dt":"תרמד","b":"תלמיד ר נתן שטרנהרץ-מנהיג חסידי ברסלב. מחשובי חסידי ברסלב ועמד בראש החסידות על מקום רבו, התגורר באומאן. ביקר בארץ. בנו ר אברהם חזן בעל \"שיחות וסיפורים\" - בני ברק תשכא.","s":"אלפסי; אסף-נאחז בסבך; גידולי הנח\"ל"},{"i":33314,"n":"נחמן הכהן מפריז","k":"בעל נחמני","b":"מגדולי חכמי פאריש-שנת ל'","s":"אוצר הרבנים 15967"},{"i":33315,"n":"נחמן הלוי חזן מטולטשין","f":"אברהם","bt":"תקעד","dt":"תרמד - כו ניסן","b":"תלמיד ר נתן מנמירוב.","s":"אלפסי"},{"i":33316,"n":"נחמן כץ מוילנא","b":"רב בוילנא. חתן ר גדליה מוילנא. נזכרו-תקיא בכתב המינוי של ר שמואל בן אביגדור כרבה של וילנא שלא יערערו על המינוי של ר שמואל. (כמו לר מאיר גינצבורג מויזון)","s":"פין-קריה נאמנה"},{"i":33317,"n":"נחמן ליטוואק מראדויל","f":"ירוחם פישל מסלוצק","dt":"תקנו - כז אלול","b":"חתן ר יצחק מדרוהוביטש. מגיד מישרים בראדויל-וואהלין. גיסו של ר יחיאל מיכל המגיד מזלוטשוב.","s":"אלפסי"},{"i":33318,"n":"נחמן מאיטליה","f":"שמואל","b":"מקובל,מחכמי איטליה-ש\"מ","s":"אוצר הרבנים 15999"},{"i":33319,"n":"נחמן מבאר","k":"ראה: מנחם מבאר","b":"רב בבאר-תקמ\"ה","s":"אוצר הרבנים 15975"},{"i":33320,"n":"נחמן מבריסק","b":"רב בבריסק-ת\"מ","s":"אוצר הרבנים 15970"},{"i":33321,"n":"נחמן מברסלב","f":"שמחה","k":"אדמור מברסלב","r":"האדמו\"ר מברסלב","bt":"תקלב","dt":"תקעא - יח תשרי","b":"נינו של הבעשט. חתן ר אפרים מהוסיאטין, ובזיוו\"ש חתן הגביר ר יחזקאל טרכטינברג מברודי. ביקר בארץ-תקנט והיה אצל משפחתו בטבריה. התגורר במדבידובקא-תקן, זלטיפולא, ברסלב-תקסב, נאווריטש, אוסטראה, זאסלב, דובנא, ברודי, למברג, אומאן-תקע. תלמידו ר נתן הו\"ל את ספריו \"לקוטי מהר\"ן\", ו\"ספר המדות\". בניו שלמה אפרים ויעקב נפטרו בילדותם. חתניו ר יוסף יוסקא אוירבוך בן ר אברהם דב מחמלניק, ר יצחק איזיק מדוברוונא, ר פנחס זזאב ור חיים אורי פייבש הורביץ בני ר אריה יהודה ליב מוואלטשיסק. ר זלמן ליוברסקי בן ר יעקב יוסף - תלמיד רבי נחמן, ר אהרן זסללבסקי בן ר אליהו חתן האדמור מלאדי ורב בקמנצ'וג.","s":"אוצר הרבנים 15977; אלפסי; תוספת להמודיע יד תשרי תשעג עמוד לד; ראה ערך ליקוטי מוהר\"ן; יומא דהילולא","bk":[["ליקוטי מוהר\"ן","חסידות"],["ליקוטי מוהר\"ן (ברסלב)",""],["ליקוטי מוהר\"ן , סיפורי מעשיות , ספר המידות",""],["ליקוטי עצות",""],["סיפורי מעשיות",""],["ספר המידות",""]],"e":"תקל\"ב-תקע\"א"},{"i":33322,"n":"נחמן מהורודנקא","f":"יצחק מזולקוא","r":"המגיד מטריסק","bt":"תם","bp":"זולקווא","dt":"תקכה-לב -ב תמוז","dp":"טבריה","b":"מחסידי הבעש\"ט הראשונים ומחותנו (בנו נשא את נכדת הבעש\"ט - אמו של ר נחמן מברסלב), גיסו של ר חיים מהורודנקא גם הוא ממקורבי הבעש\"ט. עלה לארץ ישראל בשנת תק - בחיי הבעש\"ט, שהה במזיבוז בעת פטירת הבעשט. בשנת תקכד עלה בראש שיירה והתיישב בטבריה (יש אומרים שנפטר באותה שנה ויש אומרים-תקלב). ועסק בפדיון שבויים יחד עם הבעשט. שמר עבור הבעשט את ספריו וכתביו כשנעדר מביתו. יצא כמה פעמים בשליחות לפולין-רוסיה. (ר נחמן נכדו ביקר בטבריה-תקנח - אצל משפחתו שם). בזיוו\"ש חתן ר יוסף ספראוידליוער מפיסטין. מתורתו ב\"מילי דאבות\", \"דגל מחנה אפרים\". בניו ר שמשון חיים שהו\"ל \"עובר אורח\", ור שמחה אבי ר נחמן מברסלב.","s":"גליס; וונדר-גליציה ח\"ג; אוצר הרבנים 15981; אלפסי; פרומקין-תח\"י"},{"i":33323,"n":"נחמן מלבוב","f":"שלמה","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה.","s":"אוצר הרבנים 15971; מצבות קדש-לבוב; בובר-לבוב"},{"i":33324,"n":"נחמן מלבוב","f":"יצחק","dt":"שצח","dp":"לבוב","b":"גביר בלבוב, בנה בית כנסת עם אחיו - הגביר ר מרדכי. אשתו - רויזא המכונה רויזא הזהב היתה בעלת חסד.","s":"בובר-לבוב"},{"i":33325,"n":"נחמן מלובלין","f":"צבי הירש","dt":"תקסו - ח סיון","dp":"לובלין","b":"דיין בלובלין.","s":"לקורות היהודים בלובלין"},{"i":33326,"n":"נחמן מלובלין","dt":"שצו - טז אב","dp":"לובלין","b":"נהרג עק\"ה אחר שסירב להמיר דתו יחד עם ר מרדכי. לזכרם חיבר ר הירש בן מרדכי מלובלין סליחה המתחילה \"אלקים אל דמי לך ואל תחרוש\".","s":"לקורות היהודים בלובלין"},{"i":33327,"n":"נחמן מלודמיר ווילנא","f":"שלמה נפתלי","dt":"תלג","b":"רב בלודמיר,ווילנה. חתם אחרי הט\"ז ביריד גרמניץ-תכד. הסכים על \"מגדל דוד\" לר דוד לידא. מתורתו ב\"לב אריה\".","s":"אוצר הרבנים 15989; עיר וילנא ח\"א"},{"i":33328,"n":"נחמן ממודנא","f":"נחמן","dt":"תכו","b":"רב במודנא, ור אברהם יוסף שלמה גרציאנו על מקומו אחריו.","s":"ארזי הלבנון"},{"i":33329,"n":"נחמן מסוקאל","b":"רב בסוקאל","s":"אוצר הרבנים 15972"},{"i":33330,"n":"נחמן מסקאליט","f":"ישראל מטשאהן","k":"אדמור מסקלט","dt":"תרכו - כו תמוז","b":"נכד המגיד מזלטושוב. רב בקונסטנטין-ישן, סקאליט(=סקלט)-פודוליה-אוקראינה. בניו - ר יוסף, ר ישראל זק מקראיסלוב, ר יחיאל מיכל מסקאליט. חתנו - ר בנימין זאב אוירבך מאוזריאן.","s":"אוצר הרבנים 15973; וונדר-גליציה ח\"ו; אלפסי"},{"i":33331,"n":"נחמן מפוהאסט","f":"יצחק מוולוזין","b":"אחיו של ר חיים מוולוזין. רב בפוהאסט-תקע. בנו - ר אברהם שמחה מאמציסלב.","s":"אוצר הרבנים 15996; שם הגדולים השלישי"},{"i":33332,"n":"נחמן מקוזובה","b":"רב בקוזובה - מתורתו ב\"תהלה לדוד\".","s":"וונדר-גליציה ח\"ג"},{"i":33333,"n":"נחמן מקוסוב","bt":"תעו","dt":"תקטז","b":"מתלמידי הבעשט. הבעשט העריך את כח תפלתו. רב בלודמיר, קוסוב. מפיץ החסידות בבוקובינה. מתורתו ב\"משנת חסידים\". בנו ר משה, נכדו ר שניאור - נזכר בשבחי הבעשט.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 15998"},{"i":33334,"n":"נחמן שלמה הלוי מירושלים","f":"משה","k":"בעל עטרת שלמה","bt":"תקמג","dt":"תריא","dp":"ירושלים","b":"אב\"ד זמושטש חדש, עלה לירושלים, בשנת תרד והיה אבד קהילת האשכנזים, חיבר \"עטרת שלמה\" ירושלים תרז.","s":"גליס; אוצר הרבנים 16018; פרומקין-תח\"י"},{"i":33335,"n":"נחמנזון, אהרן מאיר מהמבורג","f":"דוד","dt":"תרן - יח שבט","dp":"המבורג","b":"מחכמי המבורג.","s":"אוצר הרבנים 1830; דוקס-אוה למושב-ב"},{"i":33336,"n":"נחמני ן, אברהם","b":"מחכמי ספרד, רב בפולקירא","s":"ארזי הלבנון"},{"i":33337,"n":"נחמני ן, דוד","s":"ארזי הלבנון"},{"i":33338,"n":"נחמני, אברהם מאלגיר","bt":"תץ - בערך","dt":"תקס - בערך","b":"מחכמי אלמעסכר-אלגיר. מחזור ממנו בכת\"י - כמנהג תלמסאן, וכן קובץ פיוטים. העתיק את \"מאמר מרדכי\" לר מרדכי דרמון.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33339,"n":"נחמני, לוי סעדיה ממראקש","f":"יעקב","k":"בעל ברית הלוי","bt":"תרפא","bp":"מראקש","dt":"תשנה - ז שבט","dp":"ירושלים","b":"תלמיד ר יעקב אדהאן, ור אברהם אביטבול. מלמיד במראקש, קזבלנקה, ר\"מ בישיבת \"נוה שלום\" במרוקו, ועסק גם בקבלה. עלה לירושלים. חיבר קונטרסים בעניני אמונה וקבלה.","s":"ארזי הלבנון"},{"i":33340,"n":"נחמני, מסעוד ממכנאס","dt":"תף - לפני","b":"מחכמי מכנאס, בניו נתדיינו אצל ר יעקב ן צור=היעב\"ץ, אודות ירושת אביהם-תף.","s":"ארזי הלבנון; מלכי רבנן"},{"i":33341,"n":"נחמני, עזוז מאלכסנדריה","f":"שמעון","dp":"ברוסה","b":"מחכמי אלכסנדריה-שכט, בזמן ר בצלאל אשכנזי שהסכים עמו על פירוש לסוגייה. עבר לקהיר, ברוסה. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא.","s":"ארזי הלבנון; רוזניס-תורכיה-ב,ג"},{"i":33342,"n":"נחמני, שמואל","dt":"תקב","dp":"עכו","b":"מחכמי איטליה, עלה עם שיירת ר חיים בן עטר.","s":"גליס"},{"i":33343,"n":"נחמני, שמעון מטבריה","bp":"טבריה","dt":"תרעח","dp":"באסטייא איי כורסיא","b":"מחכמי טבריה, נאסר בגלל מלחמתו במסיון-תרעד, גורש-תרעו ע\"י התורכים לעיר באסטייא איי כורסייא ונפטר שם.","s":"ארזי הלבנון"},{"i":33344,"n":"נחמני, שמשון חיים מאיטליה","k":"בעל זרע שמשון","b":"מקובל מחכמי איטליה, תלמיד ר אפרים הכהן ליפשיץ ממודנא, ור דוד פינצי, ור אביעד שר שלום באזיליאה. רב ומלמד תורה בסיינה, ריגייו-איטליה. חיבר \"תולדות שמשון\", \"זרע שמשון\", \"קרבן קטורת\" ושירים, פירוש על הזהר - אך ציוה לגנזו בתוך קברו - לאחר שיצא הספר \"מקדש מלך\". מתלמידיו ר חנניה הכהן שהזכירו בספריו.","s":"אוצר הרבנים 20083; איטליה גירונדי-ש כה,ש יו; ארזי הלבנון"},{"i":33345,"n":"נחמקין, חיים מנחם מנדל","b":"חתן ר אליעזר דון יחיא בעל \"אבן שתיה\".","s":"אהלי שם"},{"i":33346,"n":"נחמקין, יוסף","dt":"תשג","b":"רב בזילופא","s":"אוצר הרבנים 8458"},{"i":33347,"n":"נחש, דוד מאנקונא","dt":"שיו - יג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":33348,"n":"נחשון גאון","b":"מתורתו בקבלה בספר האמונות, \"פרדס רמונים\".","s":"איטליה גירונדי-נ ו"},{"i":33349,"n":"נחשון גאון סורא","f":"רב צדוק גאון","b":"גאון סורא-(871) על מקום רב עמרם גאון. ובנו רב האי (לא האחרון) גאון בסורא. חיבר ספר \"ראומה\" על הלכות שחיטה ועוד, עסק בחכמת העיבור ועל שמו \"העיגול דרב נחשון\" לקביעת השנים והתקופות.","s":"ארזי הלבנון"},{"i":33350,"n":"נטונק, יוסף מיאס-באראני","k":"בעל שלשה קמצים","bt":"תקעג","dt":"תרנג","b":"רב ביאס-בערעני-תריד. מחובבי ציון. היה מחלקות כנגדו בקהלה בגלל דרשה שנשא כנגד האמנסיפציה ובעד עליה לארץ, נאלץ לעזוב ועבר לסקש-פהרבאר. חיבר גם \"המשיח\".","s":"אוצר הרבנים 8459; הונגריה; פרשבורג-וינגרטן"},{"i":33351,"n":"נטורנאי גאון","b":"מתורתו בקבלה בספר האמונות, \"פרדס רמונים\". היה גם בפאס, ונאלץ לגלות.","s":"איטליה גירונדי-נ ה; מלכי רבנן"},{"i":33352,"n":"נטיל, יום טוב מטשעכוב ולובלין","f":"מנחם","k":"בעל טהור רעיונים","dt":"תקעז - יג שבט","dp":"לובלין","b":"תלמיד החוזה מלובלין, ראב\"ד בלובלין בזמן כהונת ר עזריאל \"ראש הברזל\" מלובלין כאב\"ד. היה בעל מופתים. רב בטשעכוב. חיבר \"טהור רעיונים\".","s":"אוצר הרבנים 7930; אלפסי; בית העלמין בוילנא-קלויזנר; מבשר ואומר יג שבט תשעג","bk":[["טהור רעיונים – תורה, וכמה מסכתות",""]]},{"i":33353,"n":"נטל, אברהם משה","b":"תלמיד ר יהושע פנחס בומבך בדרוהוביטש-תרס.","s":"וונדר-גליציה ח\"ג"},{"i":33354,"n":"נטל, נטע שלמה מברנוב","f":"יהודה ליבוש","b":"רב בברנוב.","s":"וונדר-גליציה ח\"ג"},{"i":33355,"n":"נטלוביץ, בן ציון מקראקי","f":"אברהם משה","bt":"תרמד","b":"חתן ר מאיר רבינזון מרדושקביץ. רב בקראקי(=קרוק)-פלך קובנא (מחוז קידאן)-תרסז, שאדובה-תרפב.","s":"אוצר הרבנים 3925; אהלי שם; ליטא"},{"i":33356,"n":"נטלוביץ, חיים בן ציון מארה\"ב","f":"מאיר רבינזון","bt":"תרמו","bp":"וילנא","b":"תלמיד ר חיים עוזר גרודזנסקי ונסמך ממנו ומאת: ר אליעזר רבינוביץ, ור חנוך הניך אייגעש מוילנא. חתן ר מאיר רובינזון מרדישקוביץ-פלך וילנא. רב בקרקי(=קראקי)-פלך קובנא-תרע, גנישצק(=גניצשעק)-תרעו, שדובה-תרפב, היגר לארה\"ב-תרפג וכיהן כרב בהריסבורג-פנסילבניה, לואיוויל-קנטקי, קהלת רדישקוביץ בברוקלין-ניו יורק-תשב. פרסם מאמרים ב\"יגדיל תורה\", \"התבונה\", \"הפרדס\", ועוד.","s":"אוצר הרבנים 6262; אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":33357,"n":"נטלוביץ, שמעון מקלוורה","b":"מחכמי קלוורה(=קאלווריה?)-תרסח - תשובה אליו ב\"אהל יהושע\".","s":"וונדר-גליציה ח\"ג"},{"i":33358,"n":"נטע דיין מלובלין","b":"גבאי בח\"ק בלובלין-תצד.","s":"לקורות היהודים בלובלין"},{"i":33359,"n":"נטע מאווריטש","dt":"תקמה - א אב","b":"תלמיד הבעשט. חברו של ר מנחם נחום מטשרנוביל. חתנו - ר אברהם דב מאווריטש.","s":"אלפסי"},{"i":33360,"n":"נטע מאיר מלובלין","f":"מאיר","dt":"תקפב - ז אייר","b":"ספרא ודיינא בלובלין.","s":"לקורות היהודים בלובלין"},{"i":33361,"n":"נטע מגיצבורג","b":"מגדולי חכמי המוסר מוישלישיק-תר\"מ","s":"אוצר הרבנים 16419"},{"i":33362,"n":"נטע ממאלסטריסצנע","k":"הרב הקדוש","b":"מגדולי תלמידי ר דב בר מליובאויטש, וחתנו ר מנחם מנדל. מדריך חסידים בתורת חב\"ד. רב במלסטריסצנע, פינסק.","s":"אלפסי"},{"i":33363,"n":"נטף, אברהם","b":"מרבני תונס","s":"ארזי הלבנון"},{"i":33364,"n":"נטף, חיים","s":"ארזי הלבנון"},{"i":33365,"n":"נטף, יצחק מתונס","k":"בעל ושבועתו ליצחק","dt":"תקפא - תקפה","dp":"תונס","b":"רב ודיין בתונס-תקפ.","s":"אוצר הרבנים 10844; ארזי הלבנון"},{"i":33366,"n":"נטקין, יהודה מדמשק","b":"מחכמי דמשק, בנו - ר יהושע השל מירושלים.","s":"פרומקין-תח\"י"},{"i":33367,"n":"נטקין, יהושע השל מירושלים","f":"יהודה מדמשק","dt":"תרמג - כ אד\"ב","dp":"ירושלים","b":"מחכמי ירושלים. חתנו - ר יהודה דמשקר.","s":"פרומקין-תח\"י"},{"i":33368,"n":"נטקין, ישכר בער זאבל'ס מוילנא","f":"שבתי","k":"בערעלע זאבל'ס","dt":"תרלא - ח כסלו","dp":"וילנא","b":"נכד ר נתן נטע מירושלים. חתן ר שמואל זנויל מוילנא. גביר מחכמי וילנא. נסע בשם קהילת וילנא לקבל את פני מונטיפיורי בוילקומיר. היה כמה פעמים בשליחות הקהל בפטרבורג.","s":"עיר וילנא ח\"א"},{"i":33369,"n":"נטקין, נתן נטע מירושלים","dt":"תרמח - טבת","dp":"ניו יורק","b":"עלה לירושלים מפאריץ-פלך פינסק. מחכמי ירושלים, נכד ה\"שאגת אריה\". חתן ר יוסף זונדל סלנט, ובזיוו\"ש חתן ר ישעיה ברדקי - חתנו של ר ישראל משקלוב. בשליחות עדת האשכנזים באמריקה-תרכו, ובשנת תרלו שליח כל העדות (גם הספרדית) באמריקה - כשלוש שנים, ושוב-[תרמח] ונפטר בשליחותו. על משפחתו ב\"עיר וילנא\" לשט\"ש, וב\"הלבנון\". חתם-תרלה עם גדולי ירושלים כנגד בית עקד ספרים שהקימו משכילי אשכנז בירושלים - ונדפס בכרוז. (בארצות החיים - אמריקה מציין כי יערי בשא\"י טעה בענין שליחותו ושנת פטירתו - וצדק גרייבסקי במה שכתב).","s":"גליס; אוצר הרבנים 16444; אמריקה; פרומקין-תח\"י"},{"i":33370,"n":"נטקין, נתן נטע מראסיין","dt":"תרכז - א ניסן","dp":"קניגסברג","b":"חתן ר דב בר רבינוביץ מראסיין. רב בראסיין.","s":"מרקוביץ-ראסיין"},{"i":33371,"n":"נטקין, נתן נטע משקלוב","f":"חיים","dt":"תקסד - יא אלול","dp":"פטרבורג","b":"אבי משפחת נטקין. גביר שעסק בהספקה לצבא הרוסי בפטרבורג. מיודד עם הנסיך פוטמקין, ונודע למלכה יקטרינה. פעל לטובת היהודים בפטרבורג יחד עם חבריו הגבירים מפטרבורג ר יהודה ליב בן נח מלעטיטשוב ור אברהם פרץ. והיה בעל הזכות על ביה\"ק בפטרבורג. מכתב ממנו ב\"זרע קדש\" ל משה זלאטאווער.","s":"עיר וילנא ח\"א"},{"i":33372,"n":"נטקין, צבי הירש ממוהילוב","b":"ש\"ץ ונאמן בי\"ד מוהילוב, אצל ר מאיר ברלין ור אליעזר ליפמן ריבלין.","s":"מתוך קטלוג"},{"i":33373,"n":"נטקין, שבתי","f":"נתן נטע מירושלים","b":"חתן ר השל סירקין משקלוב. בניו ר ישכר בער מוילנא, ר יעקב אב\"ד רדושקביץ.","s":"עיר וילנא ח\"א"},{"i":33374,"n":"נטר, משה מצרפת ואלגיר","b":"רב בלמדיא-אלגיר, ווהראן - תרנב-תרסה מטעם הקונסיסטואר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33375,"n":"נטר, שלמה זלמן מירושלים","f":"יעקב","k":"בעל פירוש על אבן עזר","bp":"יאגוסטוב","dt":"תרלט - ז טבת","dp":"וינה","b":"תלמיד החת\"ס. עלה לירושלים, בעל בית מסחר לספרים בוינה והיה נוסע הלוך ושוב מא\"י להונגריה. עורך סידור דרך החיים, בית הבחירה למאירי ועוד. בנו ר יעקב מרדכי בעל \"שלוים מן הים\". (סיפר כי בזמן לימודיו אצל החת\"ס - היכה כמה פעמים את הרש\"ס - ע\"פ ציווי אביו - לחינוכו).","s":"אוצר הרבנים 18784; החת\"ס ותלמידיו; פרומקין-תח\"י"},{"i":33376,"n":"נטרוי גאון פומפודיתא","f":"אמונה","b":"גאון פומפודיתא-ד'תקיב.","s":"ארזי הלבנון"},{"i":33377,"n":"נטרונאי גאון סורא","f":"הילאי גאון בן מארי","b":"גאון סורא-ד'תריג, על מקום אביו - בהפסקה של 56 שנה. היה בקשר עם היהדות ברחבי העולם וביחוד עם ספרד. שלח לקהילת אליסאנו-ספרד את סדר הברכות, וזהו היסוד הקדום ביותר לסידור תפלה. חיבר גם פירוש לכמה סוגיות בתלמוד - לבקשת שואלים.","s":"ארזי הלבנון"},{"i":33378,"n":"נטרונאי גאון פומפודיתא","f":"נחמיה","k":"רב ינקא","b":"חתן משפחת ראש הגולה, גאון ישיבת פומפודיתא-ד'תשיט והיה מחלוקת בישיבה וכמה מהחכמים עזבו לטובת ישיבת סורא.","s":"ארזי הלבנון"},{"i":33379,"n":"ניאראטה, יעקב מוינה","b":"דיין בוינה אצל ר אלעזר הורביץ-תרטז","s":"וונדר-גליציה ח\"ב"},{"i":33380,"n":"ניבור, קארפטין","b":"כתב על בני כת ה\"דונמה\" בשלוניקי-תקלד.","s":"זכרון שלוניקי-43"},{"i":33381,"n":"ניבירט, ראובן יוסף מקורטשין","b":"מחכמי קורטשין, תלמיד ר אליעזר דייטש מבוניהאד(=בניהאד) שהשיב לו בתרמח.","s":"וונדר-גליציה ח\"ג"},{"i":33382,"n":"ניברג, דוד מרדוביץ","b":"רב ברדוביץ-תרלז אצל האב\"ד ר צבי הירש שפירא.","s":"וונדר-גליציה ח\"ו"},{"i":33383,"n":"ניברג, חיים מפיעטרקוב","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר.","s":"אוצר כתבי עת-לוין"},{"i":33384,"n":"ניברגר, מאיר יהודה ליבוש","f":"שלום","bt":"תרם","dt":"תש","b":"רב בבורשטשוב-תרסו, עבר לארה\"ב וכיהן שם כרב. נסמך מאת: מהרשד\"ם מברעזן.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 13067"},{"i":33385,"n":"ניגבור, שמחה בונם הלוי מערימלא","b":"רב בערימלא, ברודי.-תרסח.","s":"וונדר-גליציה ח\"ג"},{"i":33386,"n":"ניגר, שמואל זנויל מסוכא","dt":"תרפא","b":"תלמיד ר מאיר ארק. מחכמי סוכא-תרסב - ממשתתפי \"אספת חכמים\". בנו ר יצחק - ראש ישיבת \"עץ חיים\" דבובוב בסוכא. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד.","s":"וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין"},{"i":33387,"n":"נידרברג, מרדכי מאזדיטיטץ","f":"אהרן בער","bt":"תרלה","b":"רב באזדיטיטץ-פלך ווהלין-תרנט. חיבר ספר דרושים - בכת\"י, והניח חדושים בכת\"י.","s":"אוצר הרבנים 13952; אהלי שם"},{"i":33388,"n":"נידרהופהיים, בנימין","f":"הירש","s":"מתוך קטלוג"},{"i":33389,"n":"נידרלנד, יצחק אלחנן מוישטיניץ","dt":"תרמו","b":"רב בוישטיניץ על מקום ר אלחנן צבי לאפ.","s":"ליטא"},{"i":33390,"n":"נידרלנדר, אברהם מפרג","f":"אפרים","b":"חיבר \"ברית אברהם\" על חכמת החשבון, \"מאזני צדק\" פרג שמט.","s":"פין-כנסת ישראל"},{"i":33391,"n":"ניווירט, אהרן מהלברשטט","k":"בעלת טהרת המשפחה","bt":"תרמב","dt":"תשיח","b":"מרביץ תורה במיינץ,הלברשטט,עלה לבני ברק-תש\"ח","s":"אוצר הרבנים 1653"},{"i":33392,"n":"ניזניק, אברהם דוד מויסוקי","b":"רב בויסוקה, מזובצק. מאמר ממנו ב\"תורה אור\" - שנחאי תשו.","s":"אוצר כתבי עת-לוין"},{"i":33393,"n":"ניטא, יעקב מסן פרנציסקו","bt":"1863","bp":"לונדון","b":"תלמיד הקולג' היהודי בלונדון, ניו יורק. רב ריפורמי בקהילת \",שארית ישראל\" בסן פרנציסקו-תרסא. חיבר ספר באנגלית.","s":"דור וחכמיו-א\"ש-ו"},{"i":33394,"n":"ניטו, יצחק","f":"דוד ניטו","b":"רב העדה הספרדית בלונדון-ת\"צ","s":"אוצר הרבנים 10843"},{"i":33395,"n":"נייבורג, יצחק ממנהיים","b":"החתן שנתן את הגט מקליווא-תקכו לבתו של יעקב גונצהויזר מבון - שעורר מחלוקת גדולה בין הרבנים.","s":"רבני פרנקפורט"},{"i":33396,"n":"נייגו, יוסף מאדרינופול","f":"עזרא","bt":"תרכג","bp":"אדרינופול","b":"תלמיד דודו ר רפאל במוהר\"ש-רבה של אדרינופול, למד בקושטא אצל ר מנחם פרחי בעל \"רב פעלים\", למד חקלאות בפאריס. מנהל ביה\"ס החקלאי \"מקוה ישראל\", מפקח היק\"א בארצות המזרח - אחראי על הפעילות בקפריסין, אחוזת סלובודקא, ליסנא-גליציה, משתלות סורוקי בבסרביה, יעקב קיבקינד בים השחור, בארם נהריים על שפת הפרת והחידקל, ועוד. לכבודו נדפס בקושטא תרצג - קובץ ספרותי בצרפתית.","s":"גאון-יהודי המזרח"},{"i":33397,"n":"ניידע, אברהם מלאשיץ","f":"אהרן משה ניידע","b":"רב בלאשיץ-ת\"ר","s":"אוצר הרבנים 633"},{"i":33398,"n":"ניידע, אהרן משה מלאשיץ","b":"רב בלאשיץ","s":"אוצר הרבנים 1850"},{"i":33399,"n":"נייהויז, אברהם מטאפולצא","b":"רב בטאפולצא-ת\"ר","s":"אוצר הרבנים 634"},{"i":33400,"n":"נייהויז, אריה ליב מחעלם טומשוב","f":"יוסף קעזיס מחלם","k":"אדמור מחלם וטומשוב","bt":"תקסה","dt":"תרך - כג תשרי","b":"חתן ר מאיר מאפטא בעל \"אור לשמים\". רב ואדמור בחעלמא, טומשוב-תריא. נסע כאדמור לשר שלום מבלז, ור ישראל מרוזין. היה עשיר גדול. חתנו - ר יעקב יצחק שפירא מבלנדוב.","s":"אוצר הרבנים 3361; אלפסי; ברוורמן-אנשי שם"},{"i":33401,"n":"נייהויז, אריה ליביש מטומשוב","f":"נחמן מטומשוב","k":"אדמור מטומשוב","dt":"תש..","dp":"רוסיה","b":"אדמור בטומשוב על מקום אביו. ברח בראשית השואה לרוסיה ונפטר שם.","s":"אלפסי"},{"i":33402,"n":"נייהויז, יהודה אריה מארה\"ב","f":"יצחק הלוי","bt":"תרם","bp":"רודנבורג-פלך העסען","b":"מצאצאי ה\"נחל אשכול\". תלמיד ביהמ\"ד לרבנים בברלין, נסמך מאת: ר\"ד הופמן, ר יוסף ואהלגמוט, ר עזריאל הילדסהימר. חתן ר שלמה קרליבך מליבק. רב באוסטרווא, מנהל ביה\"ס בלייפציג, רב בפפד\"מ, נאסר במחנה הרכוז טרזנשטט ושוחרר, היגר לארה\"ב-תרצו, וכיהן כרב קהלת \"גמילות חסדים בדטרויט. פרסם מאמרים בעתוני גרמניה, פעיל באגודת ישראל, יסד בית יתומים בקאליש.","s":"אוצר הרבנים 7140; אנשי שם-אמריקה"},{"i":33403,"n":"נייהויז, יהודה זונדל מסמבור לב","f":"פנחס בן יוסף מחלם","k":"אדמור מסמבור בלמברג","bt":"תרל","dt":"תשב","b":"אחיין ונכד לאדמורי חלם. לאחר שנתייתם גדל אצל אביו חורגו ר אורי מסמבור שמינהו לאדמור בלמברג.","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":33404,"n":"נייהויז, יואל צבי מקאטה","dt":"תרעב - ו אלול","b":"תלמיד השב\"ס. מחכמי קאטה וממיסד תלמוד תורה שם, החזיק בבני עניים ודאג לשלחם ללמוד בישיבות. חתנו - ר יוסף צבי דושינסקי מחוסט - ירושלים.","s":"החת\"ס ותלמידיו"},{"i":33405,"n":"נייהויז, יוסף מחעלם","f":"אריה ליב מחלם וטומשו","k":"אדמור מחלם","b":"אדמור בחלם על מקום אביו.","s":"אלפסי"},{"i":33406,"n":"נייהויז, ישראל מבוברקא","f":"פנחס בן יוסף מחלם","k":"אדמור מבוברקא למברג","b":"נכד האדמור מחלם. לאחר שנתייתם גדל אצל אביו חורגו ר אורי מסמבור. אדמור בבוברקא, למברג.","s":"אלפסי"},{"i":33407,"n":"נייהויז, ישראל שמואל מחעלם","f":"מאיר יחיאל מטומשוב","dt":"תשג","b":"חתן ר מרדכי מלויעב (שושלת טשרנוביל). עמד להיבחר כרב בחלם על מקום אביו - אך אז פלשו הנאצים ולא נסתייע. נספה בשואה.","s":"אוצר הרבנים 11999; אלפסי; אהלי שם"},{"i":33408,"n":"נייהויז, ישראל שמואל מטומשוב","f":"יוסף מיאנוב וחלם","k":"אדמור מטומשוב","dt":"תרכט - יג אב","b":"חתן ר יעקב הירש ויעליטשקער. רב בסעלישץ, רב ואדמור בטומשוב-תרל על מקום אביו, עבר לחלם. מתורתו ב\"בנין מנחם\" - לובלין תרצג.","s":"אוצר הרבנים 12306; אלפסי"},{"i":33409,"n":"נייהויז, מאיר יחיאל מטומשוב","f":"ישראל שמואל נייהוז","bt":"תרי","dt":"תרצה","b":"מצאצאי הב\"ח, ר חיים רפפורט. רב בסעלישץ-תרל, טומשוב, חלם(=חעלמא)-פלך לובלין. בנו - ר ישראל שמואל. נסמך מאת: ר שניאור זלמן מלובלין וירושלים.","s":"אוצר הרבנים 13082; אלפסי; אהלי שם"},{"i":33410,"n":"נייהויז, נחמן מטומשוב","f":"ישראל שמואל מטומשוב","k":"אדמור מטומשוב","dt":"תרפז - יב אלול","b":"חתן ר חיים דב ליפשיץ מיאנוב. רב בגאשקוב, טומשוב וכיהן גם כאדמור.","s":"אלפסי"},{"i":33411,"n":"נייהויז, שלמה זלמן מפרשבורג","b":"ממנהלי ישיבת פרשבורג-תרץ.","s":"פרשבורג-וינגרטן"},{"i":33412,"n":"נייהויזן, חיים שמעון מארה\"ב","f":"משה יהושע","k":"בעל שני לוחות","bt":"תרלב","bp":"דוינסק(=דינבורג)","b":"ממשפחת האדמור מקאפוסט (חב\"ד). תלמיד ישיבת ר יצחק ירוחם בפלאצק, ישיבת הרב לנדא בויטבסק - והיה נתמך בידי הגביר ר וולף כהן, ישיבת וולוזין (זמן קצר). חתן ר יעקב בן ישכר בר נאטקין מוילנא. פעיל בתנועה הציונית ויסד אגודות ציוניות בפלך ויטבסק. רב בבולטימור-ארה\"ב-תרפג, ניו יורק-תרפט. פרסם מאמרים בכתבי עת רבים ובהם ב\"אהל מועד\" - פודגורזע תרנח. חיבר \"הקריאה\", \"תורת הלשון\", \"נרדפי זהר\", ועוד.","s":"אמריקה; דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין"},{"i":33413,"n":"נייהוף, אברהם מקשאנוב","dt":"תשב","b":"רב בקשאנוב - אצל הרבי משינאווא, קלווריה-גליציה-תרפו. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":33414,"n":"נייהוף, דב בער","f":"דוד","b":"חתנו - ר שמאי שהיה זקנו של ר אברהם אבא אייזנר.","s":"%"},{"i":33415,"n":"נייהוף, דוד","b":"בנו - ר דב בער.","s":"%"},{"i":33416,"n":"נייהוף, מאיר מקשנוב","b":"השתדך עם בת ר שלמה יוסף קורץ מקשנוב. ניצל מהשואה ופגש את ארוסתו זלאטא - תלמידת בית יעקב ונישאו-תשו. היגר לארה\"ב-תשי.","s":"וונדר-גליציה ח\"ו"},{"i":33417,"n":"נייוויירט, דוד הכהן","b":"דומ\"צ בעפריעס-תר\"ע","s":"אוצר הרבנים 4927"},{"i":33418,"n":"נייויידל, אליהו","f":"זלמן מוילנא","k":"בעל מורה שפת עבר","bt":"1821","bp":"אז'אראני","dt":"תרמו - אלול","b":"תלמיד ישיבת וולוזין. מורה לשפות בקובנא, הצטרף לחוג משכילי ראסיין יחד עם שניאור זקש, עבר לוארשא. עסק בהוראה. חיבר גם \"אב לבנים\".","s":"ליטא; עיר וילנא ח\"א"},{"i":33419,"n":"נייויידל, בנימין בינוש מטאוריג","f":"משה יהושע ניישטטער","dt":"תרנד","b":"נכד-אבי אמו ר זלמן-תלמיד הגר\"א ואחיו של ר חיים מוולוזין. חתן ר ליב שרה'ס רוסטובסקי מפלונגיאן-פלך קובנא. מו\"צ בטאווריג ובנו ר ברוך נתנאל על מקומו אחריו. הו\"ל את ספר אחיו ר שלום - \"דברי שלום ואמת\". (אצל מרקוביץ-עיר ראסיין - שם אביו ר שלום טוביה משונציאן. בנו - ר שלום טוביה מזאגר חדש.","s":"אוצר הרבנים 3785; אהלי שם; מרקוביץ-ראסיין"},{"i":33420,"n":"נייויידל, ברוך נתנאל מטאווריג","f":"בנימין בינוש מטאוורי","bt":"תרז","b":"תלמיד ר יצחק איזיק אברך, תלמיד קרובו ר יחיאל הלר. חתן ר אברהם חריף מפיקעלין. מו\"צ בטאווריג-תרנד על מקום אביו. מחובבי ציון וחתם על קו\"ק ציוני-תרנח. נסמך מאת: ר יוסף זכריה משאוועל, ר מנדל מטיירוגן, ר צבי הירש רבינוביץ מקובנא. בנו - ר יהודה ליב מעיר חדש סוגינד. חתניו: ר חיים פישל אפשטין מסייני-פלך סובאלק, ר נחמיה יעקב רובינסון מקובנא.","s":"אוצר הרבנים 4230; ליטא; אהלי שם"},{"i":33421,"n":"נייויידל, יהודה ליב מניישטט","f":"ברוך נתנאל מטאווריג","b":"רב בעיר חדש-סוגינד-פלך קובנא על מקום זקניו.","s":"אהלי שם"},{"i":33422,"n":"נייויידל, שלום טוביה מזאגר","f":"בנימין ביינוש","bp":"ראסיין","b":"מחכמי זאגר חדש. פרסם מאמרים ב\"יגדיל תורה\" אודסה תרם.","s":"מרקוביץ-ראסיין"},{"i":33423,"n":"נייזאץ, אליעזר ליפמן ממאגנדו","f":"מאכל","k":"בעל בציר אליעזר","bt":"תקנז","bp":"נייזאנץ","dt":"תריט - ד תשרי","dp":"סערדאוהל","b":"תלמיד החת\"ס. חתן ר עזריאל אנגל מסערדאוהל ועבר לשם. רב בזשאמבאק-תקץ, סערדאוהל, מאגנדורף-תקצד. חיבר \"בציר אליעזר\", \"באר אליעזר\" ועוד. החת\"ס המליץ עליו לרבנות וועטש ומאגנדורף.","s":"אוצר הרבנים 2697; החת\"ס ותלמידיו; חכמי הונגריה פ\"ה עמוד 322; ראה ערך באר אליעזר","bk":[["באר אליעזר",""],["בציר אליעזר",""],["מי מנוחות",""],["משבצת הפנינים",""]]},{"i":33424,"n":"נייזאץ, ישעיה מהעלישטאבא","f":"אליעזר ליפמן ממגנדרו","k":"בעל תוספות שבועות","bt":"תרב או תרכב","dt":"תרעו - כה אדר","b":"תלמיד הכת\"ס, ור משה הרצפלד מסערדאוהל. חתן ר משה אריה ליב ליטש-רוזנבוים מפרשבורג ועבר לשם-תרכד. רב בהעלישטאבא-תרלו. הו\"ל ספרי אביו \"בציר אליעזר\", \"משבצות פנינים\", ועוד - עם חדושים ממנו.","s":"אוצר הרבנים 11736; החת\"ס ותלמידיו; אהלי שם"},{"i":33425,"n":"נייטרא-פרידמן, שמעון","f":"שלום פרידמן","dt":"תרנא - כד כסלו","b":"רב ביאללע,גלנטא","s":"אוצר הרבנים 19914"},{"i":33426,"n":"ניימינץ, יוסף מפילץ קראקא","f":"משה","k":"בעל מעשה חשב","bt":"תק","bp":"פולין","dt":"תקם-ס - יג אייר","dp":"קראקא","b":"נכד התורת חיים. חתן ר מאיר סופר מפילץ, רב בפילץ, קראקא-תקלט. חתם בתקמו נגד החסידים. בנו ר משה אליהו על מקומו אחריו. חיבר \"מעשה חשב\" למברג.","s":"אוצר הרבנים 8460; וונדר-גליציה ח\"ג; צונץ-קראקא"},{"i":33427,"n":"ניימינץ, משה אליהו חריף מקראקא","f":"יוסף מקראקא","k":"בעל הלכה למשה","bt":"תקל","dt":"תקצח - יב שבט","b":"רב בקראקא על מקום אביו. חיבר \"הלכה למשה\" פרמישלא תרלד, ועוד.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 15286; אוצר הרבנים 14949","bk":[["הלכה למשה [על ב\"ק ב\"מ כתובות וריבית]",""]]},{"i":33428,"n":"ניימן, אברהם שמואל בנימין","dt":"תש..","b":"תלמיד השב\"ס. חתן ר פנחס פנט מדברעצין. מחכמי קלויזנבורג. נספה בשואה.","s":"החת\"ס ותלמידיו"},{"i":33429,"n":"ניימן, אהרן צבי מוארדיש","b":"חתן ר מרדכי בנט. רב בוורדיש,עלה לירושלים","s":"אוצר הרבנים 1871; גרינוולד-סלובקיה והונגריה"},{"i":33430,"n":"ניימן, אליהו סגל הלוי מזידטשוב","b":"רב בזידיטשוב-תרנט.","s":"וונדר-גליציה ח\"ג"},{"i":33431,"n":"ניימן, אלתר יחיאל מדמביץ","f":"מרדכי מנחם","bp":"בנדין","b":"ר\"מ בדמביץ, רב בעלקוש.","s":"וונדר-גליציה ח\"ו"},{"i":33432,"n":"ניימן, אפרים פישל מארה\"ב","f":"מרדכי ראש","k":"בעל שם ויפת","bt":"תרמב","bp":"מאקובה-פלך לומזה","b":"נסמך מאת: ר יוסף לוונשטין מסעראוצק, ר צבי יחזקאל מיכלזון מפלונסק. עוזר לאביו ברבנות מאקובה. היגר לארה\"ב-תרף וכיהן כרב בניו יורק-תר\"פ, חיבר גם \"בית אפרים\". הו\"ל \"בית יעקב\" לדודו - ר יעקב מאיר מיאלובקה, \"שיורי קומץ המנחה\" לדודו - ר א\"ל צינץ, ועוד. חבר אגודת הרבנים באמריקה.","s":"אוצר הרבנים 3571; אמריקה; אנשי שם-אמריקה"},{"i":33433,"n":"ניימן, אשר אנשל מוואץ(=וייצען)","f":"שמואל","k":"בעל כרם בן שמן","r":"אב\"ד ויצטען","bt":"תקס","dt":"תרמב - כ אייר","dp":"ירושלים","b":"רב בקהילת סטטוס-קוו בוייצען, עלה לארץ-תרכב, שליח בהונגריה ונזכר בשו\"ת ר יהודה אסאד. הדפיס קונטרס \"כרם בן שמן\" (נדפס ללא שער). מחתניו - ר יוסף חיים מפרג.","s":"גליס; אוצר הרבנים 3133; הונגריה; מליצי אש, פרומקין-תח\"י; גרינולד סיני קעה-קעו; הגאון שנשכח, מוריה קובץ סו עמוד נב","bk":[["שמן לאשר – כתובות וגיטין",""]]},{"i":33434,"n":"ניימן, ב' הרופא מירושלים","bp":"רוסיה","b":"למד רפואה בוינה, עלה לירושלים-תרז, רופא ומנהל ביה\"ח רוטשילד, עזב את הארץ-תרכו בגלל מחלתו.","s":"פרומקין-תח\"י"},{"i":33435,"n":"ניימן, ברוך נחמן","b":"פרסם מאמרים ב\"המאור\" - ברלין תרצג.","s":"אוצר כתבי עת-לוין"},{"i":33436,"n":"ניימן, דוד מציגנד","dt":"תשד","b":"רב בציגנד-הונגריה-תרפט.","s":"אוצר הרבנים 4928"},{"i":33437,"n":"ניימן, חיים יוסף מנריוב","f":"זאב וולף מנריוב","bt":"תרה","dt":"תרצה","b":"רב בנריוב, מתנגד לחסידות בעיר חסידית - גם 6 מתוך 7 ילדיו היו חסידים.","s":"וונדר-גליציה ח\"ג"},{"i":33438,"n":"ניימן, חיים יוסף מרדיויל","k":"בעל מנוחה שלמה","b":"רב ברדיויל. ממשפחת הב\"ח (ומשם מקור לשם המשפחה). חיבר \"מנוחה שלמה\" ברודי תרכט, ועוד.","s":"וונדר-גליציה ח\"ג"},{"i":33439,"n":"ניימן, יחיאל איכל הכהן מאלטשטט","dt":"תרסד - בערך","b":"רב באלטשטט-תרסד.","s":"וונדר-גליציה ח\"ג"},{"i":33440,"n":"ניימן, יעקב אריה","r":"ראש הישיבה אור ישראל, ומלפנים ראש הישיבה בלידא - פלך וילנא","bp":"אוסטרולנקה, ישיבת לומז'ה","dt":"ה'תשמג","dp":"פתח תקוה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר כתבי עת-לוין; המבשר תורני גליון 243 עמוד כד; יומא דהילולא","bk":[["דרכי מוסר",""],["פרי יעקב",""],["דרכי מוסר - שיחות על התורה",""]],"e":"?-תשמ\"ג","rb":"ישיבת אור ישראל [לידא, פתח תקוה]"},{"i":33441,"n":"ניימן, יעקב הרש משטמפן","b":"מחכמי שטמפן, חתם-תרי בפנקס הקהל.","s":"שטמפן - הרצוג"},{"i":33442,"n":"ניימן, יעקב יצחק ממונטריאול","f":"יוסף מאויבן","bt":"תרעט","dt":"תשסז","b":"תלמיד בעל \"ויגד יעקב\", מונה ע\"י רבו לראש ישיבת פאפא-תרצז, ניצל מהשואה, ואחריה חתן בזיוו\"ש של רבו בעל \"ויגד יעקב\". רב קהל מחזיקי הדת במונטריאול, גיסו של האדמור מפאפא - ר יוסף גרינוולד.","s":"החת\"ס ותלמידיו"},{"i":33443,"n":"ניימן, יעקב מזאדינע","dt":"תשד","b":"רב בזאדניע","s":"אוצר הרבנים 9776"},{"i":33444,"n":"ניימן, יעקב מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר כתבי עת-לוין"},{"i":33445,"n":"ניימן, יעקב צבי הירש מירושלים","f":"נחום דב או שלום","bt":"תקסב","bp":"פאפא","dt":"תרמט","dp":"ירושלים","b":"תלמיד ר אליקים גץ הכהן שווערין מבאיא, ר משה מינץ מאויבן ישן, ובעל שב\"ס ונסמך ממנו, חתן ר משה מרדכי באנט. רב בעיר וראדיש(=וארדישט). בשנת תרכג עלה לירושלים והיה מחכמיה.","s":"גליס; אוצר הרבנים 10285; שטמפן - הרצוג; גרינולד \"סיני\" קנב-קנו"},{"i":33446,"n":"ניימן, יצחק","f":"מרדכי מבובוב","b":"תלמיד ר בן ציון הלברשטט שכתב אליו-תרעז.","s":"וונדר-גליציה ח\"ג"},{"i":33447,"n":"ניימן, ירמיהו מפרשבורג","b":"הגיע ממורביה לפרשבורג. חתן מר קנפלמאכר. עורך \"וועסטניק\" מטעם המרכז היהודי - פרשבורג תשא. עלה לארץ.","s":"פרשבורג-וינגרטן"},{"i":33448,"n":"ניימן, ישראל יהודה מקראקא","f":"יוסף","k":"בעל מחנה ישראל","bt":"תקסח","dt":"תרמח - י שבט","b":"מכונה בשם - באנהייט. רב בקראקא-תקצח - כחמישים שנה. חיבר \"מחנה ישראל\" קראקא תרמד, ועוד. נספד מאת ר שלמה רוזנצוויג ב\"אבל כבד לישראל\" - קראקא תרמח.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 12205,12001; שם הגדולים השלישי"},{"i":33449,"n":"ניימן, מנלי מעיר חדש","b":"דיין בעיר חדש-תרם.","s":"גרינוולד-סלובקיה והונגריה"},{"i":33450,"n":"ניימן, מרדכי מבובוב","f":"אליהו מרברט","dt":"תש..","b":"רב בבובוב. חתן ר אליעזר צינוירט. נספה בשואה.","s":"וונדר-גליציה ח\"ו"},{"i":33451,"n":"ניימן, משה מזשאמבוקרט","f":"דוד מפרשבורג","k":"בעל הלכה למשה","bt":"תרטז","bp":"פרשבורג","dt":"תרצג - יג סיון","dp":"פרשבורג","b":"תלמיד הכת\"ס, השב\"ס. חתן ר גרשון אונגר מזשאמבקרעט, ובזיוו\"ש חתן ר שלום אדלר. רב בזשאמבאקרעט-תרמ.","s":"אוצר הרבנים 14950; החת\"ס ותלמידיו; חכמי הונגריה עמוד 461","bk":[["הלכה למשה",""]]},{"i":33452,"n":"ניימן, משה צבי הירש מבייטש","b":"מחכמי בייטש שלא התפרנס מרבנות אבל נהג אדמורות. [נספה בשואה].","s":"וונדר-גליציה ח\"ג"},{"i":33453,"n":"ניימן, פיליפ מפרשבורג","b":"מראשי קהלת פרשבורג-תרצב.","s":"פרשבורג-וינגרטן"},{"i":33454,"n":"ניימן, שלמה הכהן מדובצק","bp":"פשמישל","b":"רב בדובצק.","s":"וונדר-גליציה ח\"ו"},{"i":33455,"n":"ניימן, שלמה מוינקוועצי","f":"דוד מפרשבורג","bt":"תרי","bp":"פרשבורג","dt":"תרסז - יח אלול","b":"תלמיד השב\"ס, ור אהרן זינגר ממטרסדורף ור בנימין זאב פוקס מסערעד. חתן ר פנחס שטיין מטירעק-סנט מיקלוש, ועבר לשם ולברעצין. רב בפאראבאט-תרלח, וינקוועצי-תרמב.","s":"החת\"ס ותלמידיו; אוצר הרבנים 18537"},{"i":33456,"n":"ניימן, שמואל גדליה מירושלים","k":"בעל גדולי שמואל","r":"ר\"מ בעץ חיים","bt":"ה'תרמח","dt":"תשיט - כב תשרי","b":"ר\"מ בירושלים. עורך \"ועד חכמים\" - ירושלים תרפג.","s":"אוצר הרבנים 19487; אוצר כתבי עת-לוין; שער ספר גן שמואל; שער הספר; יומא דהילולא","bk":[["גידולי שמואל - ביצה, נדרים, כתובות, גיטין, קידושין, ב\"ק, ב\"מ, ב\"ב",""],["גן שמואל - ספר זכרון",""],["גידולי שמואל",""],["גידולי שמואל","מפרשי ש\"ס - אחרונים"]],"e":"תרמ\"ח-תשי\"ט"},{"i":33457,"n":"ניימן, שמואל מפרשבורג","f":"דוד מפרשבורג","bt":"תרטז","bp":"פרשבורג","dt":"תרלג - ח אייר","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור שרגא פייש פישמן מפרשבורג. נפטר בבחרותו.","s":"החת\"ס ותלמידיו"},{"i":33458,"n":"ניימן, שמעון בצלאל מטרנוב","f":"מאיר צבי","k":"בעל ילקוט הרועים","r":"מטארנא","bt":"תרך","dt":"תשב","b":"גדל אצל זקנו ר ישראל רבה של קראקא. מחכמי טרנוב, קראקא. נספה בשואה. חיבר \"ילקוט הרועים\" פרזמישל תרנא, ועוד. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי תורה\" - קראקא תרפה.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 19893; אוצר כתבי עת-לוין; היברובוקס","bk":[["אבל משה",""],["ילקוט הרועים",""],["משיב נפש",""],["משיב נפש [ב\"ח]",""],["פנינים יקרים",""],["פנינים יקרים החדש",""]]},{"i":33459,"n":"ניימן, שרגא משלם","b":"תלמיד ישיבת וערפעלט. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח.","s":"אוצר כתבי עת-לוין"},{"i":33460,"n":"ניימן-לקנבך, דוד מפרשבורג","f":"יהודה","k":"בעל ניר לדוד","bt":"תקפ","bp":"לקנבך","dt":"תרסח - ד שבט","dp":"פרשבורג","b":"נכד ר משה קוניץ מלקנבך. תלמיד החת\"ס, ור צבי הירש מאגליד-מורגנשטרן מסנטגרוד, ור אברהם אולמן מלקנבך. חתן ר שלמה ורטהימר מפעזינג. דיין ור\"מ בפרשבורג-תרלז.","s":"החת\"ס ותלמידיו; אוצר הרבנים 4930; פרשבורג-וינגרטן"},{"i":33461,"n":"ניימעגען, בנדיט מפרשבורג","f":"אליהו","dt":"תקפה - כה סיון","dp":"פרשבורג?","b":"נכד(-אבי אמו) ר ליב ורטהיימר, מצאצאי השר ר שמשון ורטהיימר. גביר ומוהל מחכמי פרשבורג, ערך בריתות רבות יחד עם החת\"ס. חתם על כתב מנוי רבנות לחת\"ס-תקסז. נזכר בחדושי החת\"ס. מחותן עם ר וולף טעבן.","s":"אבני בית היוצר-וייס"},{"i":33462,"n":"ניימרק כץ, משה","k":"חותן המהרי\"ל","b":"רב בווינה,בערוונה-ק\"מ","s":"אוצר הרבנים 14951"},{"i":33463,"n":"ניימרק, אברהם אליהו ממיכילובקא","f":"יוסף יוזפא","bt":"תרכד","b":"תלמיד ר דובער ליפשיץ בישיבת ויעטקע. מו\"צ במיכילובקה(=מיכיילאווקע)-פלך טבריא. נסמך מאת ר שלום דב מרעציצע, ר מרדכי דב מהורנסטיפל, ר אליעזר ארלודזוב מראמען ואחיו ר יחזקאל ארלודזוב מחרקוב, ר דוד זאב מיקטרינסלב, ר בנימין זקהיים מיקטרינסלב, ר ליב שפירא מסוראז, ר שלמה הכהן ארונסון מקיוב, ר ליב צירלסון מקישינב, ר חיים שניאורסון מראמען ואחיו ר זלמן שניאורסון מהאמליע. מחותן עם ר ישראל מן רבינוביץ מקאזעלעץ.","s":"אוצר הרבנים 952; אהלי שם"},{"i":33464,"n":"ניימרק, אברהם יעקב מתל אביב","f":"יהושע אליהו","k":"בעל אשל אברהם","bt":"תרלט","bp":"שומיאץ-פלך מוהילוב","dt":"תשכב - ט חשון","dp":"תל אביב","b":"תלמיד ישיבת טלז. נסמך מאת: ר אליעזר גורדון, ר צבי יעקב אופנהיים מקעלם. רב בפראן(=פרען)-פלך סובאלק-תרסט, חבר הועד הלאומי בליטא. עלה לארץ-תרפד וכיהן כרב בתל-אביב. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - ירושלים תשא, \"תורת ארץ ישראל\" - ירושלים תרץ.","s":"אוצר הרבנים 1196; ליטא; אוצר כתבי עת-לוין; אהלי שם"},{"i":33465,"n":"ניימרק, אברהם מארה\"ב","bp":"פיעטרקוב","dt":"תרעג - סיון","dp":"ניו יורק","b":"תלמיד ביהמ\"ד לרבנים בברלין, ברסלוי. רב בליק-פרוסיה, היגר לארה\"ב-תרמב וכיהן כרב ביהמ\"ד \"אורח חיים\" בניו יורק. פרסם מאמרים ב\"המגיד\", \"המליץ\".","s":"אנשי השם בארהב-איזנשטט"},{"i":33466,"n":"ניימרק, דוד מבריסק","b":"גביר מחכמי בריסק. גיסו-אחי אשתו של הגדול ממינסק. חתנו - ר אברהם טרוכונובסקי (אב\"ד סלאוטיץ?).","s":"הגדול ממינסק"},{"i":33467,"n":"ניימרק, חיים משלם זלמן","b":"רב-שנת תר\"כ","s":"אוצר הרבנים 6509"},{"i":33468,"n":"ניימרק, יהודה ליב מהאנוי","f":"דוד","k":"בעל שורש יהודה","b":"חיבר \"שורש יהודה\" פרנקפורט. מגיה \"מקראי קדש\" ליבנלונסקי.","s":"איטליה גירונדי-י קפ; פין-כנסת ישראל"},{"i":33469,"n":"ניימרק, יהושע אליהו","f":"משלם זלמן מהארקי","dt":"תרסה","dp":"יקטרינוסלב","b":"נהרג עק\"ה בפרעות, רב ביקטרינסלב.","s":"אוצר הרבנים 7656; אהלי שם"},{"i":33470,"n":"ניימרק, יוסף יחזקאל פיבל מנעוי","f":"חיים משלם זלמן","bt":"תרטו","b":"רב בנעוויל-פלך ויטבסק-תרנג.","s":"אוצר הרבנים 8866; אהלי שם"},{"i":33471,"n":"ניימרק, מיכל","b":"רב בניימרק-תק\"י","s":"אוצר הרבנים 13176"},{"i":33472,"n":"ניימרק, משה דב בר","f":"זלמן מירלס","s":"אוצר הרבנים 15347"},{"i":33473,"n":"ניימרק, משה מאה\"ו","f":"משלם זלמן מירלש מאהו","b":"חתן ר דוד לידא-הנכד. מחכמי אה\"ו, סייע בהדפסת \"יד כל בו\" לר דוד לידא.","s":"דוקס-אוה למושב-א; פין-קריה נאמנה"},{"i":33474,"n":"ניימרק, משלם זלמן","f":"משה דוב ניימרק","b":"רב בהרקי,סטרידוב,ויטבסק,נעבל-תר\"כ","s":"אוצר הרבנים 15743"},{"i":33475,"n":"ניימרק, נחמן מבריסק","b":"מצאצאי ר משלם זלמן ניימרק מירלס מאלטונא. מחכמי בריסק. חתנו - \"הגדול ממינסק\" בזיוו\"ש.","s":"הגדול ממינסק"},{"i":33476,"n":"ניימרק, נפתלי הירש מברלין","f":"משלם זלמן מירלש מאהו","dt":"תפ - ו אייר","b":"רב בברלין, פולדא.","s":"אוצר הרבנים 16229; דוקס-אוה למושב-א"},{"i":33477,"n":"נייפלד, אלימלך ניסן מירושלים","f":"ראובן יהודה מנובידבו","k":"בעל התפתחות הדרוש בי","bt":"תרנט","bp":"נובידבור","dt":"תשיז - ט חשון","b":"תלמיד ישיבות אלטונא, ברלין, אצל ר\"צ וייס, רמ\"מ גוטברוט, ר\"פ פינקלשטין מוארשא, הרב ד\"ר מ' לרנר מאלנטנא, הרב ד\"ר ש' גרינברג, ועוד. רב קהלת \"עדת ישורון סיני\" בוארשא. פעיל בתנועת ישוב הארץ, עלה לארץ. פרסם מאמרים ב\"ירושלים\" - וארשא תרצו.","s":"אוצר הרבנים 2341; אוצר כתבי עת-לוין"},{"i":33478,"n":"נייפלד, דוד דוב מרציונז","bt":"תרלא","dt":"תשג","b":"רב ברציונז-תרס\"ד","s":"אוצר הרבנים 5101"},{"i":33479,"n":"נייפלד, הניך מפיאסעצנא","dt":"תשג","b":"רב בפיאסעצנא","s":"אוצר הרבנים 5336"},{"i":33480,"n":"נייפלד, יהודה מראצוינז","b":"פרסם מאמרים ב\"המאסף\" - ירושלים תרנו.","s":"אוצר כתבי עת-לוין"},{"i":33481,"n":"נייפלד, יהודה משה","b":"תלמיד ישיבת פאקש. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח.","s":"אוצר כתבי עת-לוין"},{"i":33482,"n":"נייפלד, יעקב מדיאנדיאש","f":"שמשון ממישקולץ","dt":"תשד","b":"רב בבודווא-סילאש, דיאנדיאש. חתן ר אשר אנשל יונגריז מדיאנדיאש.","s":"אוצר הרבנים 9777; החת\"ס ותלמידיו; ברוין-אנשי מופת"},{"i":33483,"n":"נייפלד, יעקב מעיר חדש","dt":"תקמו - ו טבת","dp":"עיר חדש(=נאוי-מעסטא)","b":"אב\"ד עיר חדש על מקום ר משה המבורגר.","s":"גרינוולד-סלובקיה והונגריה"},{"i":33484,"n":"נייפלד, מוריס מברמינגהם","bt":"1869","bp":"הונגריה","b":"תלמיד ביהמ\"ד לרבנים בבודפשט. היגר לארה\"ב ולמד בביהמ\"ד לרבנים בסינסינטי. רב ריפורמי בברמינגהם-אלבמה. חיבר ספר באנגלית.","s":"דור וחכמיו-א\"ש-ו"},{"i":33485,"n":"נייפלד, ראובן יהודה מנובידואהר","f":"אברהם הי\"ד","k":"בעל שדה יהודה","bt":"תרכט","dt":"תשג","b":"תלמיד ר יהודה ליב מאקאביד, ר יחזקאל מוענגראווא, ר פתחיה מוארשא, ישיבת ר ישראל יצחק בפאוואנזיק. רב בראציונז(=ראצונז)-פלך פלאצק-תרנד, נאווידוואר(=נובידוואהר)-תכ\"ד. נסמך מאת: ר מאיר יחיאל מאסטרובצא, ר אליהו חיים מייזל, ר ירחמיאל מלוקעווא, ר שמואל זנויל קלפפיש מוארשא, ר יוסף לוינשטין מסעראצק. חיבר גם \"כרם יהודה\", ועוד - בכת\"י. מזכיר אגודת הרבנים בפולין.","s":"אוצר הרבנים 17741; אהלי שם"},{"i":33486,"n":"נייפלד, שמחה חנוך הניך","b":"חריף,רב ביעזרני-תר\"ע","s":"אוצר הרבנים 19772"},{"i":33487,"n":"נייפלד, שמשון (שמעון) ממישקולץ","f":"צבי מסעליש","bt":"תרלז או תרמא","bp":"סעליש","dt":"תשד","b":"תלמיד השב\"ס, ור שרגא צבי טננבוים ממעזא-טשאטה ועוד. חתן ר מנחם מנדל טננבוים מטארנא, עבר לשם וכיהן כר\"מ. רב בדיאשדיער(=דיוש ג'יור)-תרסה, מישקולץ-תרפה. פרסם מאמרים ב\"וילקט יוסף\". נספה בשואה. בנו ר יעקב דיין בדיאנדיאש. וחתנו ר פרץ טוביה שטיין מדיאשדיער.","s":"אוצר הרבנים 19894; החת\"ס ותלמידיו; הונגריה; אהלי שם"},{"i":33488,"n":"ניישא, עקיבא","f":"יעקב","dt":"שנז","dp":"פפד\"מ","b":"חתן ר שמעון גינצבורג מפוזנא, במקורו מניישא, שו\"ב מחכמי פפד\"מ, רב ודרשן-שכד. חיבר שירים ופיוטים. נספד ע\"י גדולי דורו ובהם המהר\"ל מפרג ונזכר ב\"פסק על עגונה\" פרג שנח. בנו ר יהודה - נפטר שפג.","s":"גינצבורג"},{"i":33489,"n":"ניישטט, אדולף מפרשבורג","k":"בעל פרעסבורגער צייטו","b":"ראש הריפורמים בפרשבורג בזמן הכת\"ס. עורך ה\"פרעסבורגער צייטונג\".","s":"פרשבורג-וינגרטן"},{"i":33490,"n":"ניישטט, אליעזר יעקב","f":"אריה הלוי","dt":"תרסט","dp":"ירושלים","b":"היה רב בציטעוויאן, עלה לירושלים","s":"גליס"},{"i":33491,"n":"ניישטט, נחום בן ציון","f":"ישראל","k":"בעל מנחם ציון","bt":"תרכח","b":"רב בחוואניק-פלך מינסק-תרנז. נסמך מאת: ר יצחק אלחנן בקובנא. חיבר ספר שו\"ת בשם \"מנחם ציון\" - בכת\"י.","s":"אוצר הרבנים 15908; אהלי שם"},{"i":33492,"n":"ניישטטל, אשר מואנדסבק","dt":"תקעא - ה אב","dp":"ואנדסבק","b":"מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג על מקום ר איצק וארט, דיין בואנדסבק, וחתם בפנקס הקהלה בהמבורג.","s":"אוצר הרבנים 3507"},{"i":33493,"n":"ניישטטל, יעקב מפרג","b":"חתן הפרנס ר יחיאל ואליך. עבר מפרג להמבורג.","s":"דוקס-אוה למושב-ב"},{"i":33494,"n":"ניישטטר, בנימין בינוש מסוגינדט","f":"שלום מסוגינדט","b":"רב בעיר חדש-סוגינד-תק\"ע. בניו - ר משה יהושע - ר\"מ בישיבת וולוזין, ר ברוך מסוגינדט.","s":"אוצר הרבנים 3652; מרקוביץ-ראסיין"},{"i":33495,"n":"ניישטטר, זבולון יהושע מעיר חדש","b":"רב בעיר חדש(=סוגינדט)-פלך קובנא-תקל, ובנו ר שלום על מקומו אחריו.","s":"אוצר הרבנים 5567; אהלי שם; מרקוביץ-ראסיין"},{"i":33496,"n":"ניישטטר, יעקב","f":"אליהו חריף","dt":"תקצה - יט אייר","b":"מצאצאי בעל הלבוש, החכם צבי, ומצד אמו מצאצאי ר דובער מפלונגיאן. בנו - ר אליהו רגולר, ומצאצאיו גם ר ישראל סלנטר.","s":"אוצר הרבנים 9778; ליפמן-קובנא"},{"i":33497,"n":"ניישטטר, משה יהושע מוולוזין","f":"בינוש בן שלום","b":"חתן ר שלמה זלמן מוולוזין-אחיו של ר חיים מוולוזין. ר\"מ בישיבת וואלוזין-תר. בניו - ר שלום, ר בנימין בינוש נייויידל, ר ברוך קראווער, ר ברוך נתנאל נייווידל (קרעווער) מטאווריג (כנראה חתנו ולא בנו).","s":"אוצר הרבנים 7597; אהלי שם; אנשי שם-אמריקה"},{"i":33498,"n":"ניישטטר, שלום מעיר חדש","f":"משה יהושע (זבולון)","b":"רב בעיר חדש סוגינד-פלך קובנא-תקע על מקום אביו. (בנו גם ר שלום מיאנישוק? - כנראה טעות). בניו - ר ברוך מסוגינדט(=עיר חדש), ר משה יהושע רבינוביץ מוילנא.","s":"אוצר הרבנים 18173; אהלי שם; מרקוביץ-ראסיין"},{"i":33499,"n":"ניישטטר, שלמה זלמן מסלובודקא","b":"תלמיד בכולל סלובודקא. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב.","s":"אוצר כתבי עת-לוין"},{"i":33500,"n":"ניישלס, גבריאל שמואל מפרשבורג","f":"חיים מפרשבורג","dt":"תרעה - ו סיון","dp":"פרשבורג","b":"תלמיד הכת\"ס. חתן ר עמרם גרינוולד מטשארנא. רב בפרשבורג. חתנו - בן גיסו - ר יוסף שמחה קאהן מהמבורג.","s":"החת\"ס ותלמידיו"},{"i":33501,"n":"ניישלס, חיים מפרשבורג","f":"יוסף יעקב מסערדאוהל","dt":"תרן - ב אדר","dp":"אונגוואר","b":"תלמיד הכת\"ס. חתן ר שמחה אבארהאם מפרשבורג. מחכמי פרשבורג-תריא, וינה, אונגוואר.","s":"החת\"ס ותלמידיו"},{"i":33502,"n":"ניישלס, יוסף יעקב מסערדאוהל","bt":"תקנה","bp":"וועטש","dt":"תרכח - טז שבט","dp":"בודפשט","b":"תלמיד החת\"ס. חתן ר פרץ גולדברג מאויבן, ועבר לשם. רב בסערדאהעלי(=סערדאוהל)-תקפא על מקום ר אהרן סודיטץ, ור אליעזר ליפמן שטיין על מקומו אחריו, מו\"ץ וראב\"ד באויבן-תקצא. (החת\"ס בתשובה אליו לא כינהו \"תלמידי\" - וכששאל את רבו מדוע הפסיק לכנותו \"תלמידי\" השיב לו החת\"ס, כי אם יקרא לו - תלמיד, יהיה מתכבד בקלון חברו (מחמת שגדל בתורה כ\"כ).","s":"אוצר הרבנים 9779; החת\"ס ותלמידיו; הונגריה; גרינוולד-סלובקיה והונגריה"},{"i":33503,"n":"ניישלס, משה מסקוירא","f":"יעקב מסערדאוהל","bt":"תרעא","bp":"סערדאוהל","dt":"תשנז - כז אד\"א","dp":"סקווירא - ניו יורק","b":"נכד ר גבריאל שמואל ניישלס מפרשבורג. תלמיד הדעת סופר, ור אשר אנשל מסערדאוהל. חתן ר ירמיה דושינסקי מפרשבורג, ועבר לשם. ניצל מהשואה ואחריה רב בפאקש, סערדאוהל והקים בה ישיבה, עבר לפרג, פריז, הגיע עם תלמידיו לניו יורק-תשח והקים מחדש את ישיבתו. רב שיכון סקווירא במדינת ניו יורק.","s":"החת\"ס ותלמידיו"},{"i":33504,"n":"נילנדר, יצחק מגינץ-רוסקא","dt":"תרנח","b":"דומ\"צ בגינץ-רוסקא","s":"אוצר הרבנים 10845"},{"i":33505,"n":"נימויטין, אריה ליב משואדיץ","b":"רב בשואדיץ-ליטא. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","s":"אוצר כתבי עת-לוין"},{"i":33506,"n":"נימויטין, יהושע מאושאץ","f":"יוסף דוד","bt":"תרכ","dt":"תשב","dp":"לנינגרד","b":"נסמך מאת: ר חזקיה מדיני, ר יוסף רוזין-הרוגצובר. רב באושאץ, דניולוביטש(=דונילאוויץ), ביעשנקאויטש(=בישנקוביץ), ויטבסק. נספה ברעב בלנינגרד בזמן המלחמה.","s":"אוצר הרבנים 7596; אהלי שם"},{"i":33507,"n":"נימני","k":"ראה: נמני","dt":"תרמו","dp":"חיפה","b":"מחכמי טיטואן-מרוקו. עלה לטבריה-תרך, וכיהן כדיין וראש ישיבה, עבר לחיפה וכיהן כאב\"ד. חתם על כתב שליחות ר שלמה טולדנו. הסכים על \"יסוד המערבי\", \"עשיר ורש\" ועוד.","s":"ארזי הלבנון"},{"i":33508,"n":"נימנסקי, פנחס אהרן מירושלים","k":"בעל זכרון דברים","b":"גביר מחכמי אומאן, עלה לירושלים. תרם והחזיק במוסדות בירושלים ובהם ישיבת חיי עולם.","s":"מתוך קטלוג"},{"i":33509,"n":"נין, אליעזר","k":"בעל משנת אליעזר","b":"רב בניקלסבורג","s":"אוצר הרבנים 2559"},{"i":33510,"n":"נינו, חיים","dt":"תרטו - א תשרי","dp":"ירושלים","b":"מגדולי רבני ירושלים","s":"אוצר הרבנים 6085"},{"i":33511,"n":"ניניו, אליהו מטבריה","f":"יעקב שאלתיאל","b":"מחכמי טבריה, מופיע בהקדמת הספר \"חן וכבוד\"","s":"גליס; גאון-יהודי המזרח; יהב\"י"},{"i":33512,"n":"ניניו, חיים מאיר","f":"שאלתיאל","b":"מגדולי חכמי ירושלים-תרי. בנו - ר רחמים שאלתיאל יעקב מירושלים.","s":"אוצר הרבנים 6464; גאון-יהודי המזרח"},{"i":33513,"n":"ניניו, יהודה מטבריה","b":"מקובל, מחכמי טבריה, ירושלים. בנו - ר יעקב שאלתיאל.","s":"אוצר הרבנים 7032; ארזי הלבנון; פרומקין-תח\"י"},{"i":33514,"n":"ניניו, יוסף מניוזיל-היסאר","f":"אברהם","b":"רב ביוזיל-היסאר - ליד אזמיר - שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":33515,"n":"ניניו, יעקב שאלתיאל","f":"יהודה מטבריה","k":"בעל אמת ליעקב","bt":"ה'תקס","bp":"ירושלים","dt":"ה'תרט (בערך)","dp":"צפת","b":"דיין מחכמי טבריה, חתן ר חיים קונוורטי, בשנת תר בשליחות צפת וטבריה ונשדד על ידי דרוזים בין צפת לעכו וניצל בנס ממות. בשנת תרג בשליחות בתורכיה ואיטליה. חיבר \"אמת ליעקב\" ליוורנו תרג, ועוד. בשנת תרה היה בקושטא ועסק בהדפסת ספרי חכמי ארץ ישראל, ומאז לא ידוע עליו דבר. בניו ר אבא ור מאיר שגדלו אצל זקנם ר חיים שמואל הכהן קונוורתי. דרשות ושו\"ת. ר' יעקב שאלתיאל ניניו, מרבני טבריה, תלמידו של ר' חיים פאלאג'י, תשו' משנת תר\"ה.","s":"גליס; רוזניס-תורכיה-ה; טוב ראי עמודים קפז - קצ, חכמיהם של ארבע ערי הקודש חלק א' עמודים 465 - 486; איטליה גירונדי-ש צא; אוצר הרבנים 18902,10328; גאון-יהודי המזרח; שא\"י","bk":[["זרע יעקב",""],["אמת ליעקב [קבלה. קונט' שפת אמת]",""],["אמת ליעקב - כתבי האריז\"ל",""],["זרע יעקב - דרוש ושו\"ת",""]]},{"i":33516,"n":"ניניו, מאיר מטבריה","f":"יעקב שאלתיאל","bt":"תר-תרא","bp":"טבריה","dt":"תרעח","dp":"טבריה","b":"נכד ר חיים שמואל הכהן קונוורטי. מחכמי טבריה- בתחילת המאה ה-20. הו\"ל ספר אביו \"זרע יעקב.","s":"אוצר הרבנים 12909; גאון-יהודי המזרח; ארזי הלבנון"},{"i":33517,"n":"ניניו, רחמים יעקב שאלתיאל-רש\"י","f":"חיים מאיר","k":"בעל חן וכבוד","bp":"ירושלים?","dt":"תרנח","dp":"ירושלים","b":"מחכמי ירושלים ומתלמידי \"בית אל\", בשנת תרמח חתם על כתב שליחות ר בן ציון אלקלעי. חיבר \"חן וכבדו\" ירושלים תרמד, ועוד. פרסם מאמרים ב\"תורה מציון\".","s":"גליס; אוצר הרבנים 17765; גאון-יהודי המזרח"},{"i":33518,"n":"ניניו, שאלתיאל מאזמיר","dt":"תקלה - יח אדר","dp":"אזמיר","b":"קרובו של ר יעקב מטבריה. מחכמי אזמיר.","s":"ארזי הלבנון; גאון-יהודי המזרח; רוזניס-תורכיה-ה"},{"i":33519,"n":"ניניו, שאלתיאל מירושלים","dt":"תקצב-סב - ח טבת","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":33520,"n":"ניניו, שלמה","b":"חתם-תרלו ב\"עיני כל חי\" לר חיים פלאג'י, עם חכמים נוספים.","s":"ארזי הלבנון"},{"i":33521,"n":"נינייאטי, משה שמואל מאנקונה","b":"מחכמי אנקונה. נזכר בחיד\"א.","s":"ארזי הלבנון"},{"i":33522,"n":"ניסברויך, זאב וולף מזלישטשיק","k":"בעל קינה לדוד","b":"אחיינו של ר זאב וולף תאומים. חיבר \"קינה לדוד\" (בתוך מחז\"ה גל' יב) למברג תרנט. ממשתתפי \"ועד חכמים\".","s":"וונדר-גליציה ח\"ג"},{"i":33523,"n":"ניסברויך, יצחק אריה","k":"בעל נוצר חסד","b":"[אחיו של ר זאב וולף]. חיבר \"נוצר חסד\" זלישטשיק תרסז.","s":"וונדר-גליציה ח\"ג"},{"i":33524,"n":"ניסברויך, ניסן מנדבורנה","b":"מחכמי נדבורנה-תרלח, רב בבלוזוב עם ר אלימלך הירש - תשובה אליו מהרי\"א הלוי.","s":"וונדר-גליציה ח\"ג"},{"i":33525,"n":"ניסטמפובר, מאיר זאב","k":"בעל היוצר ויצירתו","b":"חיבר \"היוצר ויצירתו\" פשמישל תרצז.","s":"וונדר-גליציה ח\"ג"},{"i":33526,"n":"ניסל, שבתי מדעש","f":"משה","k":"בעל מבשר טוב-תרעד","b":"תלמיד וחתן ר מנחם מנדל פאנט מדעש, דרשן מחכמי דעש. בזיוו\"ש חתן ר משה כהנא-הלר מקראסנא, ובזיוו\"ש חתן ר מרדכי הירש. בנו ר כתריאל ניסל בעל \"ערלעבניסע אין אונגארן\" פרשבורג תרף.","s":"טרנסילבניה"},{"i":33527,"n":"ניסן הכהן משיניבה","b":"רב בשיניבה-תרלח.","s":"וונדר-גליציה ח\"ג"},{"i":33528,"n":"ניסן כץ מדוואהרט","f":"ישעיה מברוד","b":"תלמיד הבעשט. אודותיו ב\"תורת אהרן\".","s":"אלפסי"},{"i":33529,"n":"ניסן מוילנא","f":"משה","dt":"תקלב - כה ניסן","dp":"וילנא","b":"מחכמי וילנא.","s":"פין-קריה נאמנה"},{"i":33530,"n":"ניסן מזולקוא","b":"מחכמי זולקוא. חתנו - ר שמואל בן יהודה הקדוש.","s":"בובר-זולקוא"},{"i":33531,"n":"ניסן מלכוביץ","dt":"תקלב - כח ניסן","b":"מו\"צ בלכוויץ","s":"אוצר הרבנים 16068"},{"i":33532,"n":"ניסן משיניבה","b":"רב בשיניבה. מל\"ו צדיקים שבדורו. חתנו היה ר אליעזר ירוחם ברון.","s":"וונדר-גליציה ח\"ג"},{"i":33533,"n":"ניסן תרפ\"ד יארצייט הרה\"ק מראדומסק רבי יעקב דוד זצוק\"ל","dt":"כ ניסן"},{"i":33534,"n":"ניסן, זליג","b":"רב בפילווע","s":"אוצר הרבנים 5777"},{"i":33535,"n":"ניסנבוים, יצחק מוארשא","k":"בעל הגות לב","bt":"תרכט","dt":"תשג","b":"תלמיד ישיבת וולוזין. עוזרו של ר שמואל מוהליבר, פעיל בתנועת \"חיבת ציון\", דרשן,רב פעלים בוארשא לישוב א\"י. נשיא המזרחי בפולין. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן. נספה בשואה.","s":"אוצר הרבנים 10847; אוצר כתבי עת-לוין"},{"i":33536,"n":"ניסנבוים, מרדכי אריה מלוטשינץ","k":"בעל מוסדות האמונה","b":"רב בלוטשינץ, ניו יורק-תרף. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז.","s":"אמריקה; אוצר כתבי עת-לוין"},{"i":33537,"n":"ניסנבוים, שלמה ברוך מלובלין","k":"בעל לקורות היהודים ב","b":"חיבר \"לקורות היהודים בלובלין\".","s":"לקורות היהודים בלובלין"},{"i":33538,"n":"ניסנביץ, שימא ממינסק","b":"מיסדת ומנהלת ביה\"ס לחרשים אילמים במינסק-תרן.","s":"מינסק-איזנשטט"},{"i":33539,"n":"ניסנביץ, שמואל מקרסניליק","b":"רב בקרסניליק-תר\"פ","s":"אוצר הרבנים 19288"},{"i":33540,"n":"ניסנוב, יחזקאל מדגסטן","f":"שמעון","bt":"תרמו","bp":"טמיר חאן שורה","dt":"תרעא - טו שבט","dp":"יבניאל","b":"עבר מדגסטן לבקו, הצטרף לתנועה הציונית ועלה לארץ-תרסו, והתישב ב\"זכרון יעקב\" והיה ממיסדי תנועת \"השומר\", עבר למושבה יבניאל, נהרג ע\"י ערבים.","s":"גאון-יהודי המזרח"},{"i":33541,"n":"ניסנוב, צבי","f":"שמעון","b":"מאנשי השומר בגליל.","s":"גאון-יהודי המזרח"},{"i":33542,"n":"ניסנוף, משיח מבוכרה","dt":"תשל","dp":"ירושלים","b":"תלמיד ר יעקב מלמד, והרב מירקאדו שהגיע ממרוקו. רב בבוכרה, עלה לירושלים-תרצב. בנו ר דוד ניסנוף.","s":"ארזי הלבנון"},{"i":33543,"n":"ניפי, חננאל מאיטליה","k":"בעל לוית חן","bp":"פיררה-איטליה","dt":"תקצו - כח טבת","b":"רב בפיררה, צינטו. תלמיד ר יעקב משה עייאש יחד עם חברו ר יעקב ישראל קרמי מריגייו. השתתף באסיפת הרבנים (סנהדרין) בפאריז-תקסו. מתלמידיו ר ישכר ריגייו שהיה רב על מקומו בפיררה. חיבר \"לוית חן\", \"זכר צדיקים לברכה\" - ע\"ד שם הגדולים ונדפס עם ספרו של מרדכי שמואל גירונדי. תשובות ממנו לחכמי דורו. חתנו ובן אחותו - ר אברהם מיכאל קארפנטיטי - על מקומו אחריו בצינטו (ר חננאל מכנה את חתנו - נכדי). נהג לחתום \"לא ליודעים ח\"ן (ראשית תיבות חננאל ניפי).","s":"איטליה גירונדי-ח כד; אוצר הרבנים 6711; ארזי הלבנון; פין-כנסת ישראל"},{"i":33544,"n":"ניצא, אליעזר חיים מרומא","k":"בעל דמשק אליעזר","b":"מגדולי חכמי איטליה,רב ברומא-ש\"ס","s":"אוצר הרבנים 2649"},{"i":33545,"n":"ניצברג, נחום מפרוזין","bp":"פרוזין","b":"גביר ומכניס אורחים. חתן ר נחמן ניימרק ממינסק והיה גיסו של הגדול ממינסק שהיה גם הוא חתן ר נחמן. בניו הגבירים - ר נחמן, ור יצחק שהלכו בדרכיו.","s":"הגדול ממינסק"},{"i":33546,"n":"ניצה, ישעיה מונציה","f":"אליעזר חיים","k":"בעל דרך ישר","b":"רב בונציה-שס. חיבר \"ישע יה\", ו\"דרך ישר\" - ונציה.","s":"איטליה גירונדי-י קיג; אוצר הרבנים 11735; פין-כנסת ישראל"},{"i":33547,"n":"ניצה, שלמה מונציה","f":"ישעיה","b":"רב בונציה. חתם בראש הרבנים. מפסקיו בספרי חכמי דורו - \"לקט הקמח\", \"בראשית בכורי קציר\", \"יד חרוזים\"-תס - ובו מספיד את תלמידו - ר גרשום חפץ, ועוד. רבו של ר מנחם יחיאל כולי. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה.","s":"איטליה גירונדי-ש יט,כט; אוצר כתבי עת-לוין"},{"i":33548,"n":"ניקו, בצלאל","b":"ממקובלי צפת, תלמיד האר\"י","s":"ארזי הלבנון"},{"i":33549,"n":"ניקומודיאו, אהרן מניקומודיא","k":"בעל \"עץ חיים","bt":"ס","dt":"קכט","dp":"קושטא","b":"מחכמי הקראים ומכונה - אהרן האחרון. חיבר גם \"גן עדן\", \"כתר תורה\" - נדפס ע\"י שמחה יצחק מגוזלאוו-תרז.","s":"פין-כנסת ישראל"},{"i":33550,"n":"נירנברג, משה","f":"יצחק איזיק מסטריזוב","b":"חסיד שיניבה. רב בקלן-גרמניה. נספה בשואה.","s":"וונדר-גליציה ח\"ו"},{"i":33551,"n":"נירנברגר, קלמן מבריגל","b":"תלמיד ישיבות הונגריה ואוניברסיטת וינה. תלמיד ביהמ\"ד לרבנים. רב בטריטש, יעמניץ(=ימניץ)-תרסט.","s":"וונדר-גליציה ח\"ו"},{"i":33552,"n":"נירנשטין, מנחם מנדל מירוסלב","f":"[שמואל מברודי]","bt":"תקס","bp":"ירוסלב","dt":"תרלו","dp":"למברג-ברודי","b":"חתן הגביר ר צבי הירש הלברשטם (קומרנר). מחכמי ברודי ומראשי הקהל, עבר ללמברג.","s":"וונדר-גליציה ח\"ג"},{"i":33553,"n":"נירנשטין, משה מסטריזוב","b":"מחכמי סטריזוב-תרמה - ממשתתפי \"אהל מועד\"","s":"וונדר-גליציה ח\"ג"},{"i":33554,"n":"נכט, יוסף מבוצאץ","bt":"תקסא","bp":"למברג","b":"רב בבוצאץ, יאסי, עלה לארץ-תקצח.","s":"וונדר-גליציה ח\"ג"},{"i":33555,"n":"נכט, יעקב מיאסי","f":"שלמה הכהן","k":"בעל סמלי אשה","bt":"תרלג","bp":"יאסי","dt":"תשיט - יב שבט","b":"תלמיד ר חנניה יו\"ט מסיגט, ר\"ז אוירבך מהלברשטט (בנו של \"נחל אשכול\"). רב ודוקטור מאוניב' ברלין. חתן ר צבי המרר מלמברג. רב בפקשן(=פאקשאן)-רומניה-תרסא (עזב בגלל מחלוקת על המילה עם רה\"ק שסירב למול את בנו), בראיילה-תרעט, ראילוב, רדואץ-תרפד. נסמך מאת: ר\"ב וייס מטשרנוביץ, ר יצחק יעקב ריינס. ראש המכון למדעי היהדות בשטרסבורג-תרפט, עלה לתל אביב-תרצד. חיבר ספרים ומאמרים רבים בשפות שונות. מעורכי \"ספר השבת\" תל אביב תרצו. חיבר \"סמלי אשה..\" תל אביב תשיט. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"ישורון\" - ברלין תרף. אחיו של ר משה בעל \"מדרש משה\", ר חיים דוד, ר יצחק.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 9781; אוצר כתבי עת-לוין; היברובוקס","bk":[["ספר השבת",""]]},{"i":33556,"n":"נכט, משה","f":"שלמה מיאסי","k":"בעל מדרש משה","bt":"תריז","b":"חתן ר דוד צבי בלומנפלד מבוטושאן (לאחר שהמנחת חינוך רצה בו לחתנו - אך לא הסתייע). חיבר \"מדרש משה\" ברלין תרפח.","s":"וונדר-גליציה ח\"ג"},{"i":33557,"n":"נכט, שלמה מפודהייץ","f":"אברהם הכהן מפודהייץ","b":"מחכמי יאסי - עסק במסחר. מחסדי רוזין. חתן ר אברהמל (שו\"ב של האוהב ישראל).","s":"וונדר-גליציה ח\"ג"},{"i":33558,"n":"נלקין, אריה ליב מברוד","b":"מחכמי ברודי וקליש - תשובה אליו בשו\"מ-תריג.","s":"וונדר-גליציה ח\"ו"},{"i":33559,"n":"נלקן, אברהם","b":"רב בקאליש-תק\"צ","s":"אוצר הרבנים 636"},{"i":33560,"n":"נמזר, מרדכי מוילנא","bt":"1841","bp":"וילנא","b":"תלמיד ביהמ\"ד לרבנים בוילנא. מורה לעברית ולדת יהודית בגימנסיות במוסקבה. רב מטעם בוילנא.","s":"ליטא"},{"i":33561,"n":"נמיאש, שלמה משלוניקי","dt":"רץ","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי"},{"i":33562,"n":"נמירובר, יעקב יצחק מיאסי","f":"נחום הכהן","k":"בעל זכרון נחום","bt":"תרלב","bp":"למברג","dt":"תש","b":"תלמיד זקנו ר שמואל מרדכי נמירובר ביאסי, ביהמ\"ד לרבנים בברלין, בעל תואר דוקטור מאוניבר' ברן. חתן נכדת ר אפרים זלמן מרגליות. רב ביאסי,-תרנו, בוקרשט. סנטור בסינט בבוקרשט-תרפו. פרסם מאות מאמרים בשפות שונות. חיבר \"זכרון נחום\" באידיש ורומנית, חוברת \"אקדמיה יבנאית חדשה\" אטושאני תרעג. נפטר ללא ילדים. לזכרו ספר זכרון בתוך \"סיני\".","s":"וונדר-גליציה ח\"ג,ח\"ו; אוצר הרבנים 10168; אהלי שם"},{"i":33563,"n":"נמליך, עקיבא מבוליחוב","b":"רב בבוליחוב-תרטז.","s":"וונדר-גליציה ח\"ג"},{"i":33564,"n":"נמני - משפחה","b":"משפחה בצפון אפריקה - הראשון הידוע בשמו נזכר אצל ר יצחק חדאד, שהביא מכת\"י של ר \"אהרן ידיע מנימני\" - כך ש-\"נימני\" הינו שם מקום.","s":"מלכי חי\"ל-מרציאנו"},{"i":33565,"n":"נמני, יוסף מטריפולי - א","bt":"תקס","dt":"תרלז - כב אלול","b":"רב ומקובל בטריפולי.","s":"אוצר הרבנים 8463; מלכי חי\"ל-מרציאנו"},{"i":33566,"n":"נמני, יוסף מטריפולי - ב","bt":"תרף","dt":"תשן","b":"רב בטריפולי-תשיב, אחר יציאת מרבית היהודים בלוב. נזכר בכתב העת \"עאדא\"-22.","s":"מלכי חי\"ל-מרציאנו"},{"i":33567,"n":"נמני, נסים מלוב","dt":"תרלח","b":"גביר, מקובל מחכמי לוב, ועוסק בצרכי צבור וחסד.","s":"מלכי חי\"ל-מרציאנו"},{"i":33568,"n":"נמרוט, יצחק מירושלים","b":"מחכמי ירושלים שעלה מקושטא, כתב לר יוסף מטרני (שחי בשנים שכט - שצט).","s":"גליס; פרומקין-תח\"י"},{"i":33569,"n":"ננדיק, יוסף אריה ליב","f":"סנדר מסוחיוואלי","k":"בעל עדות ביהוסף","dt":"תשג","dp":"קובנא","b":"חתן ר נח וינר מנובוגרד. תלמיד הסבא מקעלם, ר אליעזר גורדון בטלז. משגיח בישיבת ראדין אצל החפץ חיים, הקים יחד עם ר שמעון שקופ והרב כהנמן את ישיבת \"שער התורה\" בגרודנא, ר\"מ בקעלם, ממיסדי ישיבת פוניבז, מנהל רוחני בישיבת קוברין, ו\"בעץ החיים\" בקלצק. נספה בשואה.","s":"אוצר הרבנים 8728,8899; אהלי שם"},{"i":33570,"n":"ננדיק, מיכל","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה.","s":"אוצר כתבי עת-לוין"},{"i":33571,"n":"ננטוא, יהושע מירושלים ומצרים","f":"שמואל דוד","bp":"בלגרד או מנטובה","dp":"ירושלים?","b":"תלמיד ר שמחה הכהן בעל \"ספר השמות\" וכתב את ההקדמה לספר רבו. היה רב באלכסנדריה בשנת תכו, עלה לירושלים ושימש כסופר בית הדין. לדברי רוזניס היה שבתאי.","s":"גליס; פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":33572,"n":"ננטוא, שמואל דוד","b":"מחכמי ירושלים מעדת האשכנזים, בשליחות באיטליה והיה בטריאסט סמוך לשנת ת' בצאתו חזרה נלקח בשבי שודדי ים והוצרך לחזור לאיטליה ללא רכושו.","s":"גליס"},{"i":33573,"n":"נסים","f":"משה בן שלמה","k":"בעל ספר הנסים","b":"נכד ר משה ממרשיליא. חיבר ספר הנסים - כת\"י בפירנצי (אוצרות חיים לר חיים מיכל).","s":"איטליה גירונדי-נ כג"},{"i":33574,"n":"נסים","f":"אבטליון","b":"נזכר ב\"מכתב לחזקיהו\" לר חזקיה מדיני.","s":"ארזי הלבנון"},{"i":33575,"n":"נסים - ר\"ן","k":"בעל דרשות הר\"ן","dt":"כד","b":"מגדולי הראשונים בחכמי ספרד","s":"אוצר הרבנים 16021"},{"i":33576,"n":"נסים אברהם הכהן מירושלים","b":"מחכמי ירושלים. בשליחות בצפון אפריקה-תס. ומתורתו ב\"מראה עינים\" לר אליעזר בהלול ממכנאס. פגש בתונס את ר יצחק לומברזו והשיב לו.","s":"גליס; ארזי הלבנון"},{"i":33577,"n":"נסים אהרן הכהן מבגדד","f":"אליהו","dt":"תרמט - כז אב","b":"תלמיד ר עבדאללה סומך. רב בבגדד, וכיהן כדיין על מקום ר יעקב בן יוסף הרופא-תריב, עם ר עובדיה בן אברהם הלוי ור ששון (שמוחה) בן אליהו בן משה הלוי.","s":"ארזי הלבנון"},{"i":33578,"n":"נסים בכר אליעזר","f":"אליעזר","bt":"תרז","bp":"ירושלים","dt":"תרצא - יב טבת","dp":"ניו יורק","b":"משכיל מקורב לאדולף כרמיה, מראשי כי\"ח ופעל להקמת בתי ספר במקומות רבים ובהם בירושלים בסוריה בבולגריה ותורכיה. פעיל ציבור ומראשי העדה הספרדית בירושלים, סייע לבן יהודה בהוצאת \"הצבי\", מקורב לברון רוטשילד והשפיע עליו לרכוש את הכותל המערבי.","s":"גאון-יהודי המזרח"},{"i":33579,"n":"נסים בכר מיכאל","f":"מיכאל","bt":"תרכו","bp":"אדרינופול","dt":"תרעו - כו תמוז","dp":"ירושלים","b":"מורה ופעיל ציבור.","s":"גאון-יהודי המזרח"},{"i":33580,"n":"נסים דוד משלוניקי","dt":"תרנח","dp":"שלוניקי","b":"רופא בשלוניקי. בנו הרופא ז'אק פאשה.","s":"זכרון שלוניקי-121"},{"i":33581,"n":"נסים הכהן","b":"נזכר בספר החזיונות.","s":"ארזי הלבנון"},{"i":33582,"n":"נסים הכהן מארטא","b":"רב בארטא-שנות ה-ש'.","s":"רוזניס-תורכיה-ב,ג"},{"i":33583,"n":"נסים הכהן מג'רבה","f":"מרדכי","k":"בעל מעשה נסים","dt":"תקעד - כ חשון","b":"רב ודיין בג'רבא בקהילת בלחארה כבירא. מתלמידי ר אהרן פרץ. חברו של ר רחמים חורי. אחיו ר רחמים דיין בג'רבא על מקומו אחריו.","s":"ארזי הלבנון"},{"i":33584,"n":"נסים הכהן מג'רבה וישראל","k":"בעל אחימלך הכהן","bt":"תרעב","bp":"ג'רבא","dt":"תשלד - טו תמוז","b":"תלמיד ר דוד דידו הכהן ור רחמים חי חיותה הכהן. דיין בנגרדאן, עלה לארץ וכיהן כרב במושב שרשרת.","s":"ארזי הלבנון"},{"i":33585,"n":"נסים הלוי ממצרים","b":"רב בדאמייאת-מצרים-שלט. בנו - יהודה חסיד.","s":"רוזניס-תורכיה-ג"},{"i":33586,"n":"נסים הלוי משלוניקי","f":"יצחק","dt":"שצג - ח שבט","dp":"שלוניקי","b":"אחיו של ר שלמה הלוי הבחור. פייטן מחכמי שלוניקי. אחיינו של ר אברהם הלוי בעל \"עין משפט\".","s":"זכרון שלוניקי; מלכי רבנן"},{"i":33587,"n":"נסים חורי מעיר תיטאוין מחכמי תוניסיה","dt":"א תמוז תשכ\"ו"},{"i":33588,"n":"נסים חי הלוי","f":"יחזקאל חיים","dt":"תרנה - טו אלול","b":"תלמיד ר עבדאללה סומך, מחכמי בבל וראש השוחטים ואף רבו התיעץ עמו בעניני שחיטה ומזכירו ב\"זבחי צדק\".","s":"ארזי הלבנון"},{"i":33589,"n":"נסים חיים הכהן מירושלים - ב","b":"ראש כולל ספרדי בירושלים, חתם-תרן עם ר יעקב שאל אלישר.","s":"מתוך קטלוג"},{"i":33590,"n":"נסים חיים מירושלים","f":"שמואל ברוך","bt":"תקע","bp":"ירושלים","dt":"תרנז - כח ניסן","dp":"ירושלים","b":"מחכמי ירושלים חבר בישיבת \"חסד לאברהם\", בשנת תרמז חתם על כתב שליחות ר יעקב בכמוהריץ, בשליחות בצפון אפריקה-תריד. מראשי הקהלה הספרדית בירושלים, התמנה לאב\"ד ירושלים. נספד ב\"שובו בנים\" לר יוסף נסים בורלא.","s":"גליס; אוצר הרבנים 6524; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; שא\"י"},{"i":33591,"n":"נסים יעקב הלוי מקושטא","b":"רב בקושטא, ונזכר בספר נכדו שו\"ת הר\"ש כהן.","s":"ארזי הלבנון"},{"i":33592,"n":"נסים יעקב מקושטא","f":"דוד","k":"יעקב בכ\"ר דוד","dt":"תריד - א אלול","b":"רב בקושטא וממונה על איסור והיתר-תקצט, ורב הכולל בזמן החכם באשי ר יעקב אביגדור, וחכם באשי-תרא. חתם על פסקים והסכמות רבות.","s":"ארזי הלבנון"},{"i":33593,"n":"נסים יצחק הלוי מירושלים","dt":"תקי - ב טבת","dp":"ירושלים","b":"גביר מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":33594,"n":"נסים מאדרינופול","f":"ישראל","b":"מראשי קהלת אדרינופול-תרנא, חתם על ביטול רבנות משפחות גירון וכמוהר\"ר באדרינופול, עם ר יוסף דנון, ור נסים בן אהרן.","s":"רוזניס-תורכיה-ה"},{"i":33595,"n":"נסים מאדרינופול","b":"מראשי קהלת אדרינופול-תרנא, חתם על ביטול רבנות משפחות גירון וכמוהר\"ר באדרינופול, עם ר נסים בן ישראל, ור יוסף דנון.","s":"רוזניס-תורכיה-ה"},{"i":33596,"n":"נסים מוינה","f":"יוסף עובדיה","bt":"תרן","bp":"אדריאנופול","dt":"תשב - טז אלול","dp":"ניו יורק","b":"רב קהילת הספרדים בוינה, פריס, ניו יורק.","s":"ארזי הלבנון"},{"i":33597,"n":"נסים ממרשיליא מספרד","b":"תלמיד הרמבן וחברו של הרשב\"א. (יש הרואים בו את מחבר דרשות הר\"ן - אולם זה לא יתכן).","s":"ארזי הלבנון"},{"i":33598,"n":"נסים מספרד","f":"צמח","b":"מחכמי ספרד-קן. אחיו של הרשב\"ץ שהשיב לו בספרו.","s":"ארזי הלבנון"},{"i":33599,"n":"נסים מספרד","f":"רא\"ש-לא הרא\"ש הידוע","k":"בעל ילקוט על מועדים","b":"אביו לא היה הרא\"ש הידוע. מחכמי ספרד-רלד לפני הגירוש וחיבר ילקוט בכת\"י, חיבר ספר המעשים - הישועה - פיררה. הספר נכתב בעילום שמו.","s":"ארזי הלבנון; איטליה גירונדי-נ ט; אוצר הרבנים 16043"},{"i":33600,"n":"נסים מצפת","f":"יהושע","b":"מחכמי צפת, בשנת רסד חתם על מכתב חכמי צפת לחכמי ירושלים, בשנת רסט חתם על תקנת המסים, חתום בפסק עם ר יעקב בירב.","s":"גליס"},{"i":33601,"n":"נסים מצפת","f":"יהושע","b":"מחכמי צפת, דיין בבית דינו של הנגיד. חתם עם חכמי צפת בענין השמיטה-רסד יחד עם ר יעקב בירב.","s":"ארזי הלבנון"},{"i":33602,"n":"נסים מקושטא","f":"משה נתן","b":"רב בקושטא. נזכר ב\"רב דגן\".","s":"ארזי הלבנון"},{"i":33603,"n":"נסים מקירואן","k":"בעל מגילת סתרים","dt":"ד'תתי","b":"ראש חכמי דורו,בדור הראשון אחרי תקופת הגאונים והתחלת תקופת הרבנות,פוסק,פרשן,מרביץ תורה בקירואן","s":"אוצר הרבנים 16021 א'"},{"i":33604,"n":"נסים מקירואן","f":"ברכיה","b":"תלמיד ר יעקב ן שאהין. רב בקירואן בזמן ר נסים גאון.","s":"ארזי הלבנון"},{"i":33605,"n":"נסים מרוקו","f":"נסים","b":"רב קדום במרוקו, ונהגו רבים להשתטח על קברו הנמצא ליד קבר ר אברהם אווריוור בעיר דאד.","s":"ארזי הלבנון"},{"i":33606,"n":"נסים מתימן","f":"סעדיה","k":"בעל מפי חכמים","b":"מחכמי צ'אלע-תימן בסוף המאה ה-יט.","s":"ארזי הלבנון"},{"i":33607,"n":"נסים נתן","b":"נזכר ב\"חיים ושלום\" לר חיים פלאג'י.","s":"ארזי הלבנון"},{"i":33608,"n":"נסים נתן משלוניקי וירושלים","dp":"מצרים","b":"מחכמי שלוניקי, עלה לירושלים-שמ, ועבר למצרים.","s":"אוצר הרבנים 16060; ארזי הלבנון; זכרון שלוניקי-38; פרומקין-תח\"י"},{"i":33609,"n":"נסים עובדיה מחברון","b":"מחכמי חברון, חתם על איגרת שנשלחה לחיד\"א באיטליה-תקלה. בשנת תקמב חתם על אגרת ראשי הקהלה.","s":"גליס; ארזי הלבנון"},{"i":33610,"n":"נסים שלום","k":"בעל שבילי תרומה","s":"אוצר הרבנים 16064; ארזי הלבנון"},{"i":33611,"n":"נסים שלום מירושלים","b":"מחכמי ישיבת \"חסד לאברהם\" בירושלים-תקז בערך.","s":"רוזניס-תורכיה-ה"},{"i":33612,"n":"נסים, אלברט משלוניקי","f":"דוד","b":"רופא בשלוניקי-תרס. אחיו של הרופא ז'אק פאשה נסים משלוניקי.","s":"זכרון שלוניקי-187"},{"i":33613,"n":"נסים, אליאס משלוניקי","f":"דוד","b":"רופא בשלוניקי-תרס. אחיו של הרופא ז'אק פאשה נסים משלוניקי.","s":"זכרון שלוניקי-187"},{"i":33614,"n":"נסים, אליהו מירושלים","f":"שמואל","bt":"תרכד","bp":"ירושלים","dt":"תרצב - יג אב","dp":"ירושלים","b":"מחכמי ישיבת \"פורת יוסף\" בירושלים. חדושי ממנו בענין מילה ב\"שערי רחמים\" לר רחמים יוסף פרנקו.","s":"גאון-יהודי המזרח"},{"i":33615,"n":"נסים, אליהו משלוניקי","k":"בעל סדר אליהו","dt":"תק","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר \"סדר אליהו\" ונדפס ע\"י נכדו ר שמואל. בנו - ר חיים בעל \"מצא חיים\".","s":"זכרון שלוניקי-70"},{"i":33616,"n":"נסים, אליהו משלוניקי וירושלים","f":"יעקב","dt":"תרכט - כג סיון","dp":"ירושלים","b":"מרבני שלוניקי, עלה לארץ, דיין בירושלים. בשליחות קהלת ירושלים וקהלת חברון. חתם-תקצו עם ר מנחם אלשיך על כתב מינוי ר יונה נבון.","s":"אוצר הרבנים 2298; ארזי הלבנון; פרומקין-תח\"י"},{"i":33617,"n":"נסים, אליעזר בכר נסים מקושטא","dt":"תרנז - כד אד\"א","dp":"ירושלים","b":"מחכמי קושטא, עלה לירושלים. בנו ר נסים בכר.","s":"גאון-יהודי המזרח"},{"i":33618,"n":"נסים, בנימין משלוניקי","dt":"שצח - ו שבט","dp":"שלוניקי","b":"מחכמי שלוניקי. כנראה חתנו - הרופא ר אליהו בארבאדו.","s":"זכרון שלוניקי; מלכי רבנן"},{"i":33619,"n":"נסים, דוד חי מאיר יוסף","dt":"תרסו - כז תשרי","b":"מגדולי חכמי בגדאד, עלה לא\"י-י' אייר תרס\"ה, הקים בירושלים ישיבת \"שושנים לדוד\"","s":"ארזי הלבנון"},{"i":33620,"n":"נסים, ז'אק (פאשה) משלוניקי","f":"דוד-רופא בשלוניקי","bt":"תרי","bp":"שלוניקי","dt":"תרסג - ג אלול","dp":"שלוניקי","b":"רופא צבאי בתורכיה, מפקח על הבריאות במחוז שלוניקי מטעם השלטונות. היה נערץ על יהודי שלוניקי, ובהלויתו השתתפו רבבות יהודים. אחיו - אלברט ואליאס - רופאים בשלוניקי.","s":"זכרון שלוניקי-163"},{"i":33621,"n":"נסים, חיים משלוניקי","f":"אליהו משלוניקי-סדר א","k":"בעל מצא חיים","dt":"תקך - ז אלול","dp":"שלוניקי","b":"דיין בשלוניקי. נפטר במגפה-תקך. (לפי אוצר הרבנים - מרבני אזמיר-תק\"נ)","s":"אוצר הרבנים 6518; ארזי הלבנון; זכרון שלוניקי-92"},{"i":33622,"n":"נסים, יעקב חי בכור","f":"שמואל","k":"הו\"ל בן גוריון בלדינ","b":"גבאי כוללות הספרדים בירושלים-תרס. חיבר רשימת ספרי לאדינו ב\"קרית ספר\".","s":"גאון-יהודי המזרח"},{"i":33623,"n":"נסים, משה מירושלים","f":"יעקב חי או בכר נסים","bt":"תרמב","bp":"ירושלים","dt":"תרפז - טז טבת","dp":"ירושלים","b":"משכיל מחכמי ירושלים. מזכירו של אליעזר בן יהודה וסייע לו בחיבור המילון, והשלימו אחר פטירתו של בן יהודה.","s":"גאון-יהודי המזרח"},{"i":33624,"n":"נסים, משה מירושלים","f":"שמואל","bt":"תרלה","bp":"ירושלים","dt":"תרפג - י שבט","dp":"סמרקנד","b":"מחכמי ירושלים, חתן ר יעקב חי בורלא. בשליחות ברוסיה-תרסח ונשאר לכהן כרב בסמרקנד.","s":"גאון-יהודי המזרח"},{"i":33625,"n":"נסים, משה משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה.","s":"זכרון שלוניקי-137"},{"i":33626,"n":"נסים, שמואל מירושלים","bt":"תרא","dt":"תרעו - ל סיון","dp":"ירושלים","b":"רב בירושלים, גבאי צדקה של קהילת הספרדים בירושלים, ממיסדי ביה\"ח \"משגב לדך\". ראב\"ד-תרס וחברי בית דינו היו ר שלום הדאיה, ר אברהם גאגין, ור אברהם ביג'אג'ו. מתורתו ב\"המאסף\", ובספרי חכמי דורו. חיבר ספר דרושים בכת\"י. היה במחלוקת עם רבני ירושלים ובראשם היש\"א ברכה בנוגע להתרת ממזרים במצרים. בניו: ר משה, ר אליהו, ר יעקב חי בכור, ר מרדכי נסים.","s":"ארזי הלבנון; אוצר הרבנים 15597; גאון-יהודי המזרח"},{"i":33627,"n":"נסים, שמואל משלוניקי","f":"חיים","k":"בעל לקוטי שמואל","b":"מחכמי שלוניקי-תקעו. הו\"ל ספרי אביו וזקנו \"מצא חיים\", \"סדר אליהו\" וחיבר הקדמה וחדושים ממנו בשם \"לקוטי שמואל\"-תקעו.","s":"זכרון שלוניקי-116"},{"i":33628,"n":"נסימי, אבדולה","bt":"תרמג","bp":"מרב(פרס)","dt":"תשיט","dp":"טהרן","b":"משהד","s":"ארזי הלבנון"},{"i":33629,"n":"נסל, יצחק אנטאליפט","bt":"תרעא","dt":"תשא - ח אב","b":"רבה האחרון של אנטאליפעט","s":"אוצר הרבנים 10850"},{"i":33630,"n":"נעוויאסקי, אברהם מקובנא","b":"חתן ר מנחם מנדל בן זאב וולף מקובנא.","s":"ליפמן-קובנא"},{"i":33631,"n":"נעוויאסקי, חנוך הניך","dt":"תשג","b":"בועד הרבנים בווילנה","s":"אוצר הרבנים 6650"},{"i":33632,"n":"נעויאזשער, בנימין זאב מקובנא","f":"יחיאל","bt":"תקנב","dt":"תרלח","b":"אחד מהעשרה הראשונים שהגיעו לקובנא מגלות וילאמפול-תקלו, יחד עם ר אבא סולוביציק. יסד מחדש את ביה\"ח בקובנא יחד עם ר אליעזר ליברמן. בנו - העסקן ר צבי הירש נעויאזשער.","s":"ליפמן-קובנא"},{"i":33633,"n":"נעויאזשער, צבי הירש מקובנא","f":"בנימין זאב","b":"גביר, נאמן קהלת קובנא על מקום אביו. הזמין את ר ישראל סלנטר לקובנא להפיץ את תורת המוסר כנגד אברהם מאפו וחבריו המשכילים, ובנה קלויז עבור ר ישראל שנקרא על שמו \"נעויאזשערס קלויז\".","s":"ליפמן-קובנא"},{"i":33634,"n":"נעטר, יצחק איצק מפוסוואל","b":"רב בפוסוואל. (ממשפחתו וחתומים כבעלים על שער הספר יחד אתו: ר יוסף, ר אברהם הירש).","s":"מתוך קטלוג"},{"i":33635,"n":"נעכיליש, יוסף יוזל מלבוב","f":"אהרן","b":"מראשי קהלת לבוב-חוץ לעיר, חתם-תקל בפנקס הקהלה בענין עיזבון.","s":"בובר-לבוב"},{"i":33636,"n":"נעכיליש, ישעיה מלבוב","f":"אהרן","b":"מראשי קהלת לבוב, חתם-תקד על כרוז ותקנה.","s":"בובר-לבוב"},{"i":33637,"n":"נעכעס, שלמה מיכאל מאמריקה","k":"בעל אלפא ביתא דאבות","b":"רב בלוס אנג'לס-תרץ. חיבר גם \"מעט שמן\" לוס אנג'לס תרץ, \"שמן ראש\". פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט, \"שערי ציון\" - ירושלים תרפא. ?? לא באוצר - בחלקו ??","s":"אמריקה; אוצר כתבי עת-לוין"},{"i":33638,"n":"נעכעס, שמעון מוילנא","b":"ממנהיגי קהילת וילנא. חתן ר אלחנן דיין, גיסו של יחזקאל פיבל מדרעטשין. חתניו: ר טודרוס בן יצחק איזיק קאסעל - פרנס וילנא, ר רפאל בן נטע דייכס.","s":"עיר וילנא ח\"א"},{"i":33639,"n":"נעמיאש, שלום מארץ ישראל","dt":"תצג - כח כסלו","dp":"מרוקו","b":"סוחר שהגיע למרוקו ושם נהרג עק\"ה.","s":"טולדנו-נר המערב"},{"i":33640,"n":"נעמן, יום טוב מביירות","b":"רב בביירות-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":33641,"n":"נעמן, משה (בשאני)","dt":"תשמא","dp":"ישראל","b":"רב ומלמד תשב\"ר בטריפולי, עלה לארץ וכיהן כרב במושב חצב, על מקום ר יצחק לוזון.","s":"מלכי חי\"ל-מרציאנו"},{"i":33642,"n":"נעקדו על קידוש ה' קהילת סערענטש הונגריה וביניהם הגה\"צ רבי משה קליין זצוק\"ל הי\"ד בעמח\"ס \"שמחת משה\"","dt":"א סיון תש\"ד"},{"i":33643,"n":"נפאמניאשצי, אברהם חיים מבטורין","f":"דובער","k":"בעל קצות השלחן","bp":"הלוסק-פלך מינסק","b":"רב באטורין-פלך צרניגוב-תרנה.","s":"אוצר הרבנים 1081; אהלי שם"},{"i":33644,"n":"נפוסי, יצחק מספרד ואלגיר","bt":"קי","dt":"קפ - בערך","b":"מחכמי מיורקה-ספרד ומקורב למלכות, נאנס להתנצר בפוגרום שנת קנא, ברח לאלג'יר והגיע לבג'איה, התכונן לעלות לארץ - כדי לטהר עצמו בברכת הרשב\"ץ - לא ידוע אם הגיע לארץ.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33645,"n":"נפלבוים, נחמן יצחק מניו יורק","k":"בעל מנחה ליעקב גורדו","bt":"תרך","bp":"מינסק","b":"תלמיד \"קלויז בלומקעס\" במינסק, מורה במוסקבה. היגר לארה\"ב-תרמח והיה מורה לעברית. משורר. חיבר \"מנחה להרמן ברנשטין\". פרסם שיר ב\"אהלי שם\". הניח שירים בכת\"י.","s":"דור וחכמיו-א\"ש-ו"},{"i":33646,"n":"נפתלי","f":"דוד","k":"בעל בן דוד","b":"גדול בנגלה ונסתר,עניו,מגדולי אמסטרדם-ת\"ע","s":"אוצר הרבנים 16103"},{"i":33647,"n":"נפתלי בן יעקב אבינו","dt":"ה תשרי"},{"i":33648,"n":"נפתלי בער מליטויסק","f":"ישכר בעריש","dt":"תרנא - כח טבת","b":"רב בליטויסק","s":"אוצר הרבנים 16151"},{"i":33649,"n":"נפתלי הירש מברלין","f":"דוד פרעגער","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין.","s":"תולדות אנשי השם-לנדסהוט"},{"i":33650,"n":"נפתלי הירש מהורודוק","f":"אריה ליב","b":"אב\"ד הורודוק ובנו ר מתתיה מאויטאן (אבי משפחת שטראשון) על מקומו אחריו. נכד ר אהרן סגל הלוי - חתנו של ר יוסף יוסקי מדובנא בעל \"יסוד יוסף\". אחיו - ר יהודה קלצעס מוילנא.","s":"שם הגדולים השלישי"},{"i":33651,"n":"נפתלי הירש מהרבורג","f":"גומפריך","b":"רב בהרבורג-תקס.","s":"מתוך קטלוג"},{"i":33652,"n":"נפתלי הירש מפינטשוב ולובלין","f":"בנימין וולף או שמואל","k":"ר הירש ר הישל'ס","dt":"תמב - כב אלול","dp":"לובלין","b":"חתן ר השל מקראקא ולובלין וכונה ר הירש ר השל'ס. רב בפינטשוב-תלה, לובלין. מחותן עם ר שמואל קיידנובר המזכירו בספרו \"ברכת הזבח\". מתלמידיו: ר יוסף מסעניץ בעל \"ראש יוסף\" והביא מתורת רבו בספרו. הסכים על תנ\"ך אמשטרדם, ועל \"האשל\" - תלח בכינוס ועד ארבע ארצות בלובלין. בנו ר יעקב נפטר בחייו. הניח צוואה בכת\"י ונמצאה באוצר הספרים של שזה\"ה.","s":"אוצר הרבנים 16168; בית העלמין בוילנא-קלויזנר"},{"i":33653,"n":"נפתלי הלוי מלונדון","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":33654,"n":"נפתלי הלוי משלוניקי","dt":"תמג","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-54"},{"i":33655,"n":"נפתלי הלוי משלוניקי - א","b":"מגדולי חכמי שאלוניקי-שצ\"ה","s":"אוצר הרבנים 16126"},{"i":33656,"n":"נפתלי הרץ","f":"חנוך הניך","b":"רב-שנת ת\"נ","s":"אוצר הרבנים 16113"},{"i":33657,"n":"נפתלי הרץ","f":"שמואל פרנס מבריסק","b":"נכד ר משה ר הללס (ולא ר אהרן זליג בעל \"עמודי שבע\" שהיה דודו). בנו - ר הלל בעל \"בית הלל\". אחיו - ר משה מאך, גיסו - ר יהושע חריף בעל \"מגיני שלמה\".","s":"אוצר הרבנים 16154; בובר-זולקוא"},{"i":33658,"n":"נפתלי הרץ","f":"הרש מפרג","s":"אוצר הרבנים 16157"},{"i":33659,"n":"נפתלי הרץ (הירצקא) מבריסק","f":"מנחם? או אבא","k":"בעל פירוש למדרש רבה","dt":"שמב - יז ניסן","dp":"לבוב","b":"מגדולי דורו, רב בבריסק-שיח, למברג?. חיבר פירוש על המדרש-קראקא שכט, תשובה ממנו בשו\"ת הרמ\"א. (ראה גם ר נפתלי הרץ מלבוב). בנו - ר מאיר.","s":"אוצר הרבנים 16160,16166; פין-כנסת ישראל; בריסק-עיר תהלה; בובר-לבוב; מצבות קדש-לבוב"},{"i":33660,"n":"נפתלי הרץ אשכנזי מראווא","f":"משה מברוד","b":"נכד ר נפתלי הירץ מלמברג הנקרא \"רבי ר הירץ\"-נכד ר משה חריף. תלמיד המגיד ממזריטש. ביקר אצל ר אלימלך מליזנסק שהחזיר לו ביקור בראווא. חתן ר ישראל איסר מזולקוא-פרנס ד' ארצות. רב בזולקוא-תקב (בתחילה ראב\"ד אצל ר נפתלי הרץ בן מרדכי הורביץ, ואח\"כ דיין אצל ר צבי הירש בן שמשון מייזלש). רבה הראשון של ראווא. מתורתו ב\"נפש יהודה\". חתנו ר נתן באבד מיברוב. גיסו (נשואים לשתי אחיות) - ר משה פנחס מסוירז וזולקוא. חתם על החרם הגדול בזולקוא-תקיא לטובת ר יונתן איבשיץ. הסכים על\"אותות למועדים\" תקיב, ספר העקרים תקלב, \"עבודת המלך\" תקל, \"שיחת חולין\" תקלה, ועוד. מחותן עם בעל \"עטרת צבי\" המזכירו בספרו.","s":"אלפסי; בובר-זולקוא"},{"i":33661,"n":"נפתלי הרץ הכהן (הוכפלד)","f":"חיים משה","b":"נכד ר אהרן שמואל בעל \"וצוה הכהן\". חתן ר יצחק צבי הלברשטם מאוסטרהא בן ר דב בר ממזריטש וטוטשין. הו\"ל את ספר זקנו יחד עם דודו ר משה הכהן.","s":"אוסטרהא ריג,רס"},{"i":33662,"n":"נפתלי הרץ הכהן מאשכנז וסופיה","f":"יצחק הכהן מסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה עם אביו, דיין אצל ר בנימין בן מאיר הלוי מסופיה-רצב עם ר אהרן בן יוסף סטן הרופא. שאלה ממנו לר תם ן יחיא.","s":"רוזניס-תורכיה-א"},{"i":33663,"n":"נפתלי הרץ הכהן מגלוגא ואוסטרהא","f":"חיים מגלוגא","bp":"גלוגא","dt":"תקנו - כד טבת","dp":"שדה לבן","b":"מצאצאי ר נפתלי כץ מאוסטרהא פוזנן ופפד\"מ. חתן ר מרדכי (בנו של ר יהודה ליב מאוסטרהא פינסק וסלוצק, וחתנו של ר יוזפא מאוסטרהא). רב באוסטרהא על מקום ר אברהם משלם זלמן, שדה לבן-תקלח. בניו: ר אשר ענזיל מאוסטרהא, ר אברהם מאוסטרהא, ר אהרן שמואל בעל \"וצוה הכהן\", ר יוסף יוזפא נחמן מאוסטרהא, ר יצחק מימפולא, ר משה ור מאיר.","s":"אוצר הרבנים 16213; אוסטרהא סח,ריג"},{"i":33664,"n":"נפתלי הרץ הכהן מקנטשוגה","b":"רב בטיסמניץ-תרעט.","s":"וונדר-גליציה ח\"ג"},{"i":33665,"n":"נפתלי הרץ הכהן משאריגרד","b":"חתן ר מאיר מרגליות בעל \"מאיר נתיבים\". רב בשאריגרד-תקע. מתורתו בספר חותנו. הניח מתורתו בכת\"י.","s":"אוצר הרבנים 16215; אוסטרהא קסז; בובר-לבוב"},{"i":33666,"n":"נפתלי הרץ הלוי מטרניגרד","f":"שמואל הלוי","b":"רב בטרניגרד-תקכ. חתן ר יעקב יהושע בעל \"פני יהושע\" ?.","s":"אוצר הרבנים 16220"},{"i":33667,"n":"נפתלי הרץ הלוי מיפו","dt":"תרסב - יד סיון","b":"גדול בנגלה ונסתר,רבה הראשון של יפו-תרמ\"ט. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר הרבנים 16219; אוצר כתבי עת-לוין"},{"i":33668,"n":"נפתלי הרץ הלוי מלבוב","b":"מחכמי לבוב, חתם-תקד על כרוז ותקנה.","s":"בובר-לבוב"},{"i":33669,"n":"נפתלי הרץ הלוי מרצפערד","f":"זילברמן, נפתלי הרץ","dt":"תרכט - כג סיון","dp":"ירושלים","b":"מרבני שלוניקי, עלה לא\"י, דיין בירושלים","s":"אלפסי"},{"i":33670,"n":"נפתלי הרץ חריף","b":"מחדושיו בספר אחיו \"עולת אהרן\".","s":"איטליה גירונדי-נ יג"},{"i":33671,"n":"נפתלי הרץ מאויבן","b":"רב באויבן-ר\"ס,סופיה","s":"אוצר הרבנים 16159"},{"i":33672,"n":"נפתלי הרץ מאוסטרהא","f":"יואל פיבש","dt":"תקיז - כה ניסן","dp":"אוסטרהא","b":"בנו של רבה של אוסטרהא. פרנס באוסטרהא יחד עם ר שמואל ר יעקב'ס. בניו מגדולי אוסטרהא.","s":"אוסטרהא צח"},{"i":33673,"n":"נפתלי הרץ מבירז","b":"תלמיד הגר\"א. רב בבירז-תקע על מקום ר אברהם שלמה בן גרשון, ור נחום בן אברהם קצנלנבוגן על מקומו אחריו. היה דודו זקנו של ר נפתלי הרץ קלצקין-תלמיד בעל \"פני משה\".","s":"אוצר הרבנים 16162; ליטא; אהלי שם"},{"i":33674,"n":"נפתלי הרץ מבליענץ","f":"שלמה זלמן","b":"רב בבליענץ","s":"אוצר הרבנים 16161"},{"i":33675,"n":"נפתלי הרץ מווארקי","f":"יהונתן","b":"רב בווארקי-תק\"ל","s":"אוצר הרבנים 16164"},{"i":33676,"n":"נפתלי הרץ מוויאין-ליטא","b":"רב בוויאין(ליטא)","s":"אוצר הרבנים 16163"},{"i":33677,"n":"נפתלי הרץ מוילנא","f":"ישראל איסר","b":"חתן ר יוסף בן אליהו פעסעלעס. גביר מראשי קהילת וילנא. חתם בהסכמה ליסוד ישיבת וולוזין-תקסט. אביו של הגביר ר ישראל איסר מוילנא.","s":"עיר וילנא ח\"א"},{"i":33678,"n":"נפתלי הרץ מזולקוא","b":"חריף,מרביץ תורה בזלקווא-ת\"ק","s":"אוצר הרבנים 16165"},{"i":33679,"n":"נפתלי הרץ מזולקוא","f":"חנוך הניך מזלקווא","dt":"תצא - אב","dp":"זולקוא","b":"רב בזולקוא. מתורתו ב\"אור יקרות\" לגיסו ר יוסף בנימין זאב משינאווא, וב\"פלפולא חריפתא\" זולקוא תצו. נפטר בחיי אביו. בנו - ר יצחק (נפטר צעיר), חתנו - ר יהודה א\"ש מביאלא בן ה\"פנים מאירות\".","s":"אוצר הרבנים 16210; בובר-זולקוא"},{"i":33680,"n":"נפתלי הרץ מזולקוא","f":"יוסף בנימין זאב וולף","dt":"תקכז - יא אלול","dp":"זולקוא","b":"מחכמי זולקוא.","s":"בובר-זולקוא"},{"i":33681,"n":"נפתלי הרץ מזולקווא","f":"שמואל מבריסק או אהרן","dt":"שצח - ה אייר","dp":"זולקווא","b":"מחכמי זולקווא. בנו - ר הלל מוילנא ואה\"ו בעל \"בית הלל\". (לפי בובר-זולקוא שם אביו ר אהרן זליג מזולקוא).","s":"דוקס-אוה למושב-א"},{"i":33682,"n":"נפתלי הרץ מזורובנא","b":"רב בזורובנא-תקס.","s":"וונדר-גליציה ח\"ג"},{"i":33683,"n":"נפתלי הרץ מלבוב","f":"מנחם","k":"רבי הירצקי","dt":"שמה - יז ניסן","dp":"לבוב","b":"ר\"מ בלבוב. חיבר פירוש למדרש - קראקא שכט. (ראה גם: ר נפתלי הרץ מבריסק).","s":"פין-כנסת ישראל"},{"i":33684,"n":"נפתלי הרץ מלבוב","f":"יחיאל מיכל","dt":"תסג - ג כסלו","dp":"לבוב","b":"מראשי קהלת לבוב. נהרג עם אשתו בתו ובנו.","s":"מצבות קדש-לבוב"},{"i":33685,"n":"נפתלי הרץ מלבוב","f":"יהודה זעלקל","b":"דיין בלבוב, חתם-תט עם ר נפתלי הרץ בן יהודה זעלקל, ר נחמן בן מאיר רפפורט, ר יוסף בן יצחק.","s":"בובר-לבוב"},{"i":33686,"n":"נפתלי הרץ מנוברדוק","f":"אברהם אשר הלפרין","b":"נכד ר ישראל איסר מבריסק ונינו של ר אברהם אבא מארי מנוברדוק. רב בנוברדוק על מקום ר אריה ליב בעל \"דברי אריה\". בנו - ר חיים מזיטל.","s":"מרקוביץ-נוברדוק"},{"i":33687,"n":"נפתלי הרץ מסטנוב","b":"רב בסאטנוב","s":"אוצר הרבנים 16170"},{"i":33688,"n":"נפתלי הרץ מסטניסלב","f":"אריה ליבש מבוטאטש","b":"מגדולי נכבדי סטאניסלאב-תק\"ל. חותן ה\"חוות דעת\"","s":"אוצר הרבנים 16173"},{"i":33689,"n":"נפתלי הרץ מסטרליסק","f":"יעקב","dt":"תקל - ז טבת","dp":"לבוב","b":"רב בסטרעליסק","s":"אוצר הרבנים 16172; מצבות קדש-לבוב"},{"i":33690,"n":"נפתלי הרץ מסנוק","k":"ר' נפתלי הרץ הקדוש","b":"עק\"ה,רב בסאניק","s":"אוצר הרבנים 16169"},{"i":33691,"n":"נפתלי הרץ מפילא","dt":"תקיח- ב ניסן","b":"רב בפילא, ברלין. היה אחד הדיינים שנתמנו לפסוק במחלוקת היעב\"ץ ור יונתן איבשיץ.","s":"אוצר הרבנים 16177; דוקס-אוה למושב"},{"i":33692,"n":"נפתלי הרץ מפרישטיק","b":"רב בפרישטיק","s":"אוצר הרבנים 16175"},{"i":33693,"n":"נפתלי הרץ מפרשבורג","b":"רב בפרשבורג-ש\"כ","s":"אוצר הרבנים 16174"},{"i":33694,"n":"נפתלי הרץ מצפת","dt":"תקצז","dp":"צפת","b":"מחכמי צפת. נהרג ברעידת האדמה-תקצז.","s":"פרומקין-תח\"י"},{"i":33695,"n":"נפתלי הרץ מקוואלי","b":"רב בקוולי-תק\"כ","s":"אוצר הרבנים 16179"},{"i":33696,"n":"נפתלי הרץ מראדיוילישיק","b":"חתן ר יקותיאל זוסמן מראזאליא. רב בראדיוילישיק.","s":"אוצר הרבנים 16181; אהלי שם"},{"i":33697,"n":"נפתלי הרץ מראווא","f":"משה מברודי","k":"ר הירץ ר איסרס","b":"רב בראווא. חתן הנגיד ר ישראל איסרל (מועד ארבע ארצות). רב בזלוקוא. עמד לצדו ר יונתן איבישץ במחלוקת.","s":"וונדר-גליציה ח\"ג"},{"i":33698,"n":"נפתלי הרץ מרדוביץ","f":"דב בער","dt":"תעב - ג חשון","dp":"לבוב","b":"רב בראדוויץ(=רדוביץ), ר\"מ בלבוב.","s":"אוצר הרבנים 16180; מצבות קדש-לבוב; בובר-לבוב"},{"i":33699,"n":"נפתלי הרץ מרדיויל","dt":"תקצו","b":"מחכמי ברודי, רב ברדיויל, למברג-תקעח.","s":"וונדר-גליציה ח\"ג"},{"i":33700,"n":"נפתלי הרץ מריטובה","k":"בעל אילה שלוחה","bt":"תקמג","bp":"ריטובה","dt":"תקפח","b":"רב בריטובה. חיבר גם \"מי כיור\".","s":"ליטא"},{"i":33701,"n":"נפתלי הרץ רורקריש מלובלין","f":"אפרים פישל זיסקינד","dt":"תקפח - כו אדר","dp":"לובלין","b":"נכד אב\"ד טרניגרד, חתן הרב מטומשוב. מחכמי לובלין.","s":"לקורות היהודים בלובלין"},{"i":33702,"n":"נפתלי הרצל","k":"נפתלי הרצל מזידטשוב","b":"רב-שנת תר\"כ","s":"אוצר הרבנים 16208"},{"i":33703,"n":"נפתלי הרצקא מצוזמיר","f":"אברהם","b":"רב בצאזמיר","s":"אוצר הרבנים 16178"},{"i":33704,"n":"נפתלי הרש הכהן מברדיטשוב","f":"ישראל חריף","b":"מו\"צ בברדיטשוב-תק\"ס","s":"אוצר הרבנים 16217"},{"i":33705,"n":"נפתלי הרש הכהן מסופיה","f":"יצחק","b":"רב קהלת האשכנזים בסופיה-רצג על מקום ר בנימין הלוי בן מאיר שעבר לשלוניקי.","s":"רוזניס-תורכיה-ב"},{"i":33706,"n":"נפתלי הרש מסוחטשוב","dt":"תקפד - כג אדר","b":"רב בסוחאטשוב","s":"אוצר הרבנים 16171"},{"i":33707,"n":"נפתלי חנהלס מצפת","bt":"תרטז","b":"נקרא ע\"ש אמו חנה חנהל'ס. מצאצאי הבעש\"ט. מרביץ תורה בצפת-תרע. חיבר הספד בשם \"קול נהי\" על ר דוד משה מצ'ורטקוב - אודסה תרסד.","s":"אוצר הרבנים 16114; אהלי שם"},{"i":33708,"n":"נפתלי יעקב הכהן מקירליבאבא","f":"משה בן נפתלי יעקב","dt":"תשלה","dp":"בני ברק","b":"תלמיד ר משה גרינוולד בעל \"ערוגת הבשם\". חתן ר חיים בער ורצברגר מבורשה. רב בקירליבאבא-בוקובינה, ניצל מהשואה ואחריה רב מיהאי-פאלווה ודיין בביה\"ד להתרת עגונות ברומניה. עלה לארץ-תשח והתישב בחיפה, ובני ברק.","s":"טרנסילבניה"},{"i":33709,"n":"נפתלי כונה הירש מליסא","f":"יצחק זליג","b":"דיין בליסא-תקך, חתם עם ר צבי הירש ברלין וחבריו על מכתב לר דוד ברלין באה\"ו.","s":"מתוך קטלוג"},{"i":33710,"n":"נפתלי מברזן","b":"רב בברזן, בנו ר צבי ותשובה אליו בשואל ומשיב-תריג.","s":"וונדר-גליציה ח\"ג"},{"i":33711,"n":"נפתלי מהרדענקי וזולקוא","f":"יעקב יודא ליב","dt":"תקט - כט ניסן","dp":"זולקוא","b":"רב בהרדענקי.","s":"בובר-זולקוא"},{"i":33712,"n":"נפתלי מוילנא","f":"יואל הרץ בן ישראל","dt":"תריח","b":"ר\"מ בישיבת מייליס בוילנא ומגיד בקלויז היסוד. חיבר חדושים על המשנה - בכת\"י.","s":"ליטא"},{"i":33713,"n":"נפתלי מטרנופול","b":"רב בטרנופול--תרמח.","s":"וונדר-גליציה ח\"ג"},{"i":33714,"n":"נפתלי מלבוב","f":"צבי הירש","dt":"תיח - כא תשרי","dp":"לבוב","b":"תלמיד בעל הסמ\"ע. דיין בלבוב.","s":"אוצר הרבנים 16090; מצבות קדש-לבוב; בובר-לבוב"},{"i":33715,"n":"נפתלי מלובלין","f":"שלמה צורף","dt":"תיד - כח תמוז","dp":"לובלין","b":"מחכמי לובלין. נהרג עק\"ה.","s":"לקורות היהודים בלובלין"},{"i":33716,"n":"נפתלי מלובצי","b":"דומ\"צ בלובצי","s":"אוצר הרבנים 16089"},{"i":33717,"n":"נפתלי מליפטא-מיקלוש","b":"רב בליפטא-מיקלוש, נזכר בשו\"ת החת\"ס. חתנו - ר משה בן ישראל איסר אולמן.","s":"שטמפן - הרצוג"},{"i":33718,"n":"נפתלי מסנטוב","b":"מו\"צ בסנטוב-תק\"ס","s":"אוצר הרבנים 16091"},{"i":33719,"n":"נפתלי מפיררה","k":"בעל ביאור לרבנו בחיי","b":"רב בפיררה. חיבר ביאור לרבנו בחיי על התורה - בכת\"י.","s":"איטליה גירונדי-נ י"},{"i":33720,"n":"נפתלי מפרמישלא","dt":"תפב - ד טבת","dp":"לובלין","b":"מחכמי פרמישלא. נהרג עק\"ה.","s":"לקורות היהודים בלובלין"},{"i":33721,"n":"נפתלי מקושטא וסרייבו","f":"מנצור","b":"גביר בקושטא ומקורב לפחה ומושל סרייבו, סייע לחדוש התישבות היהודים בסרייבו בשנת שעד.","s":"רוזניס-תורכיה-ג"},{"i":33722,"n":"נפתלי מרוזניאטוב","b":"רב ברוזניאטוב אצל הרב האחרון ר יהודה צבי קורן.","s":"וונדר-גליציה ח\"ג"},{"i":33723,"n":"נפתלי משאט","b":"רב בשאט","s":"אוצר הרבנים 16092"},{"i":33724,"n":"נפתלי משלוניקי","f":"יוסף","b":"מחכמי שלוניקי, הו\"ל \"אמרות טהורות\" - שלוניקי שנד-אחרי, יחד עם ר שלמה בן יוסף אשכנזי.","s":"רוזניס-תורכיה-ג"},{"i":33725,"n":"נפתלי ן, משה מחלב","f":"דוד","b":"מבעלי המסורה. סופר ונקדן קדום בחלב-ד'תרפב (922), בן זמנו של ר אהרן בן אשר ובר פלוגתא שלו. ישנם מאות שנויים בין נוסח המסורה שלו לבין כתר אר\"ץ, והרמבם ואחריו הרד\"ק העדיפו את נוסח בן אשר.","s":"ארזי הלבנון"},{"i":33726,"n":"נפתלי נתן נטע משיניבה","f":"מנחם מנדל","k":"בעל קישוטי כלה","b":"צדיק נסתר בשיניבה, ונתפרסם ע\"י ר שמואל שמלקא מניקלשבורג, וצדיקי דורו ובהם ר אלימלך מליזנסק ביקרו אצלו. רב בניקלשבורג. נחשב לאחד מל\"ו צדיקים. חיבר כתבים שרובם אבדו. נדפס \"קישוטי כלה\" למברג תרלג. וכן \"עולת תמיד\" על הסידור פשמישל תרנו. חתנו ר יהודה ליביש דומיניץ מגרודזיסק.","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":33727,"n":"נפתלי סגל מרימנוב","b":"שו\"ב ברימנוב-תקכא - תשובה אליו רח\"ב.","s":"וונדר-גליציה ח\"ג"},{"i":33728,"n":"נפתלי צבי דוב מקראקא","f":"הרמ\"א","b":"מגדולי חכמי קרקא-ש\"פ","s":"אוצר הרבנים 16257"},{"i":33729,"n":"נפתלי צבי הירש מאשכנז","f":"חיים","k":"בעל לקוטי נפתלי","b":"חיבר \"לקוטי נפתלי\" פיורדא תקכט.","s":"איטליה גירונדי-נ יב"},{"i":33730,"n":"נפתלי צבי הירש מויטבסק וטבריה","f":"אליעזר מחווסטוב","b":"עלה לארץ-תקמו והתישב בטבריה. חתם \"שמש דעיר הקדש טבריה\".","s":"אלפסי"},{"i":33731,"n":"נפתלי צבי הירש מטבריה","f":"שאול","b":"חתם על כתב שליחות-תקסו.","s":"אלפסי"},{"i":33732,"n":"נפתלי צבי מוכיח מאויהל","dt":"תקלב - יד סיון","b":"מו\"צ באויהעל","s":"אוצר הרבנים 16274"},{"i":33733,"n":"נפתלי צבי מסטולין וטבריה","f":"יעקב מאניפולי","dt":"תרכד - כז אלול","dp":"טבריה","b":"נינו של הבעשט. חתן ר ישראל מפיקוב. מקורב לאדמורי סטולין-קרלין וסאווראן. עלה לארץ עם הוריו והיה ממונה על כולל חסידי וואהלין בטבריה. בשליחות ה\"כולל\" כמה פעמים.","s":"אלפסי"},{"i":33734,"n":"נפתלי צבי מסטרבין","f":"משה","b":"רב בסטרבין","s":"אוצר הרבנים 16256"},{"i":33735,"n":"נפתלי צבי מסקווירא","f":"משה","b":"רב בזארניטש,סקווירא-ת\"ר","s":"אוצר הרבנים 16262"},{"i":33736,"n":"נפתלי צבי מרדיחוב","b":"רב ברדכוב-תר\"ל","s":"אוצר הרבנים 16260"},{"i":33737,"n":"נפתלי צבי מרישא","b":"דיין ברישא-ת\"מ","s":"אוצר הרבנים 16259"},{"i":33738,"n":"נצח, בריש מלמברג","b":"תשובה אליו - קנאת סופרים.","s":"וונדר-גליציה ח\"ו"},{"i":33739,"n":"נצח, ישראל יונה מלבמרג","b":"נכד בעל \"נצח ישראל\" מזמושטש. מחכמי למברג.","s":"וונדר-גליציה ח\"ג"},{"i":33740,"n":"נציונישוק = קהילה","b":"ליטא - מחוז ראקישוק. כפר של יהודים עובדי אדמה. לפני מלחה\"ע ה-I ישבו בה כ-20 משפחות יהודים - ורק יהודים, לפני השואה 3 משפחות בלבד רובם היגרו לדרום אפריקה ולאמריקה. הרב המקומי היה גם הוא חקלאי והיה גם שו\"ב גם לאנשי יוז'ינט הסמוכה.","s":"ליטא"},{"i":33741,"n":"נצר ן, עובדיה עבדאללה מדמשק","b":"רב בגובר-שן - ליד דמשק. נזכר ב\"דברי יוסף\" לר יוסף סמברי.","s":"ארזי הלבנון"},{"i":33742,"n":"נקאר, צאלח יוסף חיים מבגדד","b":"תלמיד ר נסים כדורי. שו\"ב מחכמי בגדד, עלה לארץ. חיבר חדושי תורה בכת\"י.","s":"ארזי הלבנון"},{"i":33743,"n":"נקאש, אברהם מאלגיר","dt":"תקסו - לפני","b":"רב בקצמטינא, ונזכר ב\"אשכבתא דרבנן\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":33744,"n":"נקאש, דוד מאלגיר","k":"בעל כוזרי השני","bt":"קפ","dt":"רן - בערך","b":"מחכמי ורבני קצמטינא. חיבר \"כוזרי שני\"","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33745,"n":"נקאש, משה מתונס","k":"בעל תורת משה","b":"מחכמי תונס-[תק']. תלמיד ר אברהם טייב, וחברו של בנו - ר חיים טייב. וספרו \"תורת משה\" נדפס עם ספרי רבו ובנו.","s":"אוצר הרבנים 14952; ארזי הלבנון"},{"i":33746,"n":"נקאש, נסים מאלגיר","dt":"תקסו - לפני","b":"רב בקצמטינא.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33747,"n":"נקאש, נסים מתימן","b":"מחכמי ראדע-תימן בתחילת המאה ה-20. נזכר בקובץ שו\"ת בין חכמי ראדע לחכמי צנעא.","s":"ארזי הלבנון"},{"i":33748,"n":"נר, חיים שמואל מקושטא","b":"מחכמי ורבני קושטא,תלמיד בעל ה\"שדי חמד\"","s":"ארזי הלבנון"},{"i":33749,"n":"נראל, ישראל הכהן מקרמניץ","b":"אחיו בעל \"ברכת טוב\" הביא בספרו חדושים ממנו.","s":"איטליה גירונדי-י מג"},{"i":33750,"n":"נראל, משה ירמיה הכהן מקרמניץ","f":"אלעזר וולשוס","k":"בעל ברכת טוב","dt":"תיט - יז אייר","b":"תלמיד המהרש\"א. רב ורופא בקרמניץ, נארול(=נראל), עבר לאשכנז בגזירות ת\"ח, רב במיץ. חיבר \"ברכת טוב\". חברו של הרב העשל ותלמיד ר יעקב אביו של הרב העשל. חיבר גם \"מגילת סתרים\" בנו - ר טוביה הרופא בעל \"מעשה טוביה\" הדפיס את ספר אביו.","s":"איטליה גירונדי-מ מד; אוצר הרבנים 15514; אוסטרהא יב-ד; רוזניס-תורכיה-ד"},{"i":33751,"n":"נרבוני משה בן יהושע","bt":"1300","dt":"ה'קכח 1368","s":"היברובוקס","bk":[["באור לספר מורה נבוכים",""]]},{"i":33752,"n":"נרבוני, אברהם מספרד","f":"יצחק","b":"תלמיד רבינו יונה והרמב\"ן","s":"ארזי הלבנון"},{"i":33753,"n":"נרבוני, אברהם משלוניקי","dt":"רפז - ו תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי אביו של דון וידאל.","s":"עמנואל-שלוניקי"},{"i":33754,"n":"נרבוני, דוד מאלגיר","f":"מבורך בן נתן","bt":"קך","dt":"ר - בערך","b":"רב ודיין בברשך-אלגיר. חתם על שטר בי\"ד המובא בשו\"ת הריב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33755,"n":"נרבוני, דוד מאלגיר","bt":"תם","dt":"תק - בערך","b":"רב באלגיר. עדות ממנו בעניני בדיקת הריאה בקונטרס מנהג ארג'יל לר יהודה עייאש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33756,"n":"נרבוני, וידאל משלוניקי","dt":"רצג - ד אלול","dp":"שלוניקי","b":"מחכמי שלוניקי-רפ.","s":"עמנואל-שלוניקי"},{"i":33757,"n":"נרבוני, יהודה משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי-שץ.","s":"עמנואל-שלוניקי"},{"i":33758,"n":"נרבוני, יצחק מאלגיר","b":"רב באלגיר ונזכר ב\"אשכבתא דרבנן\" לקהלת אלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33759,"n":"נרבוני, יצחק מספרד","k":"בעל צרור הכסף","b":"מגדולי הראשונים בחכמי ספרד,מראשי הדיינים בברצלונה-שנת כ'","s":"אוצר הרבנים 10851"},{"i":33760,"n":"נרבוני, ישראל מקושטא","b":"מחכמי ארץ ישראל, עבר לקושטא-שנות ה-ש'.","s":"אוצר הרבנים 12002; רוזניס-תורכיה-ג"},{"i":33761,"n":"נרבוני, מרדכי מאלגיר","f":"יצחק","dt":"תקנד","dp":"אלגיר","b":"תלמיד ר יהודה עייאש וכתב הקדמה לספרו \"קול יהודה\". רב באלגיר. הואשם ע\"י המוסלמים בפגיעה בדתם והוצא לו להמיר דתו - סירב ונשרף עק\"ה. חיבר ספרים ואבדו. חיבר הקדמה לספרו רבו - \"קול יהודה\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33762,"n":"נרבוני, מרדכי מאלגיר","bt":"[שפ]","dt":"תן - בערך","b":"רב באלגיר. חיבר דיני אונות הריאה כמנהג אלגיר.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33763,"n":"נרבוני, צמח מירושלים - הנכד","f":"שלמה נרבוני","b":"מחכמי קושטא, עלה לירושלים-תז.","s":"אוצר הרבנים 17584; רוזניס-תורכיה-ד"},{"i":33764,"n":"נרבוני, צמח מקושטא - הזקן","f":"ישראל נרבוני","dp":"ירושלים","b":"רב בקושטא-שעג ודיין אצל המהרי\"ט - חתם עמו-שעג, עלה לירושלים. תלמידו - ר חיים בנבנישתי בעל \"כנסת הגדולה\". בנו - ר שלמה, ונכדו ר צמח.","s":"אוצר הרבנים 17583; רוזניס-תורכיה-ג; פרומקין-תח\"י"},{"i":33765,"n":"נרבוני, שלום מאלגיר","f":"אברהם","dt":"תסא","b":"רב באלגיר ומראשי הקהלה, וחתם על שטר רכישה לקרקע לבית העלמין \"מדרש\" באלגיר.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33766,"n":"נרבוני, שלמה מירושלים -ב","f":"צמח נרבוני","b":"רב בירושלים-שנת ת'","s":"אוצר הרבנים 18539"},{"i":33767,"n":"נרבוני, שלמה מקושטא וחברון","b":"גביר מחכמי קושטא, עלה לחברון-[של], והיה מחכמי חברון. ר יעקב קאסטרו כותב לו ממצרים בתקיפות ודורש ממנו שישמע בקולו. בנו ר צמח נרבוני.","s":"גליס; אוצר הרבנים 18538; רוזניס-תורכיה-ב; ארזי הלבנון"},{"i":33768,"n":"נריה, אברהם מפרובנס","f":"יוסף","b":"רב באריגש-פרובנס-ן'. הסכים על חרם הרשב\"א ור אבא מרי כנגד לימוד הפילוסופיה יחד עם בנו ר יוסף. מתלמידיו ר יעקב בלקיירי. חיבר ספרים ואבדו.","s":"אלופי יעקב א-קלא"},{"i":33769,"n":"נריה, משה צבי","r":"מייסד ומנהיג ישיבת כפר הרא\"ה","bt":"שבט תרעג","dt":"כסליו תשנו","b":"ראש ישיבת כפר הרוא\"ה.","s":"מעיינותיך גליון 41 עמוד 37","bk":[["אסיף לחג הסוכות",""],["ארץ מורשה - על ארץ ישראל ונגד הנסיגה ממנה",""],["דבר השמיטה",""],["מאורות נריה - קובץ לזכרו שיחותיו תולדותיו ועוד",""],["מלחמות שבת - סוגית מלחמה בשבת",""],["מסכת הנזיר - קוים לדמותו של הנזיר רבי דוד כהן",""],["נר למאור - הגדה של פסח",""],["על משכנות הרועים",""],["ענבי פתחיה - עיונים ובירורים בגופי הלכות",""],["פרקי ולוז'ין",""],["צניף מלוכה - פרקי ובירורי הלכות עם הקמת מדינת ישראל",""]]},{"i":33770,"n":"נרציזנפלד, שמעון יעקב מנמירוב","b":"רב בנמירוב-תרמו.","s":"וונדר-גליציה ח\"ג"},{"i":33771,"n":"נ\"ש, יעקב ליפמן מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט.","s":"תולדות אנשי השם-לנדסהוט"},{"i":33772,"n":"נ\"ש, שמעון מפרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח.","s":"פרשבורג-וינגרטן"},{"i":33773,"n":"נשיא, אשטרוק משלוניקי","dt":"רצב - ב תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי","s":"עמנואל-שלוניקי"},{"i":33774,"n":"נשיא, בנימין הקראי מדמשק","b":"ראש קהלת הקראים בדמשק-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":33775,"n":"נשיא, דוד הרופא הקראי מדמשק","b":"רופא קראי בדמשק-שנות ה-ת' - בזמן רבנות ר יאשיהו פינטו.","s":"רוזניס-תורכיה-ד"},{"i":33776,"n":"נשיא, חיים מקושטא","dt":"תרס - יט כסלו","b":"מגדולי חכמי קושטא,אב\"ד-תרס\"ב","s":"ארזי הלבנון"},{"i":33777,"n":"נשיא, שלמה משלוניקי","dt":"שס - טו טבת","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":33778,"n":"נשיא, שמואל מפורטוגל וקושטא","dt":"שכט","dp":"קושטא","b":"אחיו של דון יוסף נשיא. מיושבי פיררה-איטליה, עבר לקושטא. נספד מאת ר משה אלמושנינו.","s":"גאון-יהודי המזרח; רוזניס-תורכיה-ב"},{"i":33779,"n":"נשיא-מינדיס, דון דוד מקנדיא","k":"בעל הודאת בעל דין","bp":"ספרד","b":"מחכמי האי קנדיא(=קריטא, כרתים)-קצ. אחיו של דון יוסף נשיא.","s":"אוצר הרבנים 4929; גאון-יהודי המזרח; פין-כנסת ישראל"},{"i":33780,"n":"נשיא-מינדיס, חנה גרציה","f":"דייגו","bt":"רע","bp":"פורטוגל","dt":"שכח","dp":"קושטא","b":"מראשי קהלת הספרדים בקושטא, פעלה רבות למען היהודים. חתנה - דון יוסף נשיא.","s":"גאון-יהודי המזרח; פין-כנסת ישראל"},{"i":33781,"n":"נשיא-מינדיס, יוסף-יואנו מקוויס","k":"דון יוסף נשיא=בן פור","bp":"פורטוגל","dt":"שלט - ז אב","dp":"קושטא","b":"בן אנוסים ששב ליהדות, חתן דונה חנה גראסיה מנדיס נשיא, עבר לונציה, קושטא. מקורב לשולטן, נשיא האי נקסוס-שכ, יוצא ובא בחצר המלך, בא להשקיט אצל המלך עלילת דם. חיבר \"בן פורת יוסף\" בספרדית ותורגם לעברית ע\"י ר יצחק עונקירה. הקים דפוס בבילוידיר. נפטר ללא ילדים.","s":"איטליה גירונדי-י רו; אוצר הרבנים 8465; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ב"},{"i":33782,"n":"נשיא-מינדיס, משה (שמואל)","b":"בעלה של דונה גראסיה. הגיע לקושטא עם משפחתו.","s":"רוזניס-תורכיה-ב"},{"i":33783,"n":"נשיא-מינדס, ריינה","f":"דונה גראציה","b":"אשתו של דון יוסף נשיא, ובתה של דונה גראציה. פעלה למען עם ישראל לאחר פטירת בעלה-דון יוסף נשיא. הקימה בית דפוס בקושטא.","s":"רוזניס-תורכיה-ג"},{"i":33784,"n":"נשר, יצחק","f":"אברהם אדלר","dt":"תשלד - ד שבט","b":"דיין בתל אביב","s":"אוצר הרבנים 10854"},{"i":33785,"n":"נתן","b":"רב-שנת תק\"ל","s":"אוצר הרבנים 16279"},{"i":33786,"n":"נתן","b":"מגדולי דורו-ש\"צ","s":"אוצר הרבנים 16280"},{"i":33787,"n":"נתן","f":"מאיר","k":"בעל שערי התפיסה","b":"מגדולי הראשונים-ד'תתק\"ס","s":"אוצר הרבנים 16337"},{"i":33788,"n":"נתן","f":"מנחם","b":"מגדולי הראשונים-שנת ל'","s":"אוצר הרבנים 16339"},{"i":33789,"n":"נתן","f":"שמואל","k":"בעל זכרון טוב","b":"חיבר \"זכרון טוב\" בכת\"י (די רוסי) ואולי הוא המחבר \"מבחר המאמרים\" ליוורנו.","s":"איטליה גירונדי-נ יז"},{"i":33790,"n":"נתן אהרן מאושפיצין","b":"רב באושפיצין-תר\"י","s":"אוצר הרבנים 16375"},{"i":33791,"n":"נתן אופניאל-אופציאל","b":"מגדולי בעלי התוספות-ד'תתק\"נ","s":"אוצר הרבנים 16314; אלופי יעקב א-תתקעו"},{"i":33792,"n":"נתן איזיק מנפולומיץ","b":"רב בנפולומיץ.","s":"וונדר-גליציה ח\"ג"},{"i":33793,"n":"נתן אריה מהורבשוב","f":"שלמה דוב","b":"רב בהורבאשוב-תק\"ס","s":"אוצר הרבנים 16378"},{"i":33794,"n":"נתן אשר משלוניקי","dt":"תמה","dp":"שלוניקי","b":"רב בק\"ק אשכנזים בשלוניקי.","s":"זכרון שלוניקי-55"},{"i":33795,"n":"נתן בילאייעווקער מויטקא","f":"אריה ליב","b":"תלמיד בעל התניא, ונבחר ע\"י רבו ללמוד עם בנו ר דב לימים האדמור האמצעי. רב בוויטקא-תקץ. בניו: ר דוד, ר מאיר. אביו החזיק במגלת יוחסין עד המהר\"ל ונקראו בשם \"גור אריה\" ע\"ש ספרו של זקנם המהר\"ל (כתב היוחסין אבד בשריפה).","s":"אוצר הרבנים 16305; אהלי שם"},{"i":33796,"n":"נתן בן יחיאל מרומה","bt":"1035","dt":"ד'תתסג 1103","s":"היברובוקס","bk":[["הערוך (יקר הערך)",""],["הערוך (עם מוסף ערוך, המעריך, הפלאה שבערכין)",""],["הערוך (עם שלחן הערוך)",""],["מוסף הערוך",""],["ספר הערוך",""]]},{"i":33797,"n":"נתן גאון מארץ ישראל","f":"אברהם","b":"מגאוני ארץ ישראל בשנת ד'תתנה (1095)","s":"גליס"},{"i":33798,"n":"נתן גאון סורא","f":"יהודה בן שמואל גאון","b":"נתמנה לגאון סורא-ד'תרפז על מקום ר יום טוב הכהן, אך נפטר טרם שהחל בכהונתו ונבחר על מקומו רב סעדיה גאון. אחיו של ר חנינא אבי רב שרירא גאון.","s":"ארזי הלבנון"},{"i":33799,"n":"נתן גבאי","b":"מחכמי חברון, בשנת תקכג חתם על כתב שליחות ר רחמים בג'איו ור יצחק זאבי.","s":"גליס"},{"i":33800,"n":"נתן גבריאל מפרשבורג","b":"שו\"ב וחזן בפרשבורג-תסט.","s":"פרשבורג-וינגרטן"},{"i":33801,"n":"נתן גזע ישי מאלגיר","bt":"קע - בערך","dt":"רמ - בערך","b":"תלמיד הרשב\"ש באלגיר. רב בתנס-אלגיר (לא תונס) מקורב לרשב\"ש, תשובה אליו מאת ר יוסף ששפורטש - בשו\"ת הרשב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":33802,"n":"נתן גרשון מזולקוא","f":"בצלאל","dt":"תצה - ה אייר","dp":"זולקוא","b":"גביר מחכמי זולקוא, חתם-תסד על תקנת הקהלה, ועל קיום בחירת ראשי הקהל. אולי הוא היה גיסו של ר חנוך הניך ונזכר אצל היעב\"ץ שהיה מחותן עם ר אריה ליב גיסו של היעב\"ץ.","s":"בובר-זולקוא; אוצר הרבנים 4466"},{"i":33803,"n":"נתן הדיין מספרד","b":"דיין בקורדובה, ועמד בראש מתיבתא \"כנסת המדרש\", כאשר נפדה ר חנוך - אחד מארבעת השבויים, פינה ר נתן את כסאו לטובת ר חנוך (רבו של ר שמואל הנגיד).","s":"ארזי הלבנון"},{"i":33804,"n":"נתן הכהן מאלגיר","f":"עלי","bt":"קס","dt":"רל - בערך","b":"רב באלגיר בזמן הריב\"ש והרשב\"ש, ונזכר בספריו כ\"חברנו הותיק\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":33805,"n":"נתן הכהן מאשקלון","f":"מבורך","b":"דיין באשקלון בשנים 1136-1142,","s":"גליס"},{"i":33806,"n":"נתן הכהן מאשקלון","f":"עלי","b":"מחכמי אשקלון בנו של עלי הכהן הפרנס במאה ה-יב.","s":"גליס"},{"i":33807,"n":"נתן הכהן מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב.","s":"תולדות אנשי השם-לנדסהוט"},{"i":33808,"n":"נתן הכהן מזאלושין","f":"זאב וולף חריף מלאסק","b":"מו\"צ בזאלושיץ-תרי, לא נתמנה לרב בלאסק על מקום אביו בגלל שהיה בעל מום.","s":"אוצר הרבנים 16323; עיר לאסק וחכמיה"},{"i":33809,"n":"נתן הכהן משלוניקי","f":"יצחק","dt":"רץ - כח ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":33810,"n":"נתן הלוי","f":"זאב וואלף הלוי","b":"רב-שנת ת\"י","s":"אוצר הרבנים 16327"},{"i":33811,"n":"נתן הלוי מירושלים","f":"חיים","dt":"תמו","dp":"פרנקפורט","b":"מחכמי ירושלים, שליח העדה האשכנזית.","s":"גליס"},{"i":33812,"n":"נתן הלוי מפולנאה","f":"שמואל הלוי","b":"חתן ר יואל הלפרין מאוסטרהא. רב בפולנאה-תפ.","s":"אוצר הרבנים 16326; בובר-לבוב"},{"i":33813,"n":"נתן ויידל מפפד\"מ (תאומים)","f":"שמעון למלין","dt":"של","b":"דיין בפפד\"מ אצל ר אליעזר טריווש. מאבות משפחת תאומים - שמם של צאצאיו.","s":"וונדר-גליציה ח\"ה"},{"i":33814,"n":"נתן חיימזון מפראן","f":"חיים","k":"בעל אבן בוחן","bp":"אורלא-ליד ביאליסטוק","b":"מצאצאי בעל הט\"ז. דרשן, רב בפראן(=פרען)-תרג. חתנו - ר מרדכי בן צבי אפשטין מהורדנא.","s":"אוצר הרבנים 16291; ליטא; שם הגדולים השלישי; פרידנשטין - הורדנא"},{"i":33815,"n":"נתן יעקב","b":"רב בדערעטשקא-תקפ\"א","s":"אוצר הרבנים 16389"},{"i":33816,"n":"נתן מאויבן","f":"מתתיהו","bp":"בלגרד","dt":"תקמד - כז חשון","dp":"אויבן","b":"רב באויבן(=בודפשט) על מקום ר ישכר בר אופנהיים, ודיין אצלו ר יוחנן בנעט. מבניו: ר דוד גינצבורג מבורשטין, ר יהודה.","s":"גרינוולד-סלובקיה והונגריה"},{"i":33817,"n":"נתן מאוסטרהא","f":"דוד טביל מאוסטרהא","dt":"תקמ.. - כט שבט","dp":"אוסטרהא","b":"פרנס באוסטרהא.","s":"אוסטרהא קנט"},{"i":33818,"n":"נתן מאלטונא","k":"בעל חדושים לקדשים","b":"דיין באלטונה-תק\"ל","s":"אוצר הרבנים 16283"},{"i":33819,"n":"נתן מאשכנז","b":"מגדולי חכמי אשכנז-ד'תת\"ק","s":"אוצר הרבנים 16278"},{"i":33820,"n":"נתן מבבל וצפון אפריקה","f":"יצחק","b":"הגיע מבבל ולמד אצל ר חושיאל בקירואן.","s":"ארזי הלבנון"},{"i":33821,"n":"נתן מבורשטשוב","b":"רב בבורטשוב. מתורתו בספר נכדו ר משה הורביץ מוולוטשיסק \"עמק השירים\".","s":"וונדר-גליציה ח\"ג"},{"i":33822,"n":"נתן מבלחוב","b":"רב בבאלחוב-ת\"ק","s":"אוצר הרבנים 16285"},{"i":33823,"n":"נתן מברוד","dt":"תסב - יד אב","b":"דיין בברודי","s":"אוצר הרבנים 16284"},{"i":33824,"n":"נתן מוונגרוב","dt":"תרמא - כט אדר","b":"תלמיד ר מנחם מנדל מקוצק. רב בוונגרוב.","s":"אוצר הרבנים 16288; אלפסי"},{"i":33825,"n":"נתן מוורנה","b":"רב בוורנה(=וארנא). בנו - ר משה אליהו דאמיע מליבאוי-חתן ר יצחק זאב אהרונוביץ מהאזנפוט.","s":"אובצינסקי-קורלנד"},{"i":33826,"n":"נתן מוישטיניץ","b":"אב\"ד וישטיניץ, הסכים-תקפב על 'גופי הלכות' לר יעקב יפה (שהיה חתן דודו)."},{"i":33827,"n":"נתן מזולקוא","b":"פרנס בזולקוא. חתנו - ר משה אלחנן הלפרין.","s":"בובר-זולקוא"},{"i":33828,"n":"נתן מזולקוא","k":"בעל אמרי נועם","b":"מצאצאי התוי\"ט. חיבר \"אמרי נועם\" זולקוא תקיד.","s":"בובר-זולקוא"},{"i":33829,"n":"נתן מזולקוא","b":"חתנו - ר מרדכי שהובא מתורתו ב\"פלפולא חריפתא\" זולקוא שצו.","s":"בובר-זולקוא"},{"i":33830,"n":"נתן מטבריה","f":"יהודה","k":"ליבלי ראובן'ס","b":"חסיד ברסלב, תלמיד ר נתן. עלה לארץ-תרלה והתישב בטבריה. כתב מכתבים ובהם תיאור של חסידות ברסלב בארץ ישראל.","s":"אסף-נאחז בסבך"},{"i":33831,"n":"נתן מטריקולה","f":"יעקב","b":"רב בטריקולה-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":33832,"n":"נתן מטרנקטליש","f":"מאיר מקרקסונה","k":"בעל ספר העזר","b":"מגדולי הפוסקים בדורו,מרביץ תורה בדרום צרפת-ד'תתק\"צ","s":"אוצר הרבנים 16321"},{"i":33833,"n":"נתן מירושלים","b":"מחכמי ירושלים, מוזכר אצל ר משולם מוולטרא בספר מסעו משנת רמא.","s":"גליס"},{"i":33834,"n":"נתן מירושלים","f":"רפאל","b":"מחכמי ירושלים, בשנת תכו בשליחות באירופה כשליח עדת האשכנזים יחד עם ר מרדכי אשכנזי.","s":"גליס"},{"i":33835,"n":"נתן מלאסק","f":"אברהם","b":"רב בלוסק-תק על מקום ר אליקים גץ בן מאיר ור פנחס זליג בעל \"עטרת פז\" על מקומו אחריו.","s":"אוצר הרבנים 16289; עיר לאסק וחכמיה"},{"i":33836,"n":"נתן מלבוב","b":"דיין בלבוב, חתם-תעז על שטר מכירה (ואולי הוא ר נתן בן שמעון מלבוב).","s":"בובר-לבוב"},{"i":33837,"n":"נתן מלבוב","f":"שמעון","b":"דיין בלבוב, חתם-תפד עם ר נתן נטע בן זלמן סגל, ר אברהם כץ, חתם-תפה עם ר נתן נטע בן זלמן, ר אהרן זליג בן שמואל איש צבי,","s":"בובר-לבוב"},{"i":33838,"n":"נתן מלובלין","f":"יצחק איזיק","dt":"תקמב - כג אייר","dp":"לובלין","b":"פרנס מחכמי לובלין.","s":"לקורות היהודים בלובלין"},{"i":33839,"n":"נתן מלימנוב","b":"תלמיד הדברי חיים מצאנז.","s":"אלפסי"},{"i":33840,"n":"נתן ממאקווא","f":"שמואל","dt":"תקפו - טז תשרי","b":"תלמיד החוזה מלובלין, ור שמואל מקארוב. חתן ר חיים חייקל מאמדור. הוכתר כאדמור - אך המשיך ללכת בבגדי רבנים ונסע לאדמורי הדור ובעיקר ר שמחה בונם מפשיסחא. בנו ר יוחנן, וחתנו ר יצחק אבי ר פישל חתן ר אברהם משה מפשיחסא.","s":"אוצר הרבנים 16340; אלפסי"},{"i":33841,"n":"נתן ממצרים","f":"שמואל","b":"רב קדמון במצרים-ד'תתק (1140), וכנראה היה סופר הישיבה (בגדד). יחד עם חברו ר חלפון החזיקו ברבי יהודה הלוי בעברו במצרים בדרכו לארץ, ור יהודה כתב בספרו מכתב תהלה לר נתן סופר הישיבה.","s":"ארזי הלבנון"},{"i":33842,"n":"נתן מסטוטשין","k":"ר נתקי ליטוואק","dt":"תרכז - כה אלול","b":"מחשובי בני ה\"חבורה\" של ר שמחה בונם מפשיסחא, תלמיד ר מנחם מנדל מקוצק, ובעל חדושי הרי\"ם.","s":"אלפסי"},{"i":33843,"n":"נתן מסיציליה","b":"רב במעסינא-סיציליא-נ' (1290). תלמיד ר אברהם אבולעפיה ונזכר בספר רבו \"אור השכל\".","s":"ארזי הלבנון"},{"i":33844,"n":"נתן מסמיאטיץ","dt":"תרלג - כז תמוז","b":"דיין בסמיאטיץ","s":"אוצר הרבנים 16290"},{"i":33845,"n":"נתן מספרד","f":"מאיר מטרנקטיליש","k":"בעל שער התפיסה","b":"מגדולי הרבנים בדורו. מחכמי ספרד - ד'תתקן (1190). רב בפירפוניאן-פרובנס, אביו של ר משה הפרחי וזקנו של ר אישתורי הפרחי בעל \"כפתור ופרח\". הרמב\"ן מזכירו בחדושיו בשם \"מורי\", ובספר התרומות לר שמואל הסרדי מזכיר את שער התפיסה שחיבר ר נתן.","s":"ארזי הלבנון"},{"i":33846,"n":"נתן מפיורדא וירושלים","dt":"תרח - י שבט","dp":"ירושלים","b":"מחכמי פיורדא, ירושלים.","s":"פרומקין-תח\"י"},{"i":33847,"n":"נתן מפלאצק","b":"תלמיד ר שניאור זלמן מליאדי, בנו ר דב בר ונכדו ר מנחם מנדל מליובאויטש.","s":"אוצר הרבנים 16351; אלפסי"},{"i":33848,"n":"נתן מפפד\"מ וירושלים","b":"רב בפרג (וי\"א פפד\"מ), ירושלים, נזכר במכתב השל\"ה.","s":"פרומקין-תח\"י"},{"i":33849,"n":"נתן מפרנקפורט וירושלים","bp":"אשכנז","dp":"ארץ ישראל","b":"מחכמי אשכנז, מוזכר בתרומת הדשן ל ישראל איסרלין ובעוד מספרי הראשונים, עלה לארץ ישראל אחרי קפב.","s":"גליס; אוצר הרבנים 16351"},{"i":33850,"n":"נתן מקלרמונט","f":"יוסף","b":"רב בקלרמונט-צרפת במאה ה-14-13 (ויש דעות שונות היכן העיר). חיבר פירוש להגדה של פסח (בכת\"י פארמא).","s":"מוריה 22-ה-ז"},{"i":33851,"n":"נתן מתתיהו הכהן מקמניץ","f":"יצחק הכהן","b":"רב בקמניץ-ליטא-תק.","s":"אוצר הרבנים 16394,15783"},{"i":33852,"n":"נתן ן, יצחק מספרד","f":"קלונימוס בן יהודה נת","k":"בעל מאיר נתיב","b":"מחכמי ספרד-לפני הגירוש, פרובאנס-רנ, רב בונציה, (ולפי רש\"י פין - היה מחכמי איטליה וחיבר את ספרו בשנת ה'קצו). חיבר \"מאיר נתיב\" - קונקורדנציה יחד עם קרובו מרדכי הרופא, חיבר גם \"מבצר יצחק\", ו\"תוכחת מתונה\" - כנגד המומר ירונימו (די רוסי)","s":"איטליה גירונדי-י רח; אוצר הרבנים 11463; ארזי הלבנון; פין-כנסת ישראל"},{"i":33853,"n":"נתן נטע","f":"יוסף","s":"אוצר הרבנים 16410"},{"i":33854,"n":"נתן נטע","f":"שלום בן אשר משארשוב","k":"נטיל הגדול","b":"חתן ר עזריאל הורביץ מלובלין (ראש ברזל). נפטר ללא ילדים.","s":"ברוורמן-אנשי שם"},{"i":33855,"n":"נתן נטע הכהן (כהנא) מלבוב","f":"מרדכי","b":"רב בלבוב-תס. בנו ר אהרן. (יש המשער כי הוא נתן בן אליהו והוא זה שנרשם שנפטר בשנת שלב.","s":"אוצר הרבנים 16325; בובר-לבוב"},{"i":33856,"n":"נתן נטע הכהן מלבוב הזקן","f":"אליהו כהנא","dt":"שלב - כה כסלו","dp":"לבוב","b":"אב\"ד ברעזאן וראש ישיבה בלבוב. זקנו של ר נתן נטע כהנא מאוסטרהא. בנו ר משה מרדכי.","s":"אוצר הרבנים 16324; אוסטרהא; מצבות קדש-לבוב; בובר-לבוב"},{"i":33857,"n":"נתן נטע הלוי מקעלין","b":"רב בקעלין-תק\"ל","s":"אוצר הרבנים 16436"},{"i":33858,"n":"נתן נטע מאוסטרהא","f":"אברהם-חתן ר ייב\"י","b":"נכד ר ייב\"י. מחכמי אוסטרהא.","s":"אוסטרהא רו"},{"i":33859,"n":"נתן נטע מאוסטרהא","f":"יהודה מאוסטרהא","dt":"תק.. - ד סיון","dp":"אוסטרהא","b":"מחכמי אוסטרהא.","s":"אוסטרהא קסה"},{"i":33860,"n":"נתן נטע מאוסטרהא","f":"יעקב ישראל","dt":"תקעב - ח אלול","b":"נכד ר יהושע בן ר י\"פ הוצק. מחכמי אוסטרהא, גבאי בח\"ק ורשום בפנקס.","s":"אוסטרהא רט"},{"i":33861,"n":"נתן נטע מאוסטרהא","f":"שמואל שמלקא הלוי מאו","dp":"אוסטרהא","b":"דיין מחכמי אוסטרהא-תקן ומיושבי הקלויז הגדולה. הסכים על \"כנפי יונה\", ועוד. בנו ר שמואל שמלקא.","s":"אוסטרהא רכג"},{"i":33862,"n":"נתן נטע מברוד","f":"אליהו","b":"עלה לטבריה. ודבק בר אברהם מקליסק.","s":"וונדר-גליציה ח\"ו"},{"i":33863,"n":"נתן נטע מדוסאט","b":"רב בדוסאט","s":"אוצר הרבנים 16401"},{"i":33864,"n":"נתן נטע מהגנאו וירושלים","f":"יהודה ליב","k":"בעל מאורי אור","b":"רב בהגנאו, מחבורת רבי יהודה החסיד ועלה לירושלים. בשליחות-תמח קהלת ירושלים באירופה, ובהיותו בפרג מינה את הגביר ר דוד אופנהיים לנשיא קהלת ירושלים.","s":"רוזניס-תורכיה-ד"},{"i":33865,"n":"נתן נטע מהורודשץ","k":"ר' נתן נטע מגילובסקי","bt":"תרכ","b":"רב בהורודשץ-תרנ\"ח","s":"אוצר הרבנים 16420"},{"i":33866,"n":"נתן נטע מהילדסהים","f":"ישעיה מהילדסהים","b":"רב בהילדסהיים-ת\"מ","s":"אוצר הרבנים 16424"},{"i":33867,"n":"נתן נטע מחברון","f":"סעדיה","k":"בעל אור תורה","dt":"תרלא","dp":"אלכסנדריה","b":"מחכמי חברון, בשנת תקצד בשליחות העדה הספרדית יחד עם קהילת חבד באירופה ושהה שם 10 שנים, בשובו נבחר לרב באלכסנדריה. חיבר \"אור תורה\" שלוניקי תרי, ועוד.","s":"גליס; שא\"י"},{"i":33868,"n":"נתן נטע מחעלם","f":"אברהם או מרדכי מבריס","k":"אדמור מחלם-נטע שעשוע","dt":"תקעב - א שבט","b":"תלמיד ר מרדכי מנסכיז ור אלימלך מליזנסק. אדמור בוולדובה, חלם. חיבר \"נטע שעשועים\".","s":"אוצר הרבנים 16428; אלפסי; בריסק-עיר תהלה; המבשר תורני גליון 264 עמוד כד","bk":[["נטע שעשועים - על התורה",""]]},{"i":33869,"n":"נתן נטע מטבריה","f":"אליהו","b":"נכד ר דוד מביחוב. היה בטבריה-תקמט. חתם \"משרת אדמו\"ר ר אברהם מקאליסק\" וגם \"נתן נטע ב\"ר אליהו בהגאון מברודי\". בנו ר דוד אליהו היה חתן ר שאול מהורוקא - נפטר ב כסלו תרכט.","s":"אלפסי"},{"i":33870,"n":"נתן נטע מטורבין","b":"נכד בעל \"מגלה עמוקות\". חתן ר ברוך אברהם רפפורט מוילנא ופיורדא. רב בטורבין. תשובה ממנו בשו\"ת ר חיים הכהן רפפורט. חתנו - ר יוסף תאומים מאוסטרובצה. בנו - ר דב בער מזולקוא.","s":"עיר וילנא ח\"א; אהלי שם"},{"i":33871,"n":"נתן נטע מטרטקוב","f":"שמואל שמלקי","b":"רב בטרטקוב-תקם, אוסטרהא.","s":"וונדר-גליציה ח\"ג"},{"i":33872,"n":"נתן נטע מטרניגרד","f":"זכריה מנדל מקראקא","b":"רב בטרניגרד, הורדנא-תנ. בנו - ר אריה ליב קצנלנבוגן מסלוצק והורדנא (באוצר הרבנים בלבל בין בן וחתן - למעשה היה חתנו ולא בנו). (כמו כן יש בלבול בינו לבין ר אריה ליב קצנלנבוגן מברודי).","s":"אוצר הרבנים 16405"},{"i":33873,"n":"נתן נטע מלבוב","f":"ראובן","dt":"תקכד - אחרי","b":"דיין בלבוב, חתם-תקד עם ר אריה ליב רפפורט, ר ישכר בער איגרא, חתם-תקו עם ר יוסף בן מנחם מאניש, ר מרדכי בן צבי הירש, ועוד, חתם-תקט עם ר חיים רפפורט ועוד.","s":"בובר-לבוב"},{"i":33874,"n":"נתן נטע מליטומירסק","b":"רב בליטומירסק. בנו - יעקב זלמן.","s":"מתוך קטלוג"},{"i":33875,"n":"נתן נטע מנוברדוק","dt":"תקץ - בערך","b":"ראב\"ד ומו\"צ בנוברדוק בזמן ר דוד בעל \"גליא מסכת\".","s":"מרקוביץ-נוברדוק"},{"i":33876,"n":"נתן נטע מסאבטיטש","b":"רב בסאבאטיטש-תקע\"ה","s":"אוצר הרבנים 16397"},{"i":33877,"n":"נתן נטע מפהליפובה","b":"גביר מראשי קהלת פאהיליפאווע-שנות ה-תק. חתנו - ר יעקב בן יהודה בעל פדויות יעקב.","s":"פין-קריה נאמנה"},{"i":33878,"n":"נתן נטע מפילא","f":"ישעיה","b":"אב\"ד פילע(=פילא)-מחוז פוזנא-תקץ. תשובות אליו בשו\"ת ר עקיבא איגר. ר עקיבא שלח אליו מכתב עם קמע (נדפס ב\"שנות דור ודור\"). הגהות ממנו על שו\"ע ב\"כרם שלמה\".","s":"אוצר הרבנים 16408"},{"i":33879,"n":"נתן נטע מצאנץ (צאנז?) ופרשבורג","dt":"תקז - יח אייר","dp":"פרשבורג","b":"מצאצאי ר איציק מנהיימר בן ר הירש קצנלנבוגן מפפאלץ. חתן ר מרדכי מוכיח אשכנזי מפרשבורג. רב בפרוינקירכן, דיין בפרשבורג. גיסו של ר משה לבוב-אב\"ד פרשבורג. (באוצר הרבנים תאריך פטירתו - ב תמוז תקלב).","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 16450; אבני בית היוצר-וייס"},{"i":33880,"n":"נתן נטע מצפת וירושלים","f":"סעדיה","dt":"תרט - ו טבת","dp":"ירושלים","b":"מחכמי צפת, ירושלים. חתם-תקעה על מינוי הגבאים בצפת ובהם ר ישראל משקלוב.","s":"אוצר הרבנים 16411; פרומקין-תח\"י"},{"i":33881,"n":"נתן נטע מקלביעל","b":"רב בקלביעל","s":"אוצר הרבנים 16399"},{"i":33882,"n":"נתן נטע מקראקא","f":"חיים מנחם מן מוינה","b":"דיין בקראקא-תכ. חתם-תי ו-תיד על פסק דין.","s":"אוצר הרבנים 16400; בובר-לבוב"},{"i":33883,"n":"נתן נטע מקראקא","b":"תלמיד ר חיים הכהן בעל \"טור ברקת\", \"יון מצולה\" על גזירות ת\"ח. מחדושיו ב\"ברכת טוב\" לר משה נראל.","s":"איטליה גירונדי-נ ב"},{"i":33884,"n":"נתן נטע מראדזיל","b":"מקובל,רב בראדזיל-תקי\"ז","s":"אוצר הרבנים 16398"},{"i":33885,"n":"נתן נטע מרוזלא","b":"רב ברוזלא. הניח פירוש על ספרא דצניעותא - תשובה אליו בשו\"מ.","s":"וונדר-גליציה ח\"ו"},{"i":33886,"n":"נתן נטע משקלוב וירושלים","f":"מנחם מנדל","dt":"תרז - כב תשרי","dp":"ירושלים","b":"מחכמי ליטא, בשנת תקמט עלה לארץ ישראל עם ר סעדיה. בשנת תקצד במלחמת הפלחים נשדד ונעקרו עיניו. בשנת תקצח בשליחות לליטא כשליח האשכנזים בצפת. בשנת תרו חתם עם גדולי ירושלים. חתנו - ר יצחק דוד ברי\"ל לעווי, נכדו ר מנדל לעווי, חתן נכדתו - ר נפתלי ראהלר.","s":"גליס"},{"i":33887,"n":"נתן נטע סגל מלבוב","f":"שלמה זלמן","b":"דיין בלבוב אצל ר חיים הכהן רפפורט, חתם-תקא עם ר אברהם סגל מטיסמניץ, ר מנחם מנדל בן ברוך סגל.","s":"אוצר הרבנים 16404; בובר-לבוב"},{"i":33888,"n":"נתן נטע צבי הלוי","b":"רב בהידאל-מאש-תר\"ל","s":"אוצר הרבנים 16470"},{"i":33889,"n":"נתן פייטל","f":"יוסף","k":"מאה\"ו","b":"שמש ונאמן אה\"ו-תקסב, חתם עם ר אליעזר לאזי מברלין.","s":"מתוך קטלוג"},{"i":33890,"n":"נתן פייטל (אפרים) מברלין","f":"חיים בן אפרים מהמבור","dt":"תקלה","dp":"ברלין","b":"גביר בברלין ומקורב למלך. חתן ר נפתלי הירש מירלש פרנקל, וגיסו של ר דוד פרנקל בעל \"קרבן העדה\" והבטיח לממן דיין נוסף לקהילה כשמונה גיסו לראב\"ד (משום שהיו לו קרובים רבים שלא יכל לדונם ונצרכו לדיין נוסף). יסד בימ\"ד בברלין בשם \"פייטל היינע אפרים-שע לעהר אנשטאלט\".","s":"תולדות אנשי השם-לנדסהוט; פין-כנסת ישראל"},{"i":33891,"n":"נתן פייטל מקראקא","b":"מגדולי חכמי קרקא-ש\"מ","s":"אוצר הרבנים 16465"},{"i":33892,"n":"נתן שמואל מירושלים","f":"יוסף","b":"מחכמי ירושלים, מוזכר בספר המסע של ר משולם מוולטרא בשנת רמא כאחד הדיינים.","s":"גליס"},{"i":33893,"n":"נתן, אליהו מקאליב","b":"רב בקאליב","s":"אוצר הרבנים 2299"},{"i":33894,"n":"נתן, דוד","b":"מחשובי תלמידי ה\"שדי חמד\"","s":"ארזי הלבנון"},{"i":33895,"n":"נתן, כתריאל אהרן מקורשאן","f":"הלל","k":"בעל כתר המלך","bt":"תרו","bp":"לצקובה-ליטא","dt":"תרפב - יח כסלו","b":"חתן ר משה יצחק סגל מליטא. רב בקורשאן, בידקה ספוטקין(=סאפאצקין), אוגוסטוב-תרמ על מקום חותנו.","s":"אוצר הרבנים 12448,2943; ליטא; אובצינסקי-קורלנד; מרקוביץ-ראסיין"},{"i":33896,"n":"נתנאל","b":"מגדולי הראשונים-שנת ס'","s":"אוצר הרבנים 16476"},{"i":33897,"n":"נתנאל (נתן) וולף הלוי (הנביא)","b":"בן אחותו של ר יהודה החסיד, ומראשי שיירת רבי יהודה החסיד-תנט. חזר לאירופה והשתמד בנורדלינגן-תסח ושינה שמו לפרנסיסקו לותירוס פיליפי.","s":"רוזניס-תורכיה-ד"},{"i":33898,"n":"נתנאל - מקלל התאנה","b":"מקובל מחכמי ספרד, בן דורו של הרמבם. קיבל את כינויי לאחר שקילל אילן תאנים. מצאצאיו - ר מכיר בן יצחק בעל \"אבקת רוכל\".","s":"ארזי הלבנון"},{"i":33899,"n":"נתנאל אלנטע הנגיד ממצרים","b":"נגיד במצרים-ד'תתקך על מקום ר שמואל אבומנצור, ור זוטא על מקומו אחריו.","s":"רוזניס-תורכיה-ד"},{"i":33900,"n":"נתנאל גאון מארץ ישראל","f":"צדקה","b":"מחכמי ארץ ישראל בתקופת הגאונים, מכתב ממוען אליו משנת תתעד (1114).","s":"גליס"},{"i":33901,"n":"נתנאל דובראוונר","b":"בנו - ר אליהו וולפסון.","s":"ברוורמן-אנשי שם"},{"i":33902,"n":"נתנאל הוראדנער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז.","s":"עיר וילנא ח\"א"},{"i":33903,"n":"נתנאל הכהן מפוכא","b":"רב בפוכא-תקפ\"ז","s":"אוצר הרבנים 16484"},{"i":33904,"n":"נתנאל הלוי מאיטליה","f":"משלם הלוי","k":"בעל ספר מעבר","dt":"תקלא - טו ניסן","b":"גדול בנגלה ונסתר,מרביץ תורה בפאדובה,רב במודנא. חיבר ספר מעבר - אמשטרדם. בנו ר צבי שעלה לירושלים והיה בשליחות עם ר אברהם אליעזר הלוי ונתקבל לרב בטריאסט (נפטר תקסו).","s":"אוצר הרבנים 16485; איטליה גירונדי-נ י"},{"i":33905,"n":"נתנאל הלוי מכורדיסטן (ברזני)","bt":"[ש]","dt":"שע - בערך","b":"רב ומקובל בכפר ברזאן בכורדיסטן. יתכן שעלה עם בנו ר שמואל לארץ ישראל ופגש את ר חיים ויטאל ומכונה ר אבא שהגיע מאשור כמסופר ע\"י ר חיים.","s":"ארזי הלבנון"},{"i":33906,"n":"נתנאל הלוי ממודנא","f":"משלם","bp":"מודנא","b":"רב בפדובה, לוגו, פיסארו, ציינטו, מודנא. מתשובותיו ב\"פחד יצחק\", \"שמש צדקה\" ועוד. תלמידיו ר יצחק חי מוסאטי חיבר קינה לכבודו ב\"שירי זמרה\".","s":"איטליה גירונדי-נ ה"},{"i":33907,"n":"נתנאל הלוי ממצרים","f":"משה","dt":"ד'תרפא","b":"רב וראש ישיבה בקהיר על מקום אביו בשנים ד'תתקכ (1160). היה בעל מעמד מיוחד לאחר היחלשות משרת הנגיד במצרים, ר בנימין מטודלה פגשו במצרים והעיד ר ר נתנאל היה מאנשי חצרו של המלך. והיה קשור גם עם ר דניאל בן חסדאי ראש הגולה בבגדד.","s":"ארזי הלבנון"},{"i":33908,"n":"נתנאל מאוסטרהא","f":"יעקב","dt":"תנד - ט אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא.","s":"אוסטרהא כח"},{"i":33909,"n":"נתנאל מוילנא וירושלים","f":"יעקב","dt":"תרכו","dp":"ירושלים","b":"מחכמי ירושלים, נפטר במגפת הכולירה בירושלים-תרכו.","s":"פרומקין-תח\"י"},{"i":33910,"n":"נתנאל מטולטשין","b":"רב בטולטשין","s":"אוצר הרבנים 16496 ב'"},{"i":33911,"n":"נתנאל מירושלים","b":"ראב\"ד בירושלים-תס\"ה","s":"אוצר הרבנים 16477"},{"i":33912,"n":"נתנאל מירושלים","f":"שלמה זלמן","b":"רב בירושלים, בהיותו בונציה-תמה הסכים על \"מעיל שמואל\".","s":"פרומקין-תח\"י"},{"i":33913,"n":"נתנאל מלובלין","f":"משלם","dp":"לובלין","b":"ראש קהילת לובלין.","s":"לקורות היהודים בלובלין"},{"i":33914,"n":"נתנאל מנירדין","f":"שלמה זלמן","b":"רב בנירדין, עלה לירושלים, חתנו היה ר יוסף ביילר. בשנת תסא היה בוינה ומסר לר דוד אופנהיים את כתב הרבנות של ירושלים. בשנת תסה היה בונציה ושם הסכים על \"מעיל שמואל\" לר שמואל אוטולינגא.בגמר שליחותו נשאר במצרים.","s":"גליס"},{"i":33915,"n":"נתנאל מספרד","f":"יוסא אלמולא","k":"ר' נתנאל הרופא","b":"מגדולי מתרגמי פירוש המשניות להרמב\"ם,מחכמי ספרד-שנת ע'","s":"אוצר הרבנים 16495"},{"i":33916,"n":"נתנאל מקושטא","f":"שלום מספרד","b":"ממונה על החזקות בקושטא-שס עם חבריו ר משה משלם הלוי, ר יום טוב ן יעיש ועוד.","s":"רוזניס-תורכיה-ג"},{"i":33917,"n":"נתנאל מקינון","b":"מגדולי בעלי התוספות,מנהל ישיבה גדולה בקינון-ד'תתק\"נ","s":"אוצר הרבנים 16493"},{"i":33918,"n":"נתנאל מתימן","f":"ישעיה","k":"בעל מדרש אור האפילה","b":"מכונה גם \"והב בן גיאת\". רב בתימן. חיבר \"נור אלצלאם\" - \"מאור האפלה\" בעברית וערבית. חיבר גם פירוש למגילת אסתר (נדפס בספר זכרון לר יצחק נסים).","s":"אוצר הרבנים 16483; ארזי הלבנון"},{"i":33919,"n":"נתנאל מתימן","f":"פיומי","k":"בעל גן השכלים","b":"נגיד היהודים בתימן בזמן הרמבם, ואגרת תימן של הרמבם נשלחה לבנו ר יעקב. חיבר \"בסתאן אלעקול\" - \"גן השכלים\" שנכתב לחזק את האמונה בין היהודים, וכן חיבר לוח עיבור שנים המבוסס על מחזור של רמז שנים. בנו ר יעקב נגיד בתימן על מקומו אחריו. אחיו ר דניאל שחיבר פיוטים.","s":"ארזי הלבנון"},{"i":33920,"n":"נתנאל מתימן","f":"יצחק","k":"בעל ספר המרגלית","b":"רב בתימן במאה ה-15. חיבר גם \"כתאב אלתאליף\", \"שרח אלחליב\" ועוד.","s":"ארזי הלבנון"},{"i":33921,"n":"נתנזון יוסף שאול בן אריה ליבוש","bt":"1808","dt":"ה'תרלה 1875","s":"היברובוקס","bk":[["ביטול מודעה",""],["דברי שאול",""],["יד שאול",""],["ידות נדרים",""],["עדות ביוסף",""],["שואל ומשיב",""]]},{"i":33922,"n":"נתנזון, אריה ליב מוילנא","k":"ליבלי פישעלס","b":"חתן הגביר ר ירוחם פישל בן פסח. מחכמי וילנא.","s":"פין-קריה נאמנה"},{"i":33923,"n":"נתנזון, בנימין מוילנא","f":"נתן נטע","k":"בינה פישל'ס","bt":"1841","bp":"פלונגיאן","dt":"תרא - ד אדר","dp":"וילנא","b":"שם משפחתו ע\"ש אביו - נתן. מצאצאי המהרש\"ל והש\"ך. חתן ר משה בן יושע פאלק מפלונגיאן, ובזיוו\"ש חתן ר ירוחם פישל בן פסח מוילנא (ונקרא פישל'ס ע\"ש). פרנס בוילנא, גבאי בבית החולים יחד עם ר אברהם בן הגר\"א. נספד ב\"פרחי צפון\" לר מרדכי אהרן גינצבורג. וקינה לזכרו מאת אד\"ם הכהן ב\"שירי שפת קדש\". בנו - ר מרדכי מוילנא, חתנו רש\"י פין ונכדו - ר בנימין בן שמואל יוסף פין (=רש\"י פין).","s":"ליטא; עיר וילנא ח\"ב; פין-כנסת ישראל"},{"i":33924,"n":"נתנזון, דוד מברוד","f":"יעקב","b":"רב בברודי. חתנו היה בעל \"משיב כהלכה\".","s":"וונדר-גליציה ח\"ג"},{"i":33925,"n":"נתנזון, זלמן מברזן","f":"אריה ליבש מברזן","bt":"תקף","bp":"ברזן","b":"חתן הגביר ר סנדר מנדל ביק מברודי. הוציא לאור ספר אביו \"בית אל\" ובו אף כמה מחדושיו.","s":"וונדר-גליציה ח\"ג"},{"i":33926,"n":"נתנזון, חיים מפיקאלן וזידיק","f":"אברהם","k":"בעל שפתי חן","bt":"תקצח","bp":"נאוואראן","dt":"תרסד","dp":"זידיק","b":"תלמיד ישיבות שאוולי, איישישוק. רב בפיקאלן, ז'ידיק-תרם על מקום ר משה שלמה לוינברג. בצעירותו עסק גם בציור. חיבר גם \"דברי חן\".","s":"אוצר הרבנים 6081; ליטא; היברובוקס; ראה ערך דברי חן; הדרום קו' לז עמוד 226, פרוייקט השו\"ת","bk":[["דברי חן","מפרשי רמב\"ם"],["שפתי חן",""],["דברי חן [שו\"ת]",""],["שפתי חן [עה\"ת]",""]]},{"i":33927,"n":"נתנזון, יהודה מברוד","f":"יעקב","bt":"תקכה","dt":"תקצב","b":"חתן ר נפתלי הירץ מירוסלב. פרנס בברודי. עשיר ובעל צדקה.","s":"וונדר-גליציה ח\"ג"},{"i":33928,"n":"נתנזון, יוסף מברוד","f":"יצחק","bt":"תקס","dt":"תרמג","b":"מחכמי ברודי וראש הקהל-תקצח.","s":"וונדר-גליציה ח\"ג"},{"i":33929,"n":"נתנזון, יוסף שאול הלוי מלבוב","f":"אריה ליבוש מברזן","k":"בעל שואל ומשיב-השו\"ם","r":"רב ופוסק - לבוב, [למברג]","bt":"תקסח","bp":"ברזן","dt":"תרלה - כז אד\"א","dp":"לבוב","b":"חתן דודו מהרי\"א איטינגא. חיבר עם גיסו ר מרדכי זאב איטינגא \"מפרשי הים\". רב בלמברג אחר הישועות יעקב. סירב לרבנות בריסק. מגדולי המשיבים בדורו. מתנגד לחסידות - ממעריצי הגר\"א ואסר על האדמור מבלז להכנס לעירו. חיבר \"שואל ומשיב\", \"יד יוסף\" למברג תריא. פרסם מאמרים ב\"פליטת סופרים\" - וילנא תרכג, \"תבונה\" - ממל-קניגסברג תרכא. נספד מאת ר בנימין מרייגראד ב\"אבל כבד\" - ירושלים תרלה.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 8981; אוצר כתבי עת-לוין; הגדול ממינסק; מצבות קדש-לבוב; ברוורמן-אנשי שם; בריסק-עיר תהלה; בובר-לבוב; יומא דהילולא; אוצר השירים החיבורים והדרשות של הרי\"ח עמוד 340 הערה 2, שו\"ע מכון ירושלים בתחילתו, אנציקלופדיה לחכמי גליציה חלק ג' עמוד 1031 - 1044; אוצר השירים החיבורים והדרשות של הרי\"ח עמוד 340 הערה 2, שו\"ע מכון ירושלים בתחילתו, אנציקלופדיה לחכמי גליציה חלק ג' עמוד 1031 - 1044, תבונות גליון 23 עמודים 8 - 14","bk":[["יד שאול","מפרשי שו\"ע"],["שואל ומשיב",""],["מפרשי הים, מאירת עינים - בדיקת הריאה, מגן גבורים - שו\"ע או\"ח, מעשה אלפס - רי\"ף",""],["דברי שאול",""],["שואל ומשיב (שו\"ת)",""],["אמרות טהורות",""],["דברי שאול – עדות ביוסף",""],["מנחת שי",""],["שי למורה","מפרשי שו\"ע"],["שואל ומשיב","שו\"ת - אחרונים"],["דברי שאול - עדות ביוסף","מפרשי רמב\"ם"]],"e":"תק\"ע-תרל\"ה","rb":"לבוב, [למברג]","co":{"b":"49.45,24.933333"}},{"i":33930,"n":"נתנזון, יעקב מוארשא","f":"זליג","dt":"תרמד - כד אלול","b":"בעל תואר דוקטור ופרופסור לכימיה. חיבר ספרי מדע בפולנית, עסק בחינוך. הקדיש בצוואתו כסף לקרן למחברי ספרים במדע וספרות.","s":"פין-כנסת ישראל"},{"i":33931,"n":"נתנזון, יצחק","f":"יוסף מברודי","b":"תשובות אליו ב\"שואל ומשיב\"-תרטז.","s":"וונדר-גליציה ח\"ג"},{"i":33932,"n":"נתנזון, יצחק מברוד","f":"יעקב מברודי","b":"חתן ר הירץ ר איסרס מראווא. מחכמי ברודי. זקנו של השו\"מ שהביא דברים משמו בספריו.","s":"וונדר-גליציה ח\"ג"},{"i":33933,"n":"נתנזון, יצחק מברעזן","b":"מגדולי התורה בברעזאן-תק\"ס","s":"אוצר הרבנים 10842"},{"i":33934,"n":"נתנזון, ליב מוילנא","f":"בנימין","k":"ליבלי פישל'ס","dp":"וילנא","b":"גביר מחכמי וילנא. חתן ר פישל בן פסח. הסכים על \"שבט מיהודה\"-תקסג. גיסו של ר בנימין נתנזון. חתנו - הרד\"ל - ר דוד לוריא.","s":"עיר וילנא ח\"א"},{"i":33935,"n":"נתנזון, מרדכי מוילנא","f":"בנימין","k":"בעל אילת השחר","bt":"תקנה","bp":"וילנא","dt":"תרכח - ב תמוז","dp":"טלז","b":"חתן ר יהושע ציטלין, ובזיוו\"ש חתן הגביר ר ברוך שחור ממיר. מגדולי המשכילים בוילנא. חיבר גם מאמר על הקראים בטרוקי - נדפס ב\"דביר\" וילנא 1846, מכתב על דבר שמות אנשים, ועוד. חתניו - רש\"י פין מוילנא, ר ליב קאנצל מטלז ועבר לשם בסוף ימיו.","s":"ליטא; פין-כנסת ישראל; פין-קריה נאמנה"},{"i":33936,"n":"נתנזון, משה מעיר ישן","b":"רב בעיר ישן-הונגריה?. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד.","s":"אוצר כתבי עת-לוין"},{"i":33937,"n":"נתנזון, שלום משדה לבן","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט.","s":"אוצר כתבי עת-לוין"},{"i":33938,"n":"נתנזון, שמואל מפודקמין","f":"יעקב אליעזר","bt":"תרה","dt":"תרעו - כט אדר","b":"חתן הגביר ר מיכאל ציפרס מקראקא. רב בליביטשוב, פודקמין-תרמה יחד עם ר יהושע השל פרנקל-תאומים. נסמך מאת: ר יצחק אהרן איטינגא, ר צבי הירש אורנשטין מלבוב, ר יצחק יהודה שמלקיס מלבוב, ר יהושע מבלז, ר\"ב רפפורט מראווא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 19286; אוצר כתבי עת-לוין; אהלי שם"},{"i":33939,"n":"נתקה","dt":"תרלג - כז תמוז","b":"מו\"צ בוורשה-תק\"צ","s":"אוצר הרבנים 16287"},{"i":33940,"n":"נתקס, מאיר","b":"רב בבריסק","s":"אוצר הרבנים 12910"}];
